(window.TNQ=window.TNQ||[]).push({"terms":{"중대재해":{"d":"산업재해 중 사망자나 다수 부상자가 생기는 등 재해 정도가 심한 경우로 법령이 정한 재해이다.","r":[]},"중대산업재해":{"d":"중대재해처벌법이 정한 재해로, 사망자 1명 이상 등 산업안전보건법의 중대재해와 기준이 다릅니다.","r":["중대재해","중대시민재해"]},"중대시민재해":{"d":"중대재해처벌법에서 공중이용시설이나 공중교통수단 등에서 시민이 사망하거나 다수가 다치는 재해입니다.","r":["중대산업재해"]},"도급인":{"d":"물건의 제조, 건설, 수리, 서비스 제공 등의 업무를 도급하는 사업주이다. 건설공사발주자는 제외된다.","r":[]},"관계수급인":{"d":"도급이 여러 단계에 걸쳐 체결된 경우 각 단계별로 도급받은 사업주 중 고용노동부령으로 정하는 자이다.","r":[]},"건설공사발주자":{"d":"건설공사를 도급하는 자로, 공사의 시공을 주도하여 총괄, 관리하는 자는 제외된다.","r":[]},"건설공사도급인":{"d":"발주자로부터 공사를 최초로 도급받은 수급인이거나 시공을 주도해 총괄·관리하는 자입니다.","r":["건설공사발주자"]},"안전보건총괄책임자":{"d":"도급 사업에서 도급인이 같은 장소 작업의 안전보건 업무를 총괄하도록 지정하는 사람이다.","r":[]},"안전보건관리책임자":{"d":"사업장의 산업재해 예방 업무를 총괄하여 관리하는 사람이다. 안전관리자와 보건관리자를 지휘, 감독한다.","r":[]},"관리감독자":{"d":"사업장의 생산과 직결된 업무를 직접 지휘, 감독하는 부서의 장이나 그 직위에 있는 사람이다. 소속 근로자의 안전보건 업무를 수행한다.","r":[]},"안전관리자":{"d":"안전보건관리책임자를 보좌하고 관리감독자에게 안전에 관한 기술적 사항을 지도, 조언하는 사람이다.","r":[]},"보건관리자":{"d":"사업장에서 근로자의 보건에 관한 기술적 사항에 대해 사업주 또는 관리책임자를 보좌하고 지도, 조언하는 사람이다.","r":[]},"안전보건관리담당자":{"d":"안전·보건관리자를 두지 않는 일정 규모 사업장에서 사업주를 보좌하고 관리감독자에게 조언하는 사람입니다.","r":["안전관리자","보건관리자"]},"산업보건의":{"d":"사업장의 근로자 건강관리를 위해 의사 자격이 없는 보건관리자가 있는 사업장 등에서 선임하는 의사이다.","r":[]},"명예산업안전감독관":{"d":"산업재해 예방을 위해 근로자 또는 단체 추천으로 위촉되어 사업장 점검 등에 참여하는 사람이다.","r":[]},"안전보건관리규정":{"d":"사업장의 안전보건 관리조직, 교육, 작업장 안전 등에 관한 사항을 정해 놓은 규정이다.","r":[]},"산업안전보건위원회":{"d":"사업장의 산업재해 예방 계획 등 중요한 안전보건 사항을 심의, 의결하기 위해 근로자와 사용자가 같은 수로 구성하는 위원회이다.","r":[]},"노사협의체":{"d":"공사금액이 일정 규모 이상인 건설공사에서 위원회를 대신해 근로자와 사용자 위원이 구성하는 협의기구입니다.","r":["산업안전보건위원회"]},"특별교육":{"d":"유해하거나 위험한 작업에 채용하거나 작업내용을 바꿀 때 일반 교육에 더해 추가로 하는 안전보건교육입니다.","r":["직무교육"]},"직무교육":{"d":"안전보건관리책임자, 안전관리자, 보건관리자 등이 직무 수행에 필요한 지식을 위해 받는 신규교육과 보수교육이다.","r":[]},"안전보건진단":{"d":"산업재해 예방을 위해 사업장의 안전, 보건 상태를 점검하고 개선을 위해 전문 기관이 실시하는 진단이다.","r":[]},"종합진단":{"d":"경영·관리적 사항, 재해 원인, 작업조건, 기계·설비 등을 모두 살피는 안전보건진단입니다.","r":["안전보건진단"]},"안전보건개선계획":{"d":"재해율이 높은 사업장 등에 장관이 수립·시행을 명하는 종합적인 개선계획입니다.","r":["안전보건진단"]},"위험성평가":{"d":"유해, 위험 요인을 찾아 위험의 크기를 추정하고 감소 대책을 세우는 일이다.","r":[]},"사망만인율":{"d":"근로자 1만 명당 발생하는 사망재해자 수의 비율이다.","r":[]},"안전인증":{"d":"유해, 위험 기계의 안전성을 심사하여 기준에 적합함을 인증하는 제도이다.","r":[]},"자율안전확인":{"d":"자율안전확인대상기계등에 대해 제조자가 안전기준에 맞는지 스스로 확인하고 신고하는 제도이다.","r":[]},"안전검사":{"d":"안전검사대상기계등을 사용하는 사업주가 주기에 따라 받는 검사입니다.","r":["자율검사프로그램","안전인증"]},"자율검사프로그램":{"d":"사업주가 일정 요건을 갖춰 자체적으로 안전검사를 하는 방식으로, 인정받으면 안전검사를 받은 것으로 본다.","r":[]},"안전인증대상기계등":{"d":"유해하거나 위험한 기계, 기구, 설비 중 안전인증을 받아야 하는 대상이다. 설치, 이전, 주요 구조 부분 변경 시 안전인증이 요구되는 것도 있다.","r":[]},"방호조치":{"d":"기계, 기구의 위험한 부분에 덮개, 연동장치 등을 설치하여 근로자의 접촉이나 재해를 막는 조치이다.","r":[]},"작업중지":{"d":"급박한 위험이나 중대재해가 있을 때 사업주나 장관이 작업을 멈추게 하는 조치입니다.","r":[]},"과징금":{"d":"업무정지나 도급금지 위반 대신 또는 위반에 대해 부과하는 금전적 제재입니다.","r":[]},"물질안전보건자료":{"d":"MSDS. 화학물질의 명칭, 유해성, 위험성, 취급 방법 등을 담은 자료이다.","r":[]},"영업비밀":{"d":"승인을 받아 화학물질의 명칭·함유량을 대체자료로 적을 수 있게 하는 사유가 되는 비공개 정보입니다.","r":["물질안전보건자료"]},"신규화학물질":{"d":"새로 제조하거나 수입하려는 화학물질로 유해성·위험성을 조사해 보고서를 내야 합니다.","r":[]},"제조등금지물질":{"d":"직업성 암을 유발하는 등 근로자 건강에 특히 해로워 제조·수입·양도·제공·사용이 금지된 물질입니다.","r":["허가대상물질"]},"허가대상물질":{"d":"대체물질이 개발되지 않아 장관의 허가를 받아야 제조·사용할 수 있는 물질입니다.","r":["제조등금지물질"]},"일반석면조사":{"d":"건축물이나 설비를 철거·해체하는 소유주 등이 직접 하는 석면 조사입니다.","r":["기관석면조사"]},"기관석면조사":{"d":"일정 규모 이상의 철거·해체 때 석면조사기관에 맡겨 하는 석면 조사입니다.","r":["일반석면조사"]},"석면해체·제거업자":{"d":"석면이 일정 기준 이상 든 자재를 해체·제거하는 작업을 하는 등록 사업자입니다.","r":["기관석면조사"]},"공정안전보고서":{"d":"유해하거나 위험한 설비를 가진 사업장에서 중대산업사고를 예방하려고 작성하여 제출하는 보고서이다.","r":[]},"중대산업사고":{"d":"유해하거나 위험한 설비의 누출, 화재, 폭발 등으로 사업장 내 근로자나 인근 지역에 심각한 피해를 주는 사고이다.","r":[]},"유해위험방지계획서":{"d":"유해하거나 위험한 설비나 건설공사를 시작하기 전에 안전과 보건상의 위험을 미리 점검하여 제출하는 계획서이다.","r":[]},"작업환경측정":{"d":"작업환경 실태를 파악하기 위해 근로자나 작업장소에서 유해인자의 시료를 채취하고 분석, 평가하는 일이다.","r":[]},"일반건강진단":{"d":"상시 사용하는 근로자의 질병 징후를 조기에 발견하기 위해 사업주가 주기적으로 실시하는 건강진단이다.","r":[]},"특수건강진단":{"d":"유해인자에 노출되는 업무에 종사하는 근로자의 건강장해를 조기에 발견하기 위해 실시하는 건강진단이다.","r":[]},"배치전건강진단":{"d":"특수건강진단 대상 업무에 근로자를 배치하기 전에 그 업무에 적합한지 확인하기 위해 실시하는 건강진단이다.","r":[]},"수시건강진단":{"d":"특수건강진단 대상 유해인자로 인한 것으로 의심되는 직업성 천식, 피부염 등의 증상을 보이는 근로자에게 실시하는 건강진단이다.","r":[]},"임시건강진단":{"d":"같은 유해인자에 노출되는 근로자에게 유사한 질병 증상이 발생한 경우 등에 고용노동부장관의 명령으로 실시하는 건강진단이다.","r":[]},"건강관리카드":{"d":"유해업무에 종사한 근로자에게 발급해 건강진단 등을 지원하는 카드이다. 타인에게 양도나 대여할 수 없다.","r":[]},"역학조사":{"d":"집단에서 질병의 발생 원인과 분포를 조사하여 업무와의 관련성을 밝히는 조사이다.","r":[]},"산업안전지도사":{"d":"산업안전에 관한 전문지식으로 사업장의 평가, 지도, 계획서 작성 등을 하는 자격을 가진 사람이다.","r":[]},"산업보건지도사":{"d":"산업보건에 관한 전문지식으로 작업환경의 평가, 개선 지도 등을 하는 자격을 가진 사람이다.","r":[]},"안전보건대장":{"d":"건설공사 계획·설계·시공 단계마다 발주자가 작성·이행하게 하는 안전보건 문서입니다.","r":["안전보건조정자"]},"안전보건조정자":{"d":"같은 장소에서 둘 이상의 건설공사가 진행될 때 작업의 혼재로 인한 위험을 조정하는 사람이다.","r":[]},"산업안전보건관리비":{"d":"건설공사에서 산업재해 예방을 위해 도급금액이나 사업비에 계상해 사용하는 비용입니다.","r":[]},"인화성 가스":{"d":"20도, 표준압력에서 공기와 혼합하여 인화되는 범위에 있는 가스이다.","r":[]},"인화성 액체":{"d":"표준압력에서 인화점이 일정 온도 이하인 액체이다.","r":[]},"인화성 고체":{"d":"쉽게 연소되거나 마찰에 의해 화재를 일으키거나 촉진할 수 있는 물질입니다.","r":[]},"폭발성 물질":{"d":"자체 화학반응으로 주위환경에 손상을 줄 만한 온도·압력·속도의 가스를 발생시키는 고체·액체 또는 혼합물입니다.","r":[]},"고압가스":{"d":"20℃에서 200킬로파스칼 이상의 압력으로 용기에 충전된 가스이거나 냉동액화가스 형태로 충전된 가스입니다.","r":[]},"물반응성 물질":{"d":"물과 상호작용을 하여 인화성 가스를 발생시키는 고체, 액체 또는 혼합물이다.","r":[]},"자기반응성 물질":{"d":"열적으로 불안정해 산소가 공급되지 않아도 강렬하게 발열·분해하기 쉬운 물질입니다.","r":[]},"자기발열성 물질":{"d":"주위의 에너지 공급 없이 공기와 반응해 스스로 발열하는 물질입니다.","r":[]},"산화성 가스":{"d":"산소를 공급해 공기보다 다른 물질의 연소를 더 잘 일으키거나 촉진하는 가스입니다.","r":[]},"유기과산화물":{"d":"2가의 -O-O- 구조를 가진 과산화수소의 유도체로서 열에 불안정하여 폭발적으로 분해할 수 있는 유기물질이다.","r":[]},"금속 부식성 물질":{"d":"화학적 작용으로 금속에 손상 또는 부식을 일으키는 물질입니다.","r":[]},"에어로졸":{"d":"재충전이 불가능한 용기에 가스를 채우고 내용물을 폼·페이스트·분말상 등으로 내보내는 분사장치를 갖춘 것입니다.","r":[]},"이상기압":{"d":"대기압보다 현저히 높거나 낮은 압력으로, 일정 기준을 넘는 게이지 압력의 기압이다.","r":[]},"생물학적 인자":{"d":"혈액매개, 공기매개, 곤충 및 동물매개로 감염을 일으키는 인자입니다.","r":[]},"안전관리전문기관":{"d":"사업주를 대신하여 안전관리자의 업무를 위탁받아 수행하는 것으로 지정받은 기관이다.","r":[]},"보건관리전문기관":{"d":"사업주를 대신하여 보건관리자의 업무를 위탁받아 수행하는 것으로 지정받은 기관이다.","r":[]},"근로자대표":{"d":"근로자의 과반수로 조직된 노동조합이 있으면 그 노조, 없으면 근로자 과반수를 대표하는 사람이다.","r":[]},"산업재해":{"d":"근로자가 업무에 관계되는 건설물, 설비, 원재료, 가스, 분진 등이나 작업 중 사망하거나 부상, 질병에 걸리는 것이다.","r":[]},"산업재해발생건수등":{"d":"산업재해의 발생 건수, 재해율, 사망만인율 등 사업장별 재해 통계 정보이다. 일정 사업장은 이를 공표한다.","r":[]},"도급":{"d":"명칭과 관계없이 물건의 제조, 건설, 수리, 서비스 제공 등의 업무를 타인에게 맡기는 계약이다.","r":[]},"수급인":{"d":"도급을 받아 업무를 수행하는 사업주이다.","r":[]},"작업환경측정기관":{"d":"사업주의 위탁을 받아 작업환경측정을 하도록 고용노동부장관이 지정한 기관이다.","r":[]},"예비조사":{"d":"작업환경측정을 하기 전에 공정과 유해인자 등을 파악하기 위해 먼저 하는 조사이다.","r":[]},"지역 시료채취":{"d":"근로자가 아니라 작업장소의 특정 지점에 측정기를 두고 공기 시료를 채취하는 방법이다.","r":[]},"개인 시료채취":{"d":"측정기를 근로자 몸에 부착하여 호흡 위치에서 시료를 채취하는 방법이다.","r":[]},"자율안전확인대상기계등":{"d":"안전인증대상은 아니지만 제조자가 안전기준에 맞는지 스스로 확인하여 신고해야 하는 유해, 위험 기계 등이다.","r":[]},"안전검사대상기계등":{"d":"유해하거나 위험한 기계 중 사용 중에 주기적으로 안전검사를 받아야 하는 대상이다.","r":[]},"구동부 방호 연동장치":{"d":"기계의 구동 부분이 작동 중에 사람이 접근하면 작동을 멈추도록 연결된 방호장치이다.","r":[]},"날접촉 예방장치":{"d":"예초기, 금속절단기 등의 날에 근로자가 닿는 것을 막는 방호장치이다.","r":[]},"회전체 접촉 예방장치":{"d":"원심기 등의 회전하는 부분에 근로자가 접촉하는 것을 막는 방호장치이다.","r":[]},"압력방출장치":{"d":"설비 내부 압력이 한계를 넘으면 압력을 밖으로 내보내 파손을 막는 안전장치이다.","r":[]},"묻힘형":{"d":"기계의 물림점이나 동력전달 부분을 돌출되지 않게 안으로 숨기는 구조이다.","r":[]},"대여자":{"d":"유해, 위험 기계등을 타인에게 대여하는 자이다. 안전조치와 서면 발급 의무가 있다.","r":[]},"타워크레인":{"d":"건설 현장에서 고정된 철탑 위에 지브를 달아 무거운 자재를 높은 곳으로 들어 옮기는 크레인이다.","r":[]},"타워크레인 설치ㆍ해체업":{"d":"타워크레인을 설치하거나 해체하는 일을 업으로 하는 사업이다. 장비와 인력 기준을 갖추어 등록해야 한다.","r":[]},"고소작업대":{"d":"작업자가 탑승한 작업대를 높은 곳으로 올리고 내리게 하는 장비이다.","r":[]},"사출성형기":{"d":"가열한 플라스틱 재료를 금형에 밀어 넣어 제품을 만드는 기계이다. 형체결력이 일정 이상이면 안전검사 대상이 된다.","r":[]},"형체결력":{"d":"사출성형기에서 금형을 닫아 눌러 주는 힘이다.","r":[]},"롤러기":{"d":"두 개 이상의 회전하는 롤러 사이로 재료를 통과시켜 가공하는 기계이다. 급정지장치를 설치한다.","r":[]},"압력용기":{"d":"내부 압력이 대기압과 다른 상태로 가스나 액체를 담는 용기이다.","r":[]},"원심기":{"d":"용기를 고속으로 회전시켜 원심력으로 액체와 고체를 분리하는 기계이다.","r":[]},"기계등":{"d":"산업안전보건법령상 유해하거나 위험한 기계, 기구, 설비를 통틀어 이르는 말이다.","r":[]},"물질안전보건자료대상물질":{"d":"물질안전보건자료를 작성해 제공해야 하는 화학물질이나 이를 함유한 혼합물이다.","r":[]},"유해성ㆍ위험성 조사":{"d":"새로 제조하거나 수입하는 화학물질의 유해성과 위험성을 시험하여 조사하는 제도이다. 일부 물질은 제외된다.","r":[]},"허가대상 유해물질":{"d":"제조 등이 금지되지만 대체물질이 개발되지 않아 고용노동부장관의 허가를 받아 제조, 사용할 수 있는 유해물질이다.","r":[]},"자연발화성 고체":{"d":"적은 양으로도 공기와 접촉하여 짧은 시간 안에 발화할 수 있는 고체이다.","r":[]},"안전보건교육":{"d":"근로자가 안전하고 건강하게 일하도록 사업주가 실시하는 교육으로, 정기교육, 채용 시 교육, 작업내용 변경 시 교육, 특별교육 등이 있다.","r":[]},"건설업 기초안전ㆍ보건교육":{"d":"건설 일용근로자가 건설현장에서 일하기 전에 받아야 하는 기초적인 안전보건교육이다.","r":[]},"신규교육":{"d":"직무교육 중 해당 직위에 선임된 후 일정 기간 안에 받는 첫 교육이다.","r":[]},"보수교육":{"d":"지도사가 등록 갱신 등을 위해 업무교육과 직업윤리교육으로 받는 교육이다.","r":[]},"안전보건교육기관":{"d":"근로자안전보건교육이나 직무교육을 하기 위해 고용노동부장관에게 등록한 기관이다.","r":[]},"도급승인":{"d":"급성 독성 물질 취급 등 위험한 작업을 도급하려 할 때 고용노동부장관의 승인을 받아야 하는 제도이다.","r":[]},"유해한 작업의 도급금지":{"d":"도금, 수은ㆍ납ㆍ카드뮴을 제련, 주입, 가공 및 가열하는 작업 등을 도급할 수 없게 한 규정이다.","r":[]},"하도급":{"d":"도급받은 수급인이 그 작업을 다시 다른 사업주에게 도급하는 것이다.","r":[]},"순회점검":{"d":"도급인이 작업장을 돌아다니며 안전보건 상태를 확인하는 점검이다.","r":[]},"근로감독관":{"d":"사업장을 출입하여 법 위반 여부를 감독하고 조사하는 공무원이다.","r":[]},"자격대여행위":{"d":"자격증을 다른 사람에게 빌려주는 행위이다. 지도사 자격증의 대여가 금지된다.","r":[]},"작업환경측정 신뢰성평가":{"d":"작업환경측정 결과의 정확성과 신뢰성을 한국산업안전보건공단이 평가하는 제도이다.","r":[]},"협의체":{"d":"도급인과 수급인 전원으로 구성하여 작업 시기, 연락 방법, 대피 방법 등을 협의하는 기구이다.","r":[]},"역학조사평가위원회":{"d":"역학조사의 실시 결과를 평가하는 위원회이다.","r":[]},"한국산업안전보건공단":{"d":"산업재해 예방을 위한 기술지원, 연구, 교육 등을 수행하는 공공기관이다.","r":[]},"근로복지공단":{"d":"산재보험 사업을 운영하며 업무상 질병 여부 판정 등을 맡는 공공기관이다.","r":[]},"업무상 질병":{"d":"업무에 기인하여 발생한 질병이다. 산재보험 급여의 대상이 된다.","r":[]},"직업성 질환":{"d":"작업 환경이나 업무 수행 중 노출되는 유해인자로 인해 생기는 질병이다.","r":[]},"건강진단기관":{"d":"근로자 건강진단을 실시하기 위해 지정받은 의료기관이다.","r":[]},"잠함(潛函)":{"d":"수중이나 연약 지반에서 지하 구조물을 만들기 위해 압축공기를 넣어 물이 못 들어오게 한 작업용 함이다. 작업자는 높은 기압에 노출된다.","r":[]},"잠수 작업":{"d":"물속에서 호흡장비를 쓰고 하는 작업이다. 높은 기압에서 하는 작업에 속한다.","r":[]},"고기압 업무":{"d":"대기압보다 높은 압력 환경에서 하는 업무이다. 잠함, 잠수 작업 등이 해당된다.","r":[]},"갱(坑) 내":{"d":"광산이나 터널처럼 땅속을 파고 들어간 작업 장소의 안쪽이다.","r":[]},"마비성 치매":{"d":"산업안전보건법령상 사업주가 의사의 진단에 따라 근로를 금지해야 하는 질병 가운데 하나로 열거된 질병이다.","r":[]},"조현병":{"d":"사고, 지각, 감정 등에 이상이 나타나는 정신질환이다. 근로 금지나 제한 시 의사의 의견을 듣는 질병에 해당할 수 있다.","r":[]},"정신신경증":{"d":"불안, 우울 등 정신적 원인으로 신체와 정신에 증상이 나타나는 질환을 이르는 말이다.","r":[]},"제1차 검사항목":{"d":"건강진단에서 모든 대상자가 우선 받는 기본 검사항목이다. 이상 소견이 있으면 제2차 검사항목을 추가한다.","r":[]},"공정안전자료":{"d":"공정안전보고서에 포함하는 자료로, 취급 물질, 설비 현황, 공정도 등 공정의 안전에 관한 기초 자료이다.","r":[]},"공정위험성 평가서":{"d":"공정에 내재한 위험요소를 찾아 평가한 결과를 정리한 서류이다.","r":[]},"안전운전계획":{"d":"공정안전보고서에 포함되는 계획으로, 설비를 안전하게 운전하고 유지하기 위한 절차와 방법을 정한다.","r":[]},"비상조치계획":{"d":"사고가 났을 때 피해를 줄이기 위한 비상 대응 절차와 조직을 정한 계획이다.","r":[]},"이행상태평가":{"d":"공정안전보고서의 내용이 사업장에서 실제로 이행되고 있는지 평가하는 것이다.","r":[]},"지간(支間)":{"d":"다리에서 기둥과 기둥 사이의 거리이다.","r":[]},"지도사 등록":{"d":"지도사가 직무를 수행하려고 고용노동부장관에게 하는 등록이다. 일정 기간마다 갱신한다.","r":[]},"연수교육":{"d":"지도사가 받는 교육으로, 이수자 명단 등이 관리된다.","r":[]},"보증보험":{"d":"지도사가 직무 수행 중 손해를 배상할 수 있도록 가입하는 보험이다.","r":[]},"안전보건개선계획서":{"d":"산업재해율이 높은 사업장 등에 작성하게 하는 계획으로, 시설, 관리체제 등을 개선하는 내용을 담는다.","r":[]},"직업성 질병자":{"d":"업무상 유해인자에 노출되어 직업성 질병으로 판정된 근로자이다.","r":[]},"합명회사":{"d":"무한책임사원만으로 구성되는 회사이다. 지도사 법인에 상법의 이 규정이 적용된다.","r":[]}},"notes":{"1,1,2,2-테트라클로로에탄·사염화탄소·아크릴로니트릴·염화비닐 — 3개월 이내, 6개월 / 석면·면 분진 — 12개월 이내, 12개월":"테트라클로로에탄, 사염화탄소, 아크릴로니트릴, 염화비닐은 3개월 이내에 6개월, 석면·면 분진은 12개월 이내에 12개월입니다.","1 α-나프틸아민 및 그 염 / 2 디아니시딘 및 그 염 / 3 디클로로벤지딘 및 그 염 / 4 베릴륨 / 5 벤조트리클로라이드 / 6 비소 및 그 무기화합물 / 7 염화비닐 / 8 콜타르피치 휘발물 / 9 크롬광 가공(열을 가하여 소성 처리하는 경우만) / 10 크롬산 아연 / 11 o-톨리딘 및 그 염 / 12 황화니켈류 / 13 제1~4호, 제6~12호 물질을 포함한 혼합물(포함 중량 1퍼센트 이하는 제외) / 14 제5호(벤조트리클로라이드) 포함 혼합물(0.5퍼센트 이하는 제외) / 15 보건상 해로운 물질로서 심의위원회 심의를 거쳐 고시하는 물질":"허가대상물질에는 α-나프틸아민, 디아니시딘, 디클로로벤지딘, 베릴륨, 비소 및 그 무기화합물, 염화비닐, 콜타르피치 휘발물 등이 있습니다.","1 β-나프틸아민과 그 염 / 2 4-니트로디페닐과 그 염 / 3 백연을 포함한 페인트(포함 중량 2퍼센트 이하는 제외) / 4 벤젠을 포함하는 고무풀(5퍼센트 이하는 제외) / 5 석면 / 6 폴리클로리네이티드 터페닐 / 7 황린 성냥 / 8 제1호·제2호·제5호·제6호 물질을 포함한 혼합물(포함 중량 1퍼센트 이하는 제외) / 9 화학물질관리법상 금지물질(일부 제외) / 10 보건상 해로운 물질로서 산업재해보상보험및예방심의위원회 심의를 거쳐 고용노동부장관이 정하는 유해물질":"제조등금지물질에는 β-나프틸아민과 그 염, 4-니트로디페닐과 그 염, 석면, 폴리클로리네이티드 터페닐, 황린 성냥 등이 있습니다.","1 고압실 내 작업(잠함공법 등) / 2 아세틸렌 용접장치·가스집합 용접장치 금속의 용접·용단·가열 / 3 밀폐된 장소 용접 또는 습한 장소 전기용접 / 4 폭발성·물반응성·자기반응성·자기발열성 물질, 자연발화성 액체·고체, 인화성 액체의 제조·취급(시험연구 제외) / 5 액화석유가스·수소가스 등 인화성 가스 또는 폭발성 물질 중 가스의 발생장치 취급 / 6 화학설비 중 반응기·교반기·추출기의 사용 및 세척 / 7 화학설비의 탱크 내 작업 / 8 분말·원재료 등을 담은 호퍼·저장창고 등 저장탱크 내부작업 / 9 건조설비(위험물 등 속부피 1㎥ 이상 등)에 의한 가열·건조 / 10 집재장치의 조립·해체·변경·수리 및 집재·운반 / 11 동력 프레스기계 5대 이상 보유 사업장의 작업 / 12 목재가공용 기계 5대 이상 보유 사업장의 작업 / 13 운반용 등 하역기계 5대 이상 보유 사업장의 작업 / 14 1톤 이상의 크레인 사용 작업 또는 1톤 미만 크레인·호이스트 5대 이상 보유 사업장 작업(제39호 제외) / 15 건설용 리프트·곤돌라 이용 작업 / 16 주물 및 단조 작업 / 17 전압 75볼트 이상 정전 및 활선작업 / 18 콘크리트 파쇄기 파쇄작업(2m 이상 구축물) / 19 굴착면 높이 2m 이상 지반 굴착 / 20 흙막이 지보공의 보강 또는 동바리 설치·해체 / 21 터널 안 굴착작업 또는 터널 거푸집 지보공 조립·콘크리트 작업 / 22 굴착면 높이 2m 이상 암석 굴착 / 23 높이 2m 이상 물건을 쌓거나 무너뜨리는 작업 / 24 선박에 짐을 쌓거나 부리거나 이동시키는 작업 / 25 거푸집 동바리 조립·해체 / 26 비계 조립·해체·변경 / 27 건축물 골조·다리 상부구조·탑 금속제 부재(5m 이상) 조립·해체·변경 / 28 처마 높이 5m 이상 목조건축물 구조 부재 조립 등 / 29 콘크리트 인공구조물(높이 2m 이상) 해체·파괴 / 30 타워크레인 설치(상승작업 포함)·해체 / 31 보일러(소형 및 일정 규모 이하 제외) 설치·취급 / 32 게이지 압력 1kg/㎠ 이상 압력용기 설치·취급 / 33 방사선 업무 관련 작업(의료·실험용 제외) / 34 밀폐공간 작업 / 35 허가 또는 관리 대상 유해물질 제조·취급 / 36 로봇작업 / 37 석면해체·제거작업 / 38 가연물이 있는 장소에서 하는 화재위험작업 / 39 타워크레인을 사용하는 작업 시 신호업무":"특별교육 대상 작업은 고압실 내 작업, 가스 용접, 밀폐된 장소 용접, 폭발성 물질 취급 등이 번호로 나열됩니다.","1년 이하 징역 또는 1천만원 이하 벌금: 제41조제3항(고객 폭언 조치 요구 근로자 불이익) / 제56조제5항(중대재해 현장 훼손·원인조사 방해) / 제57조제1항(산재 은폐·교사·공모) / 제65조제1항, 제80조제1항·제2항·제4항, 제85조제2항·제3항, 제92조제1항, 제141조제4항, 제162조 위반":"고객 폭언 조치 불이익, 현장 훼손, 산재 은폐 등은 1년 이하 징역 또는 1천만원 이하 벌금입니다.","1 원소 / 2 천연으로 산출된 화학물질 / 3 건강기능식품 / 4 군수품(군수품관리법 제3조에 따른 통상품은 제외) / 5 농약 및 원제 / 6 마약류 / 7 비료 / 8 사료 / 9 살생물물질 및 살생물제품 / 10 식품 및 식품첨가물 / 11 의약품 및 의약외품 / 12 방사성물질 / 13 위생용품 / 14 의료기기 / 15 화약류 / 16 화장품과 화장품에 사용하는 원료 / 17 고용노동부장관이 공표한 물질로서 공표된 연간 제조량·수입량 이하로 제조·수입한 물질 / 18 고용노동부장관이 기후에너지환경부장관과 협의해 고시하는 화학물질 목록에 기록된 물질":"유해성 조사 제외 대상에는 원소, 천연 화학물질, 건강기능식품, 군수품, 농약, 마약류, 비료, 사료, 식품, 의약품 등이 있습니다.","1천500만원 이하: 안전보건진단 거부·방해·기피 또는 근로자대표 미참여 / 산업재해 발생 보고 미이행·거짓 보고 / 위생시설 장소 미제공 / 휴게시설 미설치(대상 사업장) / 역학조사 거부·방해·기피 / 역학조사 참석 거부·방해":"안전보건진단 거부·방해·기피, 산재 발생 보고 미이행·거짓 보고, 휴게시설 미설치, 역학조사 거부·방해 등은 1천500만원 이하 과태료입니다.","1천만원 이하 벌금: 제108조제2항(신규화학물질 조사 후 필요한 조치 즉시 시행)·제109조제2항 위반 및 제108조제4항·제109조제3항 명령 위반":"신규화학물질 조사 후 필요한 조치를 즉시 시행하지 않거나 관련 명령을 위반하면 1천만원 이하 벌금입니다.","1천만원 이하 벌금: 제69조제1항·제2항, 제89조제1항(자율안전확인 미신고), 제90조제2항·제3항, 제108조제2항, 제109조제2항, 제138조제1항·제2항(질병자 근로 금지·복귀) 위반 / 제90조제4항·제108조제4항·제109조제3항 명령 위반 / 제125조제6항(측정 결과 후속 조치 미이행) / 제132조제4항(건강진단 후속 조치 미이행)":"자율안전확인 미신고, 질병자 근로 금지·복귀 위반 등과 일부 명령 위반은 1천만원 이하 벌금입니다.","1호 사업장의 산업재해 예방계획의 수립에 관한 사항 / 2호 안전보건관리규정의 작성 및 변경에 관한 사항 / 3호 안전보건교육에 관한 사항 / 4호 작업환경측정 등 작업환경의 점검 및 개선에 관한 사항 / 5호 근로자의 건강진단 등 건강관리에 관한 사항 / 6호 산업재해의 원인 조사 및 재발 방지대책 수립에 관한 사항 / 7호 산업재해에 관한 통계의 기록 및 유지에 관한 사항 / 8호 안전장치 및 보호구 구입 시 적격품 여부 확인에 관한 사항 / 9호 그 밖에 근로자의 유해·위험 방지조치에 관한 사항으로서 고용노동부령으로 정하는 사항: 위험성평가의 실시에 관한 사항, 안전보건규칙에서 정하는 근로자의 위험 또는 건강장해 방지에 관한 사항":"그 업무는 재해 예방계획 수립, 안전보건관리규정 작성·변경, 안전보건교육, 작업환경 점검, 건강진단, 재해 원인 조사 등입니다.","1호 산업재해율이 같은 업종의 규모별 평균 산업재해율보다 높은 사업장 / 2호 사업주가 필요한 안전조치 또는 보건조치를 이행하지 않아 중대재해가 발생한 사업장 / 3호 대통령령으로 정하는 수 이상의 직업성 질병자가 발생한 사업장 — 연간 2명 이상 / 3호의2 화재·폭발·붕괴 등 중대재해 외 산업재해(법 제56조제1항제2호)가 발생한 사업장으로서 사업주가 필요한 안전·보건조치를 이행하지 않아 최근 1년 이내 2회 이상 발생한 사업장 / 4호 유해인자의 노출기준을 초과한 사업장":"재해율이 높거나 안전조치 불이행으로 중대재해가 났거나 직업성 질병자가 연간 2명 이상이면 대상입니다.","2021 기출은 안전보건관리책임자 신규·보수 시간을 물었으나 정답표 숫자가 현행 별표와 맞지 않는다, 현행 기준은 위 표(6시간, 6시간)":"2021 기출은 책임자의 신규·보수 시간을 물었는데 정답표 숫자가 현행 별표와 맞지 않고 현행 기준은 6시간, 6시간이라는 메모입니다.","2개 이상의 건설공사를 도급한 건설공사발주자는 같은 장소에서 행해지는 경우 작업 혼재 산재 예방을 위해 건설공사 현장에 안전보건조정자를 두어야 한다, 대상은 각 건설공사 금액의 합이 50억원 이상":"2개 이상의 건설공사를 도급한 발주자는 같은 장소의 작업 혼재 재해 예방을 위해 안전보건조정자를 두며 대상은 공사금액 합이 50억원 이상입니다.","2년 보존: 산업안전보건위원회 및 노사협의체 회의록":"노사협의체와 산업안전보건위원회가 남기는 회의록은 2년간 보존 의무가 있습니다.","2 안전·보건 관리조직과 직무: 조직 구성·소속·업무 분장 / 안전보건관리책임자(총괄책임자)·안전관리자·보건관리자·관리감독자 직무 및 선임 / 산업안전보건위원회 설치·운영 / 명예산업안전감독관 직무·활동 / 작업지휘자 배치":"규정의 둘째 항목은 안전·보건 관리조직과 직무로 책임자, 관리자, 관리감독자 직무와 위원회 운영, 작업지휘자 배치를 다룹니다.","3개월 이상의 요양이 필요한 부상자가 동시에 2명 이상 발생한 재해":"요양이 3개월 이상 필요한 부상자가 한 번에 2명 이상 나오면 중대재해입니다.","3년 보존(사업주): 안전보건관리책임자·안전관리자·보건관리자·안전보건관리담당자·산업보건의 선임 서류 / 안전조치·보건조치에 관한 서류(고용노동부령) / 산업재해의 발생 원인 등 기록 / 신규화학물질 및 중대한 건강장해 우려 화학물질의 유해성·위험성 조사 서류 / 작업환경측정 서류 / 건강진단 서류":"사업주는 책임자·관리자 선임 서류, 안전·보건조치 서류, 산업재해 발생 원인 기록 등을 3년 동안 보존해야 합니다.","3년 이하 징역 또는 3천만원 이하 벌금: 제118조제3항(허가기준 유지의무), 제118조제4항 명령 위반, 제119조제4항 명령 위반, 제123조제1항(석면해체·제거 작업기준)":"허가기준 유지의무, 일부 명령 위반, 석면해체·제거 작업기준 위반은 3년 이하 징역 또는 3천만원 이하 벌금입니다.","3년 이하 징역 또는 3천만원 이하 벌금: 제44조제1항 후단(공정안전보고서 적합 통보 전 설비 가동), 제63조, 제76조, 제81조, 제82조제2항, 제84조제1항(안전인증 미취득), 제87조제1항, 제118조제3항, 제123조제1항, 제139조제1항, 제140조제1항 위반":"공정안전보고서 적합 통보 전 설비 가동, 안전인증 미취득, 허가기준 유지의무 위반 등은 3년 이하 징역 또는 3천만원 이하 벌금입니다.","3 안전·보건교육 / 4 작업장 안전관리 / 5 작업장 보건관리 / 6 사고 조사 및 대책 수립 / 7 위험성평가 / 8 보칙":"규정의 나머지 항목은 안전·보건교육, 작업장 안전관리, 보건관리, 사고 조사 및 대책 수립, 위험성평가, 보칙입니다.","3천만원 이하: 특별교육 미실시(제29조제3항) 및 가맹본부 조치(제79조제1항) 위반 / 중대재해 발생 사실을 보고하지 않거나 거짓으로 보고":"특별교육 미실시, 가맹본부 조치 위반, 중대재해 발생 보고 미이행·거짓 보고는 3천만원 이하 과태료입니다.","500만원 이하 벌금: 제64조제1항제1호~제5호, 제7호, 제8호 또는 제2항 위반 (도급인의 협의체 구성·운영, 순회점검, 교육 지원, 교육 확인, 경보체계 훈련, 작업 확인, 작업 조정, 정기점검)":"도급인의 협의체 운영, 순회점검, 교육 지원, 작업 조정, 정기점검 위반은 500만원 이하 벌금입니다.","5년 내 재범은 형의 2분의 1까지 가중":"5년 안에 다시 범하면 형의 2분의 1까지 가중합니다.","5년 이하 징역 또는 5천만원 이하 벌금: 제117조제1항(금지물질 제조 등)·제118조제1항(허가 없이 제조·사용)·제122조제1항(석면해체·제거업자 미이용) 위반":"금지물질 제조, 허가 없는 제조·사용, 석면해체·제거업자 미이용은 5년 이하 징역 또는 5천만원 이하 벌금입니다.","5년 이하 징역 또는 5천만원 이하 벌금: 제38조제1항~제3항, 제39조제1항, 제51조(급박한 위험 시 작업중지), 제54조제1항(중대재해 시 작업중지·대피), 제117조제1항, 제118조제1항, 제122조제1항, 제157조제3항(신고 근로자 불이익) 위반 / 제42조제4항 후단, 제53조제3항, 제55조제1항·제2항, 제118조제5항 명령 위반":"급박한 위험 시 작업중지 위반, 금지물질 제조, 허가 없는 사용 등은 5년 이하 징역 또는 5천만원 이하 벌금입니다.","5천만원 이하: 기관석면조사를 하지 않고 건축물·설비 철거·해체 / 석면농도 기준 초과 상태에서 철거·해체":"기관석면조사를 하지 않고 철거·해체하거나 석면농도 기준 초과 상태로 철거·해체하면 5천만원 이하 과태료입니다.","7년 이하 징역 또는 1억원 이하 벌금: 안전조치(제38조제1항~제3항)·보건조치(제39조제1항)·도급인 조치(제63조)를 위반하여 근로자를 사망에 이르게 한 자, 5년 이내 재범은 형의 2분의 1까지 가중":"안전·보건·도급인 조치 위반으로 근로자가 숨지면 7년 이하 징역 또는 1억원 이하 벌금입니다.","MSDS 교육 내용: 대상화학물질의 명칭(또는 제품명) / 물리적 위험성 및 건강 유해성 / 취급상의 주의사항 / 적절한 보호구 / 응급조치 요령 및 사고시 대처방법 / MSDS 및 경고표지를 이해하는 방법":"MSDS 교육 내용은 물질 명칭, 물리적 위험성과 건강 유해성, 취급 주의사항, 보호구, 응급조치 요령, 자료와 경고표지를 이해하는 방법입니다.","MSDS 미제공 과태료 500만원 이하(영 별표 35: 1종당 1차 100만원), 물질안전보건자료대상물질을 양도하면서 자료를 제공하지 않은 것은 징역·벌금 대상이 아니라 과태료 대상":"MSDS를 제공하지 않으면 과태료 500만원 이하이고 징역·벌금이 아니라 과태료 대상이며 영 별표 35에서 1종당 1차 100만원입니다.","N,N-디메틸아세트아미드·디메틸포름아미드 — 1개월 이내, 6개월 / 벤젠 — 2개월 이내, 6개월":"N,N-디메틸아세트아미드와 디메틸포름아미드는 1개월 이내 첫 검진에 주기 6개월, 벤젠은 2개월 이내에 주기 6개월입니다.","β-나프틸아민, 4-니트로디페닐, 폴리클로리네이티드 터페닐, 석면, 황린 성냥은 제조등금지물질이며 허가대상이 아니다, 베릴륨·크롬산 아연·황화니켈류·염화비닐·o-톨리딘·콜타르피치 휘발물은 허가대상":"β-나프틸아민, 4-니트로디페닐, 폴리클로리네이티드 터페닐, 석면, 황린 성냥은 허가대상이 아니라 금지물질이고 베릴륨 등은 허가대상입니다.","① 공정상의 안전에 관한 평가·지도 ② 유해·위험의 방지대책에 관한 평가·지도 ③ ①·②와 관련된 계획서 및 보고서의 작성 ④ 그 밖에 산업안전에 관한 사항으로서 대통령령으로 정하는 사항":"산업안전지도사의 직무는 공정상의 안전과 유해·위험 방지대책에 관한 평가·지도, 관련 계획서와 보고서의 작성 등입니다.","① 근로자대표 ② 명예산업안전감독관이 위촉되어 있으면 근로자대표가 지명하는 1명 이상의 명예산업안전감독관 ③ 근로자대표가 지명하는 9명 이내의 해당 사업장 근로자(②의 위원이 있으면 9명에서 그 수를 뺀 수)":"근로자위원은 근로자대표, 근로자대표가 지명하는 명예산업안전감독관, 근로자대표가 지명하는 근로자 9명 이내로 구성합니다.","① 기계·전기·전자·화공 또는 산업안전 분야 기사 이상 + 실무경력 3년 ② 같은 분야 산업기사 이상 + 5년 ③ 같은 분야 기능사 이상 + 7년 ④ 4년제 학교 관련 학과 졸업 + 3년 ⑤ 그 밖의 고등교육법상 학교 관련 학과 졸업 + 5년 ⑥ 고등학교·고등기술학교 기계·전기 또는 전자·화공 관련 학과 졸업 + 7년 ⑦ 자율검사프로그램에 따른 성능검사 교육 이수 + 실무경력 1년":"자율안전검사원 자격은 관련 분야 기사 이상은 실무경력 3년, 산업기사 이상은 5년, 기능사 이상은 7년 등으로 정해집니다.","① 작업환경의 평가 및 개선 지도 ② 작업환경 개선과 관련된 계획서 및 보고서의 작성 ③ 근로자 건강진단에 따른 사후관리 지도 ④ 직업성 질병 진단(의사인 산업보건지도사만) 및 예방 지도 ⑤ 산업보건에 관한 조사·연구 ⑥ 그 밖에 대통령령 사항":"산업보건지도사의 직무는 작업환경 평가·개선 지도, 건강진단 사후관리 지도, 직업성 질병 진단 및 예방 지도, 산업보건 조사·연구 등입니다.","① 해당 사업의 대표자 ② 안전관리자 1명(위탁 사업장은 전문기관 담당자) ③ 보건관리자 1명(위탁 시 전문기관 담당자) ④ 산업보건의(해당 사업장에 선임되어 있는 경우만) ⑤ 대표자가 지명하는 9명 이내의 해당 사업장 부서의 장":"사용자위원은 사업 대표자, 안전관리자 1명, 보건관리자 1명, 선임된 산업보건의, 대표자가 지명하는 부서의 장 9명 이내입니다.","감독 기준 사유: 산업재해 발생 또는 급박한 위험이 있는 경우 / 근로자의 신고 또는 고소·고발 등 조사가 필요한 경우 / 법 위반 범죄의 수사 등 사법경찰관리의 직무 수행 / 그 밖에 위반 여부 조사가 필요하다고 인정하는 경우":"감독 사유는 재해나 급박한 위험, 신고·고소·고발, 수사, 그 밖에 조사가 필요한 경우입니다.","개선계획 미수립·미시행 과태료 1천만원 이하(영 별표 35: 1차 500만원·2차 750만원·3차 1,000만원, 진단 후 계획 명령은 1,000만원)":"개선계획을 수립·시행하지 않으면 과태료 1천만원 이하이고 영 별표 35에서 1차 500만원, 2차 750만원, 3차 1,000만원입니다.","개선계획서에 포함할 사항: 시설, 안전보건관리체제, 안전보건교육, 산업재해 예방 및 작업환경의 개선을 위해 필요한 사항":"계획서에는 시설, 관리체제, 교육, 재해 예방과 작업환경 개선에 필요한 내용을 담습니다.","개선계획서 작성은 지도사의 직무에 포함":"개선계획서를 대신 작성해 주는 일은 지도사가 하는 직무의 하나입니다.","건강관리카드: 고용노동부장관이 건강장해 우려 업무 종사자 중 요건을 갖춘 사람에게 발급, 타인에게 양도·대여 금지(과태료 500만원 이하), 업무에 종사하지 않는 사람은 매년 1회 건강진단 가능":"건강관리카드는 장관이 발급하고 양도·대여하면 과태료 500만원 이하이며 업무를 떠나도 매년 1회 검진합니다.","건강진단 결과, 요양급여기록 및 건강검진 결과(국민건강보험법), 고용정보(고용보험법), 질병정보 및 사망원인 정보(암관리법) 등을 관련 기관에 요청할 수 있다, 소득세법 납세 정보는 없다":"역학조사를 위해 건강진단 결과, 요양급여기록, 고용정보, 질병정보 등을 관련 기관에 요청할 수 있고 소득세법 납세 정보는 포함되지 않습니다.","건강진단 결과 근로자의 건강 유지에 필요하면 작업장소 변경, 작업 전환, 근로시간 단축, 야간근로(오후 10시~다음 날 오전 6시)의 제한, 작업환경측정, 시설·설비의 설치·개선 등 조치, 위반 시 1천만원 이하 벌금":"건강진단 결과 필요하면 작업장소 변경, 작업 전환, 근로시간 단축, 야간근로 제한 등을 하고 위반하면 1천만원 이하 벌금입니다.","건강진단 결과를 근로자의 건강 보호 및 유지 외의 목적으로 사용 금지":"건강진단 결과는 근로자의 건강 보호와 유지 외의 목적으로 사용할 수 없습니다.","건강진단 결과 서류 보존: 법 3년, 규칙 5년(고시 물질 취급 근로자 30년)":"건강진단 결과 서류는 법 3년, 규칙 5년 보존하며 고시 물질 취급 근로자는 30년 보존합니다.","건강진단기관은 실시한 날부터 30일 이내에 결과를 근로자에게 송부하고 건강진단 결과표를 사업주에게 송부, 특수건강진단기관은 30일 이내 지방고용노동관서에 제출":"건강진단기관은 실시한 날부터 30일 이내에 근로자와 사업주에게 결과를 송부하고 특수건강진단기관은 지방고용노동관서에도 30일 이내 제출합니다.","건강진단 비용은 국민건강보험법에서 정한 기준에 따른다 (일반·특수·배치전·수시·임시 모두)":"일반·특수·배치전·수시·임시건강진단의 비용은 모두 국민건강보험법에서 정한 기준에 따릅니다.","건강진단을 실시할 때 근로자대표가 요구하면 근로자대표를 참석시켜야 한다 (미참석 과태료 500만원 이하)":"건강진단을 할 때 근로자대표가 요구하면 참석시켜야 하고 미참석이면 과태료 500만원 이하입니다.","건강진단을 하지 않은 사업주 과태료 1천만원 이하(영 별표 35: 근로자 1명당 10만원·20만원·30만원), 건강진단을 받지 않은 근로자 과태료 300만원 이하(5만원~)":"건강진단을 하지 않은 사업주는 과태료 1천만원 이하이고 건강진단을 받지 않은 근로자는 300만원 이하입니다.","건강·환경 유해성 13종: 급성 독성 / 피부 부식성·자극성 / 심한 눈 손상성·자극성 / 호흡기 과민성 / 피부 과민성 / 발암성 / 생식세포 변이원성 / 생식독성 / 특정 표적장기 독성(1회 노출) / 특정 표적장기 독성(반복 노출) / 흡인 유해성 / 수생 환경 유해성 / 오존층 유해성":"건강·환경 유해성은 급성 독성, 피부 부식성·자극성, 발암성, 생식독성 등 13종으로 분류됩니다.","건설공사: 해당 공사의 착공(대지 정리·가설사무소 설치 등 준비기간은 착공으로 보지 않음) 전날까지 공단에 2부 제출":"건설공사는 착공 전날까지 공단에 2부를 제출하며 대지 정리나 가설사무소 설치 등 준비기간은 착공으로 보지 않습니다.","건설공사는 건설산업기본법상 건설공사, 전기공사업법상 전기공사, 정보통신공사업법상 정보통신공사, 소방시설공사업법에 따른 소방시설공사, 국가유산수리 등에 관한 법률에 따른 국가유산 수리공사":"건설공사에는 건설산업기본법상 공사 외에 전기공사, 정보통신공사, 소방시설공사, 국가유산 수리공사가 포함됩니다.","건설공사도급인은 건설공사발주자로부터 해당 건설공사를 최초로 도급받은 수급인 또는 건설공사의 시공을 주도하여 총괄·관리하는 자":"건설공사도급인은 발주자로부터 공사를 최초로 도급받은 수급인이거나 시공을 주도해 총괄·관리하는 자입니다.","건설공사도급인이 협의체를 구성한 경우: 근로자위원은 전체 사업의 근로자대표·명예감독관·근로자대표가 지명하는 근로자, 사용자위원은 도급인 대표자·관계수급인 각 대표자·안전관리자":"건설공사도급인이 협의체를 구성한 경우 근로자위원은 전체 사업의 근로자대표 등, 사용자위원은 도급인과 관계수급인 대표자와 안전관리자입니다.","건설공사발주자는 건설공사를 도급하는 자로서 건설공사의 시공을 주도하여 총괄·관리하지 아니하는 자, 도급받은 건설공사를 다시 도급하는 자는 제외":"건설공사발주자는 건설공사를 도급하되 시공을 주도해 총괄·관리하지 않는 자이며, 다시 도급하는 자는 제외합니다.","건설공사 착공 사업주(자체심사 및 확인업체 제외)는 계획서를 작성할 때 건설안전 분야의 자격 등 고용노동부령 자격을 갖춘 자의 의견을 들어야 한다":"착공하는 건설공사 사업주는 건설안전 자격자의 의견을 듣고 계획서를 만들어야 합니다.","건설기계관리법 검사(제13조제1항제1호·제2호·제4호, 안전검사 주기에 해당하는 시기의 검사) / 고압가스 안전관리법 제17조제2항 검사 / 광산안전법 제9조 검사 중 설치·변경공사 완료 후 일정한 기간이 지날 때마다 받는 검사 / 선박안전법 제8조~제12조 검사 / 에너지이용 합리화법 제39조제4항 검사 / 원자력안전법 제22조제1항 검사 / 위험물안전관리법 제18조 정기점검 또는 정기검사 / 전기안전관리법 제11조 검사 / 항만법 제33조제1항제3호 검사 / 소방시설법 제22조제1항 자체점검 / 화학물질관리법 제24조제3항 본문 정기검사":"건설기계관리법 검사, 고압가스 안전관리법 검사, 광산안전법 검사 중 일정한 검사 등을 받으면 안전검사가 면제됩니다.","건설업: 공사금액 120억원 이상(토목공사업 150억원 이상)":"건설업은 공사금액 120억원 이상(토목공사업은 150억원 이상)이면 위원회를 설치합니다.","건설업: 공사금액 20억원 이상":"건설업은 공사금액 20억원 이상인 경우 책임자를 선임해야 합니다.","건설업: 공사금액 50억원 이상(관계수급인은 100억원 이상) 120억원 미만(토목공사업 150억원 미만)은 1명 이상, 120억원 이상 800억원 미만도 1명 이상, 800억원 이상 1,500억원 미만은 2명 이상 …(금액 구간별로 증가), 1조원 이상은 11명 이상(2천억원마다 1명 추가, 2조원부터 3천억원마다)":"건설업은 공사금액 50억원 이상부터 구간별로 안전관리자 수가 늘어 1조원 이상이면 11명 이상입니다.","건설업: 공사금액 800억원 이상(토목공사업 1천억원 이상) 또는 상시근로자 600명 이상일 때 1명 이상, 800억원(토목 1천억원) 기준으로 1,400억원 증가할 때마다 또는 600명 추가될 때마다 1명 추가":"건설업은 공사금액 800억원 이상 또는 상시근로자 600명 이상이면 1명 이상이고 기준이 늘 때마다 1명씩 더합니다.","건설업 기초안전·보건교육(건설 일용근로자): 4시간 이상 (내용: 건설공사 종류·시공 절차 1시간 / 산업재해 유형별 위험요인 및 안전보건조치 2시간 / 안전보건관리체제 및 근로자 권리·의무 1시간)":"건설 일용근로자 기초안전·보건교육은 4시간 이상이며 시공 절차 1시간, 재해 유형별 위험요인 2시간, 관리체제와 권리·의무 1시간입니다.","건설업 기초안전·보건교육기관 등록은 공단에 신청(접수 15일 이내 확인, 고용노동부장관 통보 7일 이내), 등록 취소 등을 한 지방고용노동관서의 장은 그 사실을 공단에 통보":"건설업 기초안전·보건교육기관 등록은 공단에 신청하며 접수 후 15일 이내 확인하고 7일 이내에 장관에게 통보합니다.","건설업 기초안전보건교육을 이수한 건설 일용근로자를 채용하는 경우에는 하지 않아도 된다":"건설업 기초안전보건교육을 이수한 건설 일용근로자를 채용하면 채용 시 교육을 하지 않아도 됩니다.","건설업 사업주는 건설 일용근로자를 채용할 때 안전보건교육기관의 교육을 이수하도록 해야 한다(채용 전에 이수했으면 제외)":"건설 일용근로자를 채용하는 건설업 사업주는 먼저 기관 교육을 이수하게 해야 하고 이미 이수했다면 생략합니다.","건설 일용근로자 기초안전보건교육 미이수 채용: 1명당 10만원·20만원·50만원":"건설 일용근로자 기초안전보건교육을 이수하지 않은 사람을 채용하면 1명당 10만원, 20만원, 50만원의 과태료입니다.","건설재해예방전문지도기관 종사자: 신규 34시간 이상, 보수 24시간 이상":"전문지도기관 종사자의 직무교육 시간도 안전관리자와 같아 신규 34시간, 보수 24시간 이상입니다.","건축물이나 설비를 철거·해체하려는 건축물·설비소유주등은 일반석면조사를 하고 결과를 기록·보존, 대통령령 규모 이상은 석면조사기관에 기관석면조사를 하게 한 후 결과를 기록·보존":"건축물이나 설비를 철거·해체하는 소유주 등은 일반석면조사를 하고 일정 규모 이상은 석면조사기관에 기관석면조사를 맡겨 결과를 기록·보존합니다.","검사원 성능검사 교육: 28시간 이상":"검사원이 성능검사를 하려면 28시간 이상의 교육이 필요합니다.","경영·관리적 사항: 산업재해 예방계획의 적정성 / 안전·보건 관리조직과 그 직무의 적정성 / 산업안전보건위원회 설치·운영, 명예산업안전감독관의 역할 등 근로자의 참여 정도 / 안전보건관리규정 내용의 적정성":"경영·관리적 사항 진단은 예방계획의 적정성, 안전·보건 조직과 직무, 위원회 운영과 근로자 참여, 관리규정 내용을 봅니다.","경우 2: 근로복지공단이 업무상 질병 여부의 결정을 위해 요청(요청하는 쪽이 근로복지공단, 실시하는 쪽이 공단) / 경우 3: 공단이 직업성 질환 예방을 위해 역학조사평가위원회 심의를 거친 경우 / 경우 4: 사회적 물의를 일으킨 질병에 대해 지방고용노동관서의 장이 요청":"근로복지공단의 요청이나 위원회 심의를 거친 예방 필요 시 공단이 역학조사를 할 수 있습니다.","계획단계: 중점 관리 유해·위험요인과 감소방안을 포함한 기본안전보건대장 작성 / 설계단계: 기본안전보건대장을 설계자에게 제공하고 설계자가 설계안전보건대장을 작성하게 하고 확인 / 시공단계: 최초 도급받은 수급인에게 설계안전보건대장을 제공하고 공사안전보건대장을 작성하게 하고 이행 확인":"발주자는 계획단계에 기본안전보건대장, 설계단계에 설계안전보건대장, 시공단계에 공사안전보건대장을 쓰게 합니다.","계획서 미제출·미변경 과태료 1천만원 이하(건설공사는 1,000만원), 자격자 의견 청취 의무 위반 300만원 이하, 확인을 받지 않은 경우 300만원 이하":"계획서 미제출·미변경은 과태료 1천만원 이하, 자격자 의견 청취 의무 위반과 확인 미수검은 300만원 이하입니다.","계획 수립 시 산업안전보건위원회의 심의를 거쳐야 한다, 위원회가 설치되어 있지 않으면 근로자대표의 의견을 듣는다":"계획을 수립할 때는 산업안전보건위원회의 심의를 거치고 위원회가 없으면 근로자대표의 의견을 듣습니다.","계획에는 안전 및 보건에 관한 비용, 시설, 인원 등의 사항을 포함해야 한다, 대표이사는 계획을 성실하게 이행":"계획에는 안전·보건 비용, 시설, 인원 등을 포함해야 하고 대표이사는 계획을 성실하게 이행해야 합니다.","계획에 포함할 사항은 안전 및 보건에 관한 경영방침 / 안전·보건관리 조직의 구성·인원 및 역할 / 안전·보건 관련 예산 및 시설 현황 / 전년도 활동실적 및 다음 연도 활동계획":"계획에는 경영방침, 안전·보건관리 조직의 구성·인원·역할, 예산과 시설 현황, 전년도 실적과 다음 연도 계획이 들어갑니다.","고객응대근로자에 대한 폭언 등으로 인한 건강장해 예방조치, 제3자의 폭언 등으로 건강장해가 발생하거나 현저히 우려되면 업무의 일시적 중단 또는 전환, 휴게시간 연장, 치료·상담 지원, 고소·고발 등 지원, 근로자는 조치를 요구할 수 있고 사업주는 불리한 처우 금지":"고객응대근로자에게 폭언 등으로 건강장해가 생기거나 우려되면 업무의 일시 중단·전환, 휴게시간 연장, 치료·상담 지원 등을 해야 합니다.","고기압 업무에 종사시켜서는 안 되는 질병: 감압증 등 고기압 장해 또는 후유증 / 결핵·급성상기도감염·진폐·폐기종 등 호흡기계 질병 / 빈혈증·심장판막증·관상동맥경화증·고혈압증 등 혈액·순환기계 질병 / 정신신경증·알코올중독·신경통 등 정신신경계 질병 / 메니에르씨병·중이염 등 이관협착을 수반하는 귀 질환 / 관절염·류마티스 등 운동기계 질병 / 천식·비만증·바세도우씨병 등 알레르기성·내분비계·물질대사·영양장해 관련 질병":"고기압 업무에 종사시켜서는 안 되는 질병에는 감압증 등 고기압 장해, 호흡기계 질병, 혈액·순환기계 질병, 정신신경증 등이 있습니다.","고압가스: 20℃, 200킬로파스칼(kPa) 이상의 압력 하에서 용기에 충전되어 있는 가스 또는 냉동액화가스 형태로 용기에 충전되어 있는 가스(압축가스, 액화가스, 냉동액화가스, 용해가스로 구분)":"고압가스는 20℃에서 200킬로파스칼 이상 압력으로 용기에 충전된 가스이거나 냉동액화가스 형태로 충전된 가스입니다.","고압가스를 사용하는 단위공정 설비는 안전관리규정·안전성향상계획 및 공단·한국가스안전공사 공동 의견서를 허가관청에 제출하면 보고서를 제출한 것으로 본다":"고압가스를 쓰는 단위공정 설비는 안전관리규정 등과 공동 의견서를 허가관청에 제출하면 공정안전보고서를 제출한 것으로 봅니다.","고용노동부를 제외한 행정기관의 장이 사업장의 안전 및 보건에 관하여 규제를 하려면 미리 고용노동부장관과 협의해야 한다":"다른 부처가 사업장 안전·보건 규제를 만들 때는 먼저 고용노동부장관과 협의하는 절차를 밟아야 합니다.","고용노동부장관은 고용노동부령으로 정하는 사유가 있으면 안전관리자를 늘리거나 교체할 것을 명할 수 있다, 위반 시 과태료 500만원 이하":"장관은 사유가 있으면 안전관리자의 증원이나 교체를 명할 수 있고 위반하면 과태료 500만원 이하입니다.","고용노동부장관은 근로자, 근로자단체, 사업주단체 및 산업재해 예방 관련 전문단체에 소속된 사람 중에서 위촉할 수 있다, 근로자대표가 소속 사업장 근로자 중에서 추천하면 위촉해야 한다":"명예산업안전감독관은 근로자단체 등 소속 중에서 위촉하며 근로자대표가 소속 사업장 근로자를 추천하면 위촉해야 합니다.","고용노동부장관은 근로자에게 건강장해를 일으키는 화학물질 및 물리적 인자 등(유해인자)의 유해성·위험성 분류기준을 마련해야 한다":"건강장해를 일으키는 화학물질과 물리적 인자에 대해 장관이 유해성·위험성 분류기준을 만듭니다.","고용노동부장관은 기본계획 시행에 필요하면 관계 행정기관의 장 또는 공공기관의 운영에 관한 법률 제4조에 따른 공공기관의 장에게 협조를 요청할 수 있다":"장관은 기본계획 시행에 필요하면 관계 행정기관과 공공기관의 장에게 협조를 요청할 수 있습니다.","고용노동부장관은 도급인에게 관계수급인에 관한 자료의 제출을 요청할 수 있고, 정당한 사유 없이 응하지 않으면 안 된다":"장관은 도급인에게 관계수급인에 관한 자료 제출을 요청할 수 있고 도급인은 정당한 사유 없이 거부해서는 안 됩니다.","고용노동부장관은 도급인의 사업장 중 대통령령으로 정하는 사업장에서 관계수급인 근로자가 작업하면 도급인의 재해건수등에 관계수급인의 재해건수등을 포함하여 공표해야 한다":"도급인 사업장에서 관계수급인 근로자가 일하면 도급인의 재해건수 등에 관계수급인의 재해건수 등을 포함해 통합 공표합니다.","고용노동부장관은 보고서가 제출되면 명칭, 유해성·위험성, 건강장해 예방 조치 사항 등을 공표하고 관계 부처에 통보, 시설·설비 설치·정비, 보호구 비치 등의 조치를 명할 수 있다":"장관은 보고서가 제출되면 명칭과 유해성 등을 공표하고 관계 부처에 통보하며 시설 설치·정비, 보호구 비치 등의 조치를 명할 수 있습니다.","고용노동부장관은 분야별(기계·화공·전기·건설 등)로 한정하여 진단을 명할 수 있다, 결과보고서에는 산업재해 또는 사고의 발생원인, 작업조건·작업방법에 대한 평가 등이 포함":"장관은 기계, 화공, 전기, 건설 등 분야별로 한정해 진단을 명할 수 있고 결과보고서에는 재해 원인과 작업조건 평가 등이 포함됩니다.","고용노동부장관은 산업재해를 예방하기 위해 대통령령으로 정하는 사업장의 산업재해 발생건수, 재해율 또는 그 순위 등을 공표해야 한다":"고용노동부장관은 대통령령으로 정한 사업장의 산업재해 발생건수와 재해율 또는 순위 등을 공표해야 합니다.","고용노동부장관은 산업재해 예방을 위해 사업주, 사업주단체, 그 밖의 관계인에게 필요한 사항을 권고하거나 협조를 요청할 수 있다":"재해 예방을 위해 장관이 사업주나 단체에 필요한 사항을 권고하거나 협조를 구할 수 있습니다.","고용노동부장관은 심사 결과를 서면으로 알려 주고, 필요하면 작업·공사의 중지 또는 계획서 변경을 명할 수 있다, 사업주는 계획서와 심사결과서를 사업장에 갖추어 두고, 공법 변경 등으로 변경이 필요하면 변경해 갖추어 둔다":"장관은 심사 결과를 서면으로 알리고 필요하면 작업·공사 중지나 계획서 변경을 명하며 사업주는 계획서와 심사결과서를 사업장에 갖추어 둡니다.","고용노동부장관은 심사하여 결과를 서면으로 알려 주고, 필요하면 변경을 명할 수 있다, 사업주는 심사를 받은 보고서를 사업장에 갖추어 둔다":"장관은 심사해 결과를 서면으로 알리고 필요하면 변경을 명하며 사업주는 심사받은 보고서를 사업장에 갖추어 둡니다.","고용노동부장관은 아래 사업장으로서 산업재해 예방을 위해 종합적인 개선조치가 필요하다고 인정되면 안전보건개선계획의 수립·시행을 명할 수 있다":"아래 사업장에 해당하고 종합적 개선이 필요하다고 인정되면 개선계획 수립·시행 명령을 받습니다.","고용노동부장관은 안전성능 저하 등으로 근로자에게 피해를 줄 우려가 크면 제조 과정을 조사하고 유해·위험기계등을 수거해 성능시험을 할 수 있다, 방해·거부 시 1년 이하 징역 또는 1천만원 이하 벌금":"안전성능 저하가 우려되면 장관이 제조 과정을 조사하고 기계등을 수거해 성능시험을 합니다.","고용노동부장관은 작업환경측정 결과의 신뢰성을 평가할 수 있다, 사업주와 근로자는 적극 협조":"장관이 측정 결과의 신뢰성을 평가할 수 있고 사업주와 근로자는 이에 협조해야 합니다.","고용노동부장관은 제출된 계획서를 심사해 결과를 서면으로 알리고, 필요하면 보완을 명할 수 있다":"제출된 계획서는 장관이 심사해 서면으로 결과를 알리고 보완이 필요하면 명합니다.","고용노동부장관은 중대재해, 그리고 화재·폭발·붕괴 등으로 발생한 중대재해 외 산업재해로서 고용노동부령으로 정하는 재해(중대재해등)가 발생하면 원인을 조사할 수 있다, 공단이나 관계전문가에게 별도로 실시하도록 할 수 있다":"장관은 중대재해와 화재·폭발·붕괴 등 중대재해 외의 일부 재해가 나면 원인을 조사하거나 공단·전문가에게 따로 조사하게 할 수 있습니다.","고용노동부장관은 중대재해등이 발생한 사업장의 사업주에게 안전보건개선계획의 수립·시행, 그 밖에 필요한 조치를 명할 수 있다":"중대재해등이 난 사업장은 장관이 안전보건개선계획을 세워 시행하도록 사업주에게 명할 수 있습니다.","고용노동부장관은 지도사의 등록을 취소하거나 2년 이내의 기간을 정하여 업무정지를 명할 수 있다":"등록 취소나 2년 이내의 업무정지는 장관이 명할 수 있습니다.","고용노동부장관은 직업성 질환의 진단·예방 및 발생 원인 규명을 위해 근로자의 질환과 작업장 유해요인의 상관관계에 관한 역학조사를 할 수 있다, 사업주 또는 근로자대표, 그 밖에 고용노동부령으로 정하는 사람이 요구하면 참석하게 할 수 있다":"고용노동부장관은 직업성 질환의 진단·예방과 원인 규명을 위해 질환과 작업장 유해요인의 상관관계를 보는 역학조사를 할 수 있습니다.","고용노동부장관은 추락·붕괴, 화재·폭발, 유해하거나 위험한 물질의 누출 등 산업재해 발생 위험이 현저히 높은 사업장의 사업주에게 안전보건진단기관의 안전보건진단을 받을 것을 명할 수 있다":"장관은 추락·붕괴, 화재·폭발, 유해물질 누출 등 위험이 현저히 높은 사업장의 사업주에게 안전보건진단기관의 진단을 받으라고 명할 수 있습니다.","고용노동부장관의 권한은 대통령령에 따라 일부를 지방고용노동관서의 장에게 위임할 수 있고, 일부 업무는 공단 또는 비영리법인·전문기관에 위탁할 수 있다 (위탁받은 비영리법인·전문기관 임직원은 형법 공무원 의제)":"장관 권한 일부는 지방관서에 위임하고 일부 업무는 공단·비영리법인에 위탁하며 임직원은 공무원으로 봅니다.","고용노동부장관의 시정조치: 사업주가 필요한 조치를 하지 않아 근로자에게 현저한 유해·위험이 우려되면 해당 기계·설비등에 대해 사용중지·대체·제거·시설 개선 등 시정조치 명령":"장관은 사업주가 조치를 하지 않아 근로자에게 현저한 위험이 우려되면 기계·설비의 사용중지·대체·제거·시설 개선 등을 명할 수 있습니다.","고용노동부장관의 작업중지: 중대재해 발생 작업 또는 동일 작업으로 재발 급박한 위험이 있으면 작업중지 명령, 토사·구축물 붕괴, 화재·폭발, 유해물질 누출 등으로 주변 확산 우려가 있는 불가피한 경우 사업장 작업 중지":"장관은 중대재해 작업이나 같은 작업에서 재발 급박한 위험이 있으면 작업중지를 명하고 주변 확산 우려가 있으면 사업장 작업을 중지시킵니다.","고용노동부장관이 수립하고, 산업재해보상보험및예방심의위원회의 심의를 거쳐 공표(변경도 같음)":"산업재해 예방 기본계획은 고용노동부장관이 세우고 심의위원회 심의를 거쳐 공표하며 변경도 같습니다.","고용노동부장관이 시행하는 지도사 자격시험에 합격한 사람은 지도사 자격을 가진다, 일부 면제 대상 자격 보유자는 시험 일부 면제 가능, 시험 실시를 전문기관에 대행시킬 수 있다":"시험 합격자가 지도사 자격을 가지며 일부 자격자는 시험이 일부 면제되고 실시를 대행시킬 수 있습니다.","고용노동부장관이 중앙행정기관·지방자치단체·공단 등에 정보 제공을 요청할 수 있는 것은 부가가치세법·법인세법에 따른 사업자등록 정보 / 고용보험법에 따른 근로자의 피보험자격의 취득 및 상실 등 정보 / 그 밖에 대통령령으로 정하는 정보":"장관이 정보 제공을 요청할 수 있는 것은 사업자등록 정보와 고용보험 피보험자격 취득·상실 정보, 대통령령 정보입니다.","고의 또는 과실로 의뢰인에게 손해를 입히면 배상 책임, 등록 지도사는 보험금액 2천만원(법인은 2천만원에 사원인 지도사 수를 곱한 금액) 이상 보증보험에 가입":"지도사가 고의나 과실로 의뢰인에게 손해를 입히면 배상 책임이 있고 등록 지도사는 보험금액 2천만원 이상 보증보험에 가입해야 합니다.","공단 소속 직원은 사업장에 출입해 산업재해 예방에 필요한 검사 및 지도 등을 할 수 있다, 검사·지도 업무를 한 때에는 그 결과를 고용노동부장관에게 보고해야 한다 (근로감독관·사업주 보고 아님)":"공단 직원은 사업장에 출입해 검사와 지도를 할 수 있고 그 결과를 근로감독관이나 사업주가 아니라 고용노동부장관에게 보고해야 합니다.","공단은 지도사에 대한 지도·연락 및 정보의 공동이용체제의 구축·유지, 지도사의 직무 수행과 관련된 사업주의 불만·고충의 처리 및 피해에 관한 분쟁의 조정 등을 한다":"공단은 지도사에 대한 지도·연락, 정보 공동이용체제 구축·유지, 사업주 불만·고충 처리와 분쟁 조정 등을 합니다.","공단이 역학조사를 할 수 있는 경우 1: 작업환경측정 또는 건강진단 결과만으로 직업성 질환 여부를 판단하기 곤란한 질병에 대하여 사업주·근로자대표·보건관리자(보건관리전문기관 포함)·건강진단기관의 의사가 요청":"공단은 작업환경측정이나 건강진단 결과만으로 직업성 질환 여부를 판단하기 곤란한 질병에 대해 사업주 등이 요청하면 역학조사를 할 수 있습니다.","공단이 평가할 수 있는 경우: 측정 결과가 노출기준 미만인데도 직업병 유소견자가 발생한 경우 / 공정설비·작업방법·사용 화학물질 변경 등 작업 조건의 변화가 없는데도 유해인자 노출수준이 현저히 달라진 경우 / 작업환경측정방법을 위반하여 측정한 경우 등 필요성이 인정되는 경우":"기준 미만인데 유소견자가 나왔거나 작업 조건 변화 없이 노출수준이 크게 달라지면 평가합니다.","공사금액 120억원(토목공사업 150억원) 이상 건설공사의 건설공사도급인은 근로자위원과 사용자위원이 같은 수로 구성되는 노사협의체를 구성·운영할 수 있다, 구성하면 위원회와 도급 협의체를 구성한 것으로 본다":"공사금액 120억원 이상 건설공사의 도급인은 노사협의체를 구성하면 위원회와 협의체를 모두 구성한 것으로 봅니다.","공사기간 단축 및 공법변경 금지: 건설공사발주자 또는 건설공사도급인은 설계도서 등에 따라 산정된 공사기간을 단축해서는 안 되고, 공사비를 줄이기 위해 위험성이 있는 공법을 사용하거나 정당한 사유 없이 정해진 공법을 변경해서는 안 된다, 위반 시 1천만원 이하 벌금":"발주자나 도급인은 산정된 공사기간을 단축하거나 공사비를 줄이려고 위험한 공법을 쓰거나 정당한 사유 없이 공법을 변경해서는 안 됩니다.","공사기간 연장: 불가항력 사유 또는 발주자 책임 사유로 지연되어 도급인이 산업재해 예방을 위해 요청하면 발주자는 특별한 사유가 없으면 연장해야 한다, 관계수급인도 도급인에게 요청 가능":"불가항력이나 발주자 책임으로 공사가 지연되어 도급인이 재해 예방을 위해 요청하면 발주자는 특별한 사유가 없으면 공사기간을 연장해야 합니다.","공정안전보고서를 제출한 유해·위험설비에 대해서는 유해위험방지계획서를 제출한 것으로 본다":"공정안전보고서를 낸 설비는 유해위험방지계획서도 낸 것으로 쳐 줍니다.","공정안전보고서 작성은 위원회 심의(미설치 시 근로자대표 의견), 안전보건개선계획 수립은 위원회 심의(미설치 시 근로자대표 의견)":"공정안전보고서 작성과 안전보건개선계획 수립은 위원회 심의를 거치며 위원회가 없으면 근로자대표 의견을 듣습니다.","공정안전자료 / 공정위험성 평가서 / 안전운전계획 / 비상조치계획 / 그 밖에 고용노동부장관이 고시하는 사항, 산업재해 예방에 관한 기본계획은 포함 사항이 아니다":"공정안전보고서에는 공정안전자료, 공정위험성 평가서, 안전운전계획, 비상조치계획 등이 포함되고 산업재해 예방 기본계획은 포함되지 않습니다.","공정안전자료: 취급·저장 유해·위험물질의 종류 및 수량 / 물질안전보건자료 / 유해하거나 위험한 설비의 목록 및 사양 / 운전방법을 알 수 있는 공정도면 / 각종 건물·설비의 배치도 / 폭발위험장소 구분도 및 전기단선도 / 위험설비의 안전설계·제작 및 설치 관련 지침서":"공정안전자료에는 유해·위험물질의 종류와 수량, 물질안전보건자료, 설비 목록 및 사양, 공정도면, 배치도, 폭발위험장소 구분도 등이 들어갑니다.","공정위험성평가서 및 잠재위험에 대한 사고예방·피해 최소화 대책 — 평가기법 중 하나 이상: 체크리스트 / 상대위험순위 결정(Dow and Mond Indices) / 작업자 실수 분석(HEA) / 사고 예상 질문 분석(What-if) / 위험과 운전 분석(HAZOP) / 이상위험도 분석(FMECA) / 결함 수 분석(FTA) / 사건 수 분석(ETA) / 원인결과 분석(CCA) / 이와 같은 수준 이상의 기술적 평가기법, 사고예방·피해최소화 대책은 잠재위험이 있다고 인정되는 경우에만 작성":"공정위험성평가서는 체크리스트, 상대위험순위 결정, What-if, HAZOP 등 평가기법 중 하나 이상으로 작성합니다.","공정·작업방법·설비·사용 화학물질에 변화가 없는 경우 연 1회 이상으로 줄일 수 있는 경우: 소음이 최근 2회 연속 85데시벨 미만 / 소음 외 모든 인자가 최근 2회 연속 노출기준 미만 (고시 물질 취급 공정 제외)":"변화가 없고 소음이 2회 연속 85데시벨 미만, 다른 인자가 기준 미만이면 연 1회로 줄일 수 있습니다.","공표방법: 관보, 전국을 보급지역으로 하는 일반일간신문 또는 인터넷 등에 게재":"공표는 관보, 전국 일반일간신문, 인터넷 등에 게재하는 방법으로 합니다.","과태료 부과기준: 같은 위반행위로 과태료를 받은 최근 5년 내 횟수에 따라 가중, 중대재해·중대산업사고 발생 사업장의 발생원인 조사에서 적발된 위반은 3차 이상 금액, 규모별 감경(50명 이상 100명 미만 100분의 90, 10명 이상 50명 미만 100분의 80, 10명 미만 100분의 70)":"과태료는 최근 5년 내 위반 횟수에 따라 가중하고 규모별로 감경하며 중대재해 조사에서 적발되면 3차 이상 금액입니다.","과태료 비교 예(2025 기출): 건강관리카드 양도·대여, 안전관리자 미선임, 안전보건조정자 미선임, 유해성·위험성 조사 결과 미제출(제109조제1항)은 모두 500만원 이하, 제10조제3항 후단 위반 관계수급인 자료 허위 제출은 1천만원 이하":"건강관리카드 양도·대여, 안전관리자 미선임, 안전보건조정자 미선임, 유해성·위험성 조사 결과 미제출은 모두 500만원 이하 과태료입니다.","관계수급인에 관한 자료를 제출하지 않거나 거짓으로 제출하면 과태료 1천만원 이하":"관계수급인 자료를 안 내거나 거짓으로 내면 1천만원 이하의 과태료가 부과됩니다.","관계수급인은 도급인의 순회점검을 거부·방해·기피해서는 안 되고 시정요구에 따라야 한다, 도급인은 관계수급인의 교육 장소·자료 제공 요청에 협조":"관계수급인은 순회점검을 막을 수 없고 시정요구를 따라야 하며 도급인은 교육 지원 요청에 협조합니다.","관계수급인 자료 미제출·거짓 제출 / 안전보건 현황 미공시 / 이사회 보고·승인 미이행 / 고객 응대 근로자 조치 위반 / 유해위험방지계획서·공정안전보고서 관련 의무 / 안전검사 미수검·사용 / 허용기준 초과 / 안전보건진단·개선계획 명령 위반 / 타워크레인 미등록 설치·해체 / 작업환경측정 미실시 / 휴게시설 설치·관리기준 미준수 / 건강진단 미실시 / 근로감독관의 검사·점검·수거 거부":"관계수급인 자료 미제출, 이사회 보고·승인 미이행, 안전검사 미수검·사용, 허용기준 초과 등도 과태료 대상입니다.","관리감독자가 있는 경우 건설기술 진흥법상 안전관리책임자 및 안전관리담당자를 각각 둔 것으로 본다(안전보건관리책임자가 있는 경우가 아님)":"건설기술 진흥법상 안전관리책임자와 안전관리담당자는 관리감독자가 있으면 각각 둔 것으로 보고, 안전보건관리책임자가 있는 경우가 아닙니다.","관리감독자의 역할과 임무, 기계·기구의 위험성과 작업의 순서 및 동선은 근로자 정기교육 내용이 아니다(후자는 채용 시·작업내용 변경 시 교육 내용)":"관리감독자의 역할과 임무는 근로자 정기교육 내용이 아니며, 기계·기구의 위험성과 작업 순서는 채용 시·변경 시 교육 내용입니다.","광물성 분진·목재 분진·소음 및 충격소음 — 12개월 이내, 24개월 / 그 밖의 모든 유해인자 — 6개월 이내, 12개월":"광물성·목재 분진과 소음은 12개월 이내 첫 검진 후 24개월, 나머지 인자는 6개월 후 12개월 주기입니다.","광업, 섬유제품 염색·정리, 모피, 신발, 코크스·석유정제, 화학, 의약품, 고무·플라스틱, 비금속 광물, 1차 금속, 금속가공, 기타 기계, 전자부품, 전기장비, 자동차, 기타 운송장비, 가구, 해체·선별·원료 재생, 자동차 수리, 허가·관리 대상 유해물질 제조·사용 사업(고시): 50명 이상 500명 미만 1명 이상, 500명 이상 2천명 미만 2명 이상, 2천명 이상 2명 이상(의사·간호사 1명 이상 포함)":"보건관리자를 두어야 하는 업종으로 광업, 화학, 금속, 자동차, 가구 제조업 등이 열거되며 규모에 따라 1명 이상 또는 2명 이상 둡니다.","교육은 등록한 안전보건교육기관에 위탁할 수 있다":"교육 실시를 직접 하지 않고 등록된 안전보건교육기관에 맡길 수 있습니다.","교육을 하려는 자는 대통령령으로 정하는 인력·시설·장비 요건을 갖추어 고용노동부장관에게 등록해야 한다 (지정이 아니라 등록)":"교육기관은 지정이 아니라 대통령령의 인력·시설·장비 요건을 갖추어 고용노동부장관에게 등록해야 합니다.","국소배기장치: 관계 법령 / 산업보건 개요 / 산업환기의 기본원리 / 국소환기장치의 설계 및 실습 / 국소배기장치 및 제진장치 검사기준 / 검사실습 및 체크리스트 작성 요령 / 검사원 직무, 이상 시 응급조치는 포함되지 않음(압력용기 과정에 포함)":"국소배기장치 검사원 교육은 산업환기 원리와 설계, 검사기준, 실습으로 구성되며 이상 시 응급조치는 압력용기 과정에 속합니다.","군수품은 MSDS 제외 대상 목록에 없다 (유해성 조사 제외 대상에는 군수품이 있음)":"군수품은 MSDS 제외 대상이 아니지만 유해성 조사 제외 대상에는 들어 있습니다.","굴착, 채석, 하역, 벌목, 운송, 조작, 운반, 해체, 중량물 취급, 그 밖의 작업 시 불량한 작업방법 등에 의한 위험 예방 조치":"굴착, 채석, 하역, 벌목, 운송, 중량물 취급 등의 작업에서 불량한 작업방법으로 생기는 위험을 예방하는 조치입니다.","규정 미작성 과태료 500만원 이하, 작성·변경 절차 위반(위원회 심의·의결 또는 근로자대표 동의 없음)도 500만원 이하":"규정을 작성하지 않거나 작성·변경 절차를 어기면 과태료 500만원 이하가 부과됩니다.","규정에 포함할 사항은 안전 및 보건에 관한 관리조직과 그 직무 / 안전보건교육 / 작업장의 안전 및 보건 관리 / 사고 조사 및 대책 수립 / 그 밖에 안전 및 보건에 관한 사항":"안전보건관리규정에는 관리조직과 직무, 안전보건교육, 작업장 안전·보건 관리, 사고 조사와 대책 수립 등을 담습니다.","규정은 단체협약 또는 취업규칙에 반할 수 없다, 반하는 부분은 단체협약 또는 취업규칙으로 정한 기준에 따른다":"안전보건관리규정은 단체협약이나 취업규칙에 반할 수 없고 반하는 부분은 그 협약이나 취업규칙 기준에 따릅니다.","그 밖에 해당 사업장 근로자의 안전 및 보건을 유지·증진시키기 위하여 필요한 사항":"근로자의 안전·보건을 유지·증진하기 위해 필요한 그 밖의 사항도 위원회가 다룹니다.","그 밖의 근로자: 16시간 이상(최초 작업 종사 전 4시간 이상, 12시간은 3개월 이내 분할 실시 가능), 단기간·간헐적 작업은 2시간 이상":"그 밖의 근로자 특별교육은 16시간 이상이고 최초 작업 전 4시간, 나머지 12시간은 3개월 이내 분할할 수 있습니다.","그 외 사업장은 영 별표 13의 유해·위험물질 중 하나 이상을 규정량 이상 제조·취급·저장하는 설비 및 그 설비의 운영과 관련된 모든 공정설비":"그 밖의 사업장은 영 별표 13의 유해·위험물질을 규정량 이상 제조·취급·저장하는 설비와 관련된 공정설비가 대상입니다.","근로가 금지·제한된 근로자가 건강을 회복하면 지체 없이 근로를 할 수 있도록 해야 한다":"건강을 되찾은 근로자는 지체 없이 다시 근로할 수 있게 해 줘야 합니다.","근로감독관은 기계·설비등에 대한 검사를 할 수 있으며, 검사에 필요한 한도에서 무상으로 제품·원재료 또는 기구를 수거할 수 있다, 결과는 사업주 등에게 서면으로 알려야 한다":"근로감독관은 기계·설비등을 검사하고 필요한 한도에서 무상으로 제품·원재료·기구를 수거할 수 있으며 결과를 사업주 등에게 서면으로 알립니다.","근로감독관은 법 시행을 위해 관계인에게 보고 또는 출석을 명할 수 있다, 출입 시 신분증표를 지니고 출입 시 성명·출입시간·목적 등이 표시된 문서를 관계인에게 내준다":"근로감독관은 관계인에게 보고나 출석을 명할 수 있고 출입할 때 신분증표를 지니며 성명·출입시간·목적 등이 적힌 문서를 관계인에게 줍니다.","근로감독관은 법 시행을 위해 필요하면 사업장, 각종 지정·등록 기관의 사무소, 석면해체·제거업자의 사무소, 지도사의 사무소에 출입해 질문, 장부·서류 검사, 안전보건 점검, 서류 제출 요구를 할 수 있다":"근로감독관은 사업장과 지정·등록 기관, 석면해체·제거업자, 지도사 사무소에 출입해 점검할 수 있습니다.","근로감독관은 사업장 감독 시 해당 사업장의 명예산업안전감독관을 참여시켜야 한다(없거나 참여를 거부하는 등 사정이 있으면 예외)":"근로감독관은 사업장을 감독할 때 그 사업장의 명예산업안전감독관을 참여시켜야 하며 사정이 있으면 예외입니다.","근로감독관의 검사·점검·수거를 거부·방해·기피하면 과태료 1천만원 이하, 질문에 대한 답변 거부·거짓 답변은 300만원 이하, 보고·출석 명령 위반은 500만원 이하":"감독관의 검사·수거를 방해하면 1천만원, 답변 거부는 300만원, 출석 명령 위반은 500만원 이하 과태료입니다.","근로 금지 대상: ① 전염될 우려가 있는 질병에 걸린 사람(전염을 예방하기 위한 조치를 한 경우는 제외) ② 조현병, 마비성 치매에 걸린 사람 ③ 심장·신장·폐 등의 질환이 있는 사람으로서 근로에 의하여 병세가 악화될 우려가 있는 사람 ④ 위에 준하는 질병으로서 고용노동부장관이 정하는 질병에 걸린 사람":"전염 우려 질병자, 조현병·마비성 치매 환자, 근로로 악화될 심장·신장·폐 질환자가 근로 금지 대상입니다.","근로자는 근로기준법 제2조제1항제1호에 따른 근로자 / 사업주는 근로자를 사용하여 사업을 하는 자 / 근로자대표는 근로자의 과반수로 조직된 노동조합이 있으면 그 노동조합, 없으면 근로자의 과반수를 대표하는 자":"근로자는 근로기준법상 근로자이고, 사업주는 근로자를 사용하는 자이며, 근로자대표는 과반수 노동조합 또는 과반수 대표자입니다.","근로자는 급박한 위험이 있으면 작업을 중지하고 대피할 수 있다, 지체 없이 관리감독자 또는 그 밖에 부서의 장에게 보고, 보고받은 관리감독자등은 필요한 조치":"근로자는 급박한 위험이 있으면 작업을 중지하고 대피할 수 있으며 지체 없이 관리감독자 등에게 보고합니다.","근로자는 사업장에서 법령 위반 사실이 있으면 고용노동부장관 또는 근로감독관에게 신고할 수 있다, 사업주는 신고를 이유로 해고나 불리한 처우를 해서는 안 된다(5년 이하 징역 또는 5천만원 이하 벌금)":"법령 위반을 신고한 근로자를 해고하거나 불리하게 대하면 5년 이하 징역 또는 5천만원 이하 벌금입니다.","근로자는 사업주의 안전조치·보건조치 중 고용노동부령으로 정하는 사항을 지켜야 한다":"근로자도 사업주의 안전·보건조치 중 고용노동부령이 정한 사항은 지켜야 합니다.","근로자는 이 법과 명령의 산업재해 예방 기준을 지키고, 사업주·근로감독관·공단 등 관계인이 실시하는 산업재해 예방 조치에 따라야 한다":"근로자는 법령의 재해 예방 기준을 지키고 사업주, 근로감독관, 공단 등이 하는 예방 조치에 따라야 합니다.","근로자대표(관계수급인 근로자대표 포함)가 요구하면 측정 시 근로자대표를 참석시켜야 한다, 예비조사에는 근로자대표 또는 해당 작업공정을 수행하는 근로자가 요구하면 참석시켜야 한다":"근로자대표가 요구하면 측정 때 참석시켜야 하고 예비조사에는 근로자대표나 해당 근로자가 요구하면 참석시켜야 합니다.","근로자대표가 요구하면 진단에 근로자대표를 참여시켜야 한다":"근로자대표가 요구하면 사업주는 진단 과정에 근로자대표를 함께하게 해야 합니다.","근로자대표가 추천한 명예감독관의 업무 범위는 해당 사업장 업무(제8호 제외), 노동조합·사업주단체·예방 관련 단체가 추천한 명예감독관은 제8호~제10호 업무만 가능, 사업장 산업재해 예방계획 수립 참여는 포함되지 않음":"단체가 추천한 명예감독관은 제8호~제10호 업무만 맡고 사업장 예방계획 수립 참여는 할 수 없습니다.","근로자대표는 안전보건진단 결과, 개선계획 수립·시행 사항을 사업주에게 통지해 줄 것을 요청할 수 있다":"근로자대표는 진단 결과와 개선계획 수립·시행 내용을 알려 달라고 사업주에게 요청할 수 있습니다.","근로자대표는 조합원과 비조합원의 비율을 반영하여 근로자위원을 지명하도록 노력":"지명할 때 조합원과 비조합원이 각각 얼마나 되는지 비율을 살펴 근로자위원을 정하도록 힘써야 합니다.","근로자대표·명예감독관·사업의 대표자·안전관리자·보건관리자가 출석할 수 없으면 해당 사업에 종사하는 사람 1명을 지정해 직무를 대리하게 할 수 있다":"근로자대표 등이 출석할 수 없으면 해당 사업에 종사하는 사람 1명을 지정해 직무를 대리하게 할 수 있습니다.","근로자를 채용할 때와 작업내용을 변경할 때 해당 작업에 필요한 교육":"새로 채용하거나 작업이 바뀌면 그 작업에 맞는 교육을 따로 해야 합니다.","근로자안전보건교육기관·직무교육기관 등록 신청은 주된 사무소 소재지를 관할하는 지방고용노동청장, 신청서를 받은 날부터 20일 이내 등록증 발급":"등록 신청은 주된 사무소 관할 지방고용노동청장에게 하며 신청서를 받은 날부터 20일 이내에 등록증을 발급합니다.","근로자위원 및 사용자위원 각 과반수의 출석으로 개의, 출석위원 과반수의 찬성으로 의결":"근로자위원과 사용자위원 각 과반수가 출석하면 회의를 열고 출석위원 과반수 찬성으로 의결합니다.","근로자위원은 전체 사업의 근로자대표 / 근로자대표가 지명하는 명예감독관 1명(없으면 근로자 1명) / 공사금액 20억원 이상 공사 관계수급인의 각 근로자대표":"노사협의체 근로자위원은 전체 사업의 근로자대표, 명예감독관 1명, 공사금액 20억원 이상 관계수급인의 근로자대표입니다.","근로 제한: 건강진단 결과 유기화합물·금속류 등 유해물질에 중독된 사람, 중독될 우려가 있다고 의사가 인정하는 사람, 진폐 소견이 있는 사람 또는 방사선에 피폭된 사람을 해당 유해물질·방사선 취급 업무 또는 건강을 악화시킬 우려가 있는 업무에 종사하도록 해서는 안 된다":"근로 제한은 유해물질에 중독된 사람, 중독될 우려가 있다고 의사가 인정한 사람, 진폐 소견자, 방사선 피폭자를 해당 업무에서 제한하는 것입니다.","금속 부식성 물질: 화학적인 작용으로 금속에 손상 또는 부식을 일으키는 물질":"금속 부식성 물질은 화학적 작용으로 금속을 손상시키거나 부식시키는 물질입니다.","금지 위반 도급 또는 승인 없는 도급, 승인받은 작업의 재하도급: 10억원 이하 과징금":"금지된 도급이나 승인 없는 도급, 승인받은 작업의 재하도급에는 10억원 이하의 과징금을 부과합니다.","금지하거나 다시 시작하도록 할 때는 미리 보건관리자(의사인 보건관리자만 해당), 산업보건의 또는 건강진단을 실시한 의사의 의견을 들어야 한다":"금지하거나 복귀시키기 전에 의사인 보건관리자나 산업보건의 등의 의견을 반드시 듣습니다.","금지 행위: 거짓이나 부정한 방법으로 의뢰인에게 법령 의무를 이행하지 않게 하는 행위 / 의뢰인에게 법령에 따른 신고·보고 등 의무를 이행하지 않게 하는 행위 / 법령에 위반되는 행위에 관한 지도·상담":"지도사는 거짓·부정한 방법으로 의뢰인이 법령 의무나 신고·보고 의무를 이행하지 않게 하거나 법령 위반 행위를 지도·상담해서는 안 됩니다.","기계·기구·설비를 설계·제조·수입하는 자, 원재료 등을 제조·수입하는 자, 건설물을 발주·설계·건설하는 자는 이 법의 기준을 지키고 물건으로 인한 산업재해 방지에 필요한 조치를 해야 한다":"기계·설비를 설계·제조·수입하는 자와 원재료 제조·수입자, 건설물 발주·설계·시공자도 법 기준을 지켜 재해 방지 조치를 해야 합니다.","기계·기구의 위험성과 작업의 순서 및 동선 / 작업 개시 전 점검 / 정리정돈 및 청소 / 사고 발생 시 긴급조치 / 물질안전보건자료":"채용 시·작업내용 변경 시 교육 내용은 기계·기구의 위험성, 작업 개시 전 점검, 정리정돈, 긴급조치, 물질안전보건자료입니다.","기계·설비: 연삭기 또는 연마기(휴대형 제외) / 산업용 로봇 / 혼합기 / 파쇄기 또는 분쇄기 / 식품가공용 기계(파쇄·절단·혼합·제면기만) / 컨베이어 / 자동차정비용 리프트 / 공작기계(선반, 드릴기, 평삭·형삭기, 밀링만) / 고정형 목재가공용 기계(둥근톱, 대패, 루타기, 띠톱, 모떼기 기계만) / 인쇄기":"자율안전확인 대상 기계·설비에는 연삭기, 산업용 로봇, 혼합기, 파쇄기, 컨베이어, 자동차정비용 리프트, 공작기계 등이 있습니다.","기관석면조사 대상: 건축물(주택 제외) 연면적 합계 50㎡ 이상이면서 철거·해체 부분 면적 합계 50㎡ 이상 / 주택(부속건축물 포함) 연면적 합계 200㎡ 이상이면서 철거·해체 부분 합계 200㎡ 이상 / 설비의 단열재·보온재·분무재·내화피복재·개스킷·패킹재·실링재 등 사용 면적 15㎡ 이상 또는 부피 1㎥ 이상 / 파이프 보온재 길이 80m 이상":"기관석면조사는 주택 외 건축물 50㎡ 이상, 주택 200㎡ 이상 철거·해체 등에 대해 합니다.","기관석면조사를 실시한 기관은 그 건축물·설비의 석면해체·제거를 해서는 안 된다, 석면해체·제거업자는 작업 전 고용노동부장관에게 신고하고 서류를 보존(30년)":"기관석면조사를 한 기관은 그 건축물의 석면해체·제거를 할 수 없고 해체·제거업자는 작업 전 장관에게 신고하고 서류를 30년 보존합니다.","기관석면조사 생략: 설계도서·자재 이력 등으로 석면을 포함하지 않음이 명백한 경우 / 석면이 중량비율 1퍼센트가 넘게 포함된 자재를 사용했음이 명백한 경우":"설계도서나 자재 이력으로 석면이 없음이 명백하거나 석면이 중량비율 1퍼센트를 넘는 자재 사용이 명백하면 기관석면조사를 생략합니다.","기술능력 및 생산체계 심사: 안전성능을 지속적으로 유지·보증하기 위해 사업장이 갖추어야 할 기술능력과 생산체계가 기준에 적합한지, 기간 30일(외국 제조는 45일)":"기술능력 및 생산체계 심사는 안전성능을 지속 유지할 능력이 기준에 맞는지 보며 기간은 30일이고 외국 제조는 45일입니다.","나머지 사업: 상시근로자 100명 이상":"나머지 사업은 상시근로자 100명 이상이면 위원회를 설치합니다.","나머지 사유(요건 미충족, 지정받은 사항 위반 등)는 취소 또는 업무정지를 선택하는 임의적 사유":"요건 미충족과 지정사항 위반 등 나머지 사유는 취소나 업무정지 중 고를 수 있는 임의적 사유입니다.","노무를 제공하는 사람이 업무에 관계되는 건설물·설비·원재료·가스·증기·분진 등에 의하거나 작업 또는 그 밖의 업무로 인하여 사망 또는 부상하거나 질병에 걸리는 것":"산업재해는 노무를 제공하는 사람이 업무 관련 건설물, 설비, 원재료, 가스, 분진 등이나 작업 때문에 사망, 부상, 질병에 걸리는 것입니다.","노출기준 초과, 평균보다 높은 산업재해율(2배 미만)만으로는 진단 병행 대상이 아니라 계획 수립·시행 명령 대상":"노출기준 초과나 2배 미만의 높은 재해율만으로는 진단 병행이 아니라 계획 수립·시행 명령 대상입니다.","농업·임업·어업, 위에 열거하지 않은 제조업, 전기·가스 등, 도매·소매, 숙박·음식점, 부동산업(부동산 관리업 제외 100명 이상), 사진처리업(100명 이상) 등: 50명 이상 1천명 미만 1명 이상, 1천명 이상 2명 이상":"농업·임업·어업, 열거하지 않은 제조업, 도매·소매, 숙박·음식점 등은 50명 이상 1천명 미만 1명 이상, 1천명 이상 2명 이상입니다.","농·임·어업, 전기·가스, 수도·하수·폐기물, 운수·창고, 도소매, 숙박·음식점, 인쇄·출판, 방송, 우편·통신, 부동산, 연구개발, 사진처리(100명), 시설관리·조경, 공공행정(현업), 학교(현업), 청소년수련시설, 보건업, 골프장, 개인·소비용품수리, 세탁업: 50명 이상 5천명 미만 1명 이상, 5천명 이상 2명 이상":"농·임·어업, 도소매, 숙박·음식점 등은 50명 이상 5천명 미만이면 1명 이상, 5천명 이상이면 2명 이상 둡니다.","누구든지 동력으로 작동하는 기계·기구로서 대통령령으로 정하는 것은 방호조치를 하지 않고서는 양도, 대여, 설치 또는 사용에 제공하거나 양도·대여 목적으로 진열해서는 안 된다":"동력으로 작동하는 기계·기구로서 대통령령으로 정한 것은 방호조치 없이 양도·대여·설치·사용에 제공하거나 양도·대여 목적으로 진열할 수 없습니다.","누구든지 인증을 받지 않거나 기준에 맞지 않게 되었거나 취소·표시 사용 금지를 받은 안전인증대상기계등을 제조·수입·양도·대여·사용하거나 진열할 수 없다(3년 이하 징역 또는 3천만원 이하 벌금), 수거·파기 명령 가능":"인증이 없거나 취소된 기계등을 만들거나 팔면 3년 이하 징역 또는 3천만원 이하 벌금이고 수거·파기를 명합니다.","누구든지 중대재해등 발생 현장을 훼손하거나 원인조사를 방해해서는 안 된다, 위반 시 1년 이하 징역 또는 1천만원 이하 벌금":"중대재해등 현장을 훼손하거나 원인조사를 방해하면 1년 이하 징역 또는 1천만원 이하 벌금에 처합니다.","누구든지 직업성 암을 유발하는 것으로 확인되어 근로자 건강에 특히 해롭다고 인정되는 물질, 또는 유해성·위험성이 평가·조사된 물질 중 중대한 건강장해를 일으킬 우려가 있는 물질로서 대통령령 물질(제조등금지물질)을 제조·수입·양도·제공 또는 사용해서는 안 된다, 위반 시 5년 이하 징역 또는 5천만원 이하 벌금":"직업성 암을 유발하는 것으로 확인된 물질 등 대통령령 물질은 제조등금지물질로서 누구든지 제조·수입·양도·제공·사용할 수 없습니다.","다음 작업에 종사하는 근로자에게는 안전·보건조치 외에 작업과 휴식의 적정한 배분 및 근로시간 관련 근로조건 개선 등 건강 보호 조치 — 6시간 제한과는 다름: 갱 내 작업 / 다량의 고열물체 취급 및 현저히 덥고 뜨거운 장소 작업 / 다량의 저온물체 취급 및 현저히 춥고 차가운 장소 작업 / 라듐방사선·엑스선·그 밖의 유해 방사선 취급 작업 / 유리·흙·돌·광물의 먼지가 심하게 날리는 장소 작업 / 강렬한 소음이 발생하는 장소 작업 / 착암기 등으로 신체에 강렬한 진동을 주는 작업 / 인력으로 중량물을 취급하는 작업 (동력 기계를 이용한 중량물 취급은 아님) / 납·수은·크롬·망간·카드뮴 등 중금속 또는 이황화탄소·유기용제, 그 밖에 고용노동부령 특정 화학물질의 먼지·증기·가스가 많이 발생하는 장소 작업":"갱 내 작업 등은 6시간 제한과 달리 작업과 휴식의 적정 배분 등 건강 보호 조치를 받습니다.","대상(영 별표 21) 건축물: 사무실 및 공장용 건축물":"대여 대상 건축물은 사무실 및 공장용 건축물입니다.","대상 1: 산업재해로 인한 사망자(사망재해자)가 연간 2명 이상 발생한 사업장":"공표 대상의 하나는 사망재해자가 연간 2명 이상 발생한 사업장입니다.","대상 2: 사망만인율(연간 상시근로자 1만명당 발생하는 사망재해자 수의 비율)이 규모별 같은 업종의 평균 사망만인율 이상인 사업장":"사망만인율은 상시근로자 1만명당 사망재해자 수의 비율이며 규모별 같은 업종 평균 이상인 사업장이 공표 대상입니다.","대상 3: 법 제44조제1항 전단에 따른 중대산업사고가 발생한 사업장":"법 제44조제1항 전단의 중대산업사고가 발생한 사업장도 공표 대상입니다.","대상 4: 법 제57조제1항을 위반하여 산업재해 발생 사실을 은폐한 사업장":"법 제57조제1항을 위반해 산업재해 발생 사실을 은폐한 사업장도 공표 대상입니다.","대상 5: 산업재해 발생 보고(법 제57조제3항)를 최근 3년 이내 2회 이상 하지 않은 사업장":"산업재해 발생 보고를 최근 3년 이내 2회 이상 하지 않은 사업장도 공표 대상입니다.","대상 기계 1: 이동식 크레인 / 타워크레인 / 불도저 / 모터 그레이더 / 로더 / 스크레이퍼 / 스크레이퍼 도저":"대여 대상 기계로 이동식 크레인, 타워크레인, 불도저, 모터 그레이더, 로더, 스크레이퍼 등이 있습니다.","대상 기계 2: 파워 셔블 / 드래그라인 / 클램셸 / 버킷굴착기 / 트렌치 / 항타기 / 항발기 / 어스드릴 / 천공기 / 어스오거 / 페이퍼드레인머신":"파워 셔블, 드래그라인, 클램셸, 항타기, 항발기, 어스드릴, 천공기 등도 대여 대상 기계입니다.","대상 기계 3: 리프트 / 지게차 / 롤러기 / 콘크리트 펌프 / 고소작업대 / 그 밖에 산업재해보상보험및예방심의위원회 심의를 거쳐 고용노동부장관이 고시하는 것":"리프트, 지게차, 롤러기, 콘크리트 펌프, 고소작업대와 장관이 고시하는 기계도 대여 대상입니다.","대상 업종: 금속가공제품 제조업(기계·가구 제외) / 비금속 광물제품 제조업 / 기타 기계 및 장비 제조업 / 자동차 및 트레일러 제조업 / 식료품 제조업 / 고무제품 및 플라스틱제품 제조업 / 목재 및 나무제품 제조업 / 기타 제품 제조업 / 1차 금속 제조업 / 가구 제조업 / 화학물질 및 화학제품 제조업 / 반도체 제조업 / 전자부품 제조업":"대상 업종에는 금속가공제품, 비금속 광물제품, 기타 기계 및 장비, 자동차 및 트레일러, 식료품, 고무·플라스틱, 목재 제조업 등이 있습니다.","대상 작업장: 별표 21의 측정 대상 유해인자에 노출되는 근로자가 있는 작업장, 제외 가능: 관리대상 유해물질 허용소비량 이하 / 임시 작업·단시간 작업(고시 물질 제외) / 분진작업 적용 제외 작업장 / 노출수준이 노출기준에 비해 현저히 낮다고 고시하는 작업장":"대상 작업장은 별표 21의 측정 대상 유해인자에 노출되는 근로자가 있는 곳이며 허용소비량 이하나 임시·단시간 작업 등은 제외할 수 있습니다.","대상 회사는 상시근로자 500명 이상 회사, 또는 건설산업기본법에 따라 공시된 시공능력(토목건축공사업) 순위 상위 1천위 이내 건설회사":"대상 회사는 상시근로자 500명 이상 회사이거나 시공능력 순위 상위 1천위 이내 건설회사입니다.","대여받는 자의 조치(근로자가 아닌 사람이 조작하는 경우): 조작자가 관계 법령상 자격·기능이 있는지 확인 / 조작자에게 작업 내용, 지휘계통, 연락·신호 방법, 운행경로·제한속도 등을 주지, 기종 선정 목적의 일시 대여는 제외":"근로자가 아닌 사람이 조작하는 경우 대여받는 자는 조작자의 자격·기능을 확인하고 작업 내용, 지휘계통, 신호 방법 등을 알려 줍니다.","대여자 조치 1: 기계등을 미리 점검하고 이상을 발견하면 즉시 보수 등 정비":"대여자는 기계등을 미리 점검하고 이상이 있으면 즉시 보수 등 정비해야 합니다.","대체자료로 적힌 정보 제공을 요구할 수 있는 자: 근로자를 진료하는 의사 / 보건관리자 및 보건관리전문기관 / 산업보건의 / 근로자대표 / 역학조사 실시 업무 위탁기관 / 업무상질병판정위원회":"대체자료로 적힌 정보의 제공을 요구할 수 있는 자는 근로자를 진료하는 의사, 보건관리자, 산업보건의, 근로자대표 등입니다.","대통령령 사유(영 제28조)는 관련 서류의 거짓 작성 / 정당한 사유 없이 수탁 거부 / 위탁받은 업무에 차질 또는 게을리함 / 업무 수행 없이 위탁 수수료 수령 / 비치서류 미보존 / 대가 외 금품 수령 / 관계 공무원의 지도·감독 거부·방해·기피":"대통령령 사유에는 서류 거짓 작성, 정당한 사유 없는 수탁 거부, 업무 소홀, 업무 없이 수수료 수령, 지도·감독 방해 등이 있습니다.","대통령령으로 정하는 건설공사의 발주자 또는 도급인(최초 도급받은 수급인 제외)은 착공 시 지도계약을 체결하고, 전문기관은 도급인에게 지도를 실시하며 도급인은 지도에 따라 적절한 조치를 한다, 지정 취소 규정은 제21조제4항·제5항 준용":"대통령령으로 정한 건설공사의 발주자나 도급인은 착공 시 전문기관과 지도계약을 체결하고 도급인은 지도에 따라 적절한 조치를 합니다.","대통령령으로 정하는 기계·기구·설비 또는 건축물 등을 타인에게 대여하거나 대여받는 자는 필요한 안전·보건조치를 해야 한다, 위반 시 3년 이하 징역 또는 3천만원 이하 벌금":"대여하거나 대여받는 자는 안전·보건조치를 해야 하고 어기면 3년 이하 징역 또는 3천만원 이하 벌금입니다.","대통령령으로 정한 공통 직무(안전·보건 모두): 위험성평가의 지도 / 안전보건개선계획서의 작성 / 그 밖에 산업안전(산업보건)에 관한 사항의 자문에 대한 응답 및 조언":"안전·보건지도사의 공통 직무는 위험성평가의 지도, 안전보건개선계획서의 작성, 자문에 대한 응답 및 조언입니다.","도급금지 등 의무위반 과징금: 10억원 이하, 고려사항: 도급 금액·기간·횟수 / 관계수급인 근로자 산재 예방 조치 노력 정도 / 산업재해 발생 여부, 가산금은 연 100분의 6 범위, 60개월 상한":"도급금지 위반 과징금은 10억원 이하이며 가산금은 연 100분의 6 범위에서 60개월을 넘지 않습니다.","도급은 명칭에 관계없이 물건의 제조·건설·수리 또는 서비스의 제공, 그 밖의 업무를 타인에게 맡기는 계약 / 도급인은 물건의 제조·건설·수리 또는 서비스의 제공, 그 밖의 업무를 도급하는 사업주, 다만 건설공사발주자는 제외 / 수급인은 도급인으로부터 물건의 제조·건설·수리 또는 서비스의 제공, 그 밖의 업무를 도급받은 사업주 / 관계수급인은 도급이 여러 단계에 걸쳐 체결된 경우 각 단계별로 도급받은 사업주 전부":"도급은 이름과 관계없이 제조, 건설, 수리, 서비스 제공 등을 타인에게 맡기는 계약이고, 도급인·수급인·관계수급인도 따로 정의합니다.","도급인은 관계수급인 근로자가 도급인의 사업장에서 작업하는 경우 그 사업장의 안전보건관리책임자를 안전보건총괄책임자로 지정해야 한다, 안전보건관리책임자를 두지 않아도 되는 사업장에서는 사업을 총괄하여 관리하는 사람을 지정":"도급인은 관계수급인 근로자가 일하는 사업장의 책임자를 안전보건총괄책임자로 지정해야 합니다.","도급인은 관계수급인 근로자가 도급인의 사업장에서 작업하는 경우 자신의 근로자와 관계수급인 근로자의 산업재해를 예방하기 위해 안전 및 보건 시설의 설치 등 필요한 안전조치 및 보건조치를 해야 한다, 다만 보호구 착용의 지시 등 관계수급인 근로자의 작업행동에 관한 직접적인 조치는 제외":"도급인은 자기 근로자와 관계수급인 근로자의 재해를 막기 위해 안전 및 보건 시설 설치 등 필요한 안전조치와 보건조치를 해야 합니다.","도급인은 수급인이 정보에 따라 필요한 조치를 했는지 확인":"수급인이 제공된 정보대로 필요한 조치를 했는지 도급인이 점검해야 합니다.","도급인은 자신의 근로자 및 관계수급인 근로자와 함께 정기적으로 또는 수시로 작업장의 안전 및 보건에 관한 점검을 해야 한다":"도급인은 작업장 안전·보건 점검을 자기 근로자, 관계수급인 근로자와 함께 정기·수시로 해야 합니다.","도급인의 사업장에서 관계수급인 또는 관계수급인의 근로자가 작업을 하는 경우에는 도급인이 자격을 가진 자로 하여금 측정을 하도록 해야 한다":"관계수급인이 도급인 사업장에서 일하면 측정은 도급인이 자격자에게 맡겨 합니다.","도급인이 선임한 전담 안전관리자·보건관리자가 있으면 관계수급인은 안전관리자·보건관리자를 선임하지 않을 수 있다(요건: 도급인 자신의 관리자 보유 + 수급인 상시근로자 수를 합계한 만큼 추가 선임)":"도급인이 선임한 전담 안전관리자·보건관리자가 있으면 관계수급인은 안전·보건관리자를 선임하지 않을 수 있습니다.","도급인이 시정조치할 수 있는 경우: 관계수급인 또는 근로자가 도급받은 작업과 관련해 법령을 위반하면 시정조치(관계수급인은 정당한 사유 없으면 따라야 한다)":"관계수급인이나 근로자가 도급받은 작업에서 법령을 위반하면 도급인이 시정조치할 수 있고 관계수급인은 정당한 사유 없이 거부할 수 없습니다.","도급인이 제공하지 않으면 수급인이 요청할 수 있고, 그래도 제공하지 않으면 수급인은 해당 도급 작업을 하지 않을 수 있으며 이행 지체 책임을 지지 않는다":"정보를 못 받은 수급인은 요청하고 그래도 안 받으면 작업을 거부해도 지체 책임을 지지 않습니다.","도로교통법에 따라 도로에서 발생한 교통사고로서 해당 공사의 공사용 차량·장비에 의한 사고는 제외 대상이 아니다":"도로에서 난 교통사고여도 공사용 차량·장비가 낸 사고는 산정 제외 대상이 아닙니다.","도시가스업은 통합공표 사업에 포함되지 않는다":"도시가스업은 통합공표 대상이 되는 업종에 들어가지 않습니다.","둘 이상의 사업장에 1명의 안전관리자를 공동으로 둘 수 있는 경우는 같은 사업주 경영, 같은 시·군·구 소재이거나 경계 기준 15킬로미터 이내, 상시근로자 합계 300명 이내(건설업은 공사금액 합계 120억원, 토목 150억원 이내)":"둘 이상의 사업장이 안전관리자를 공동으로 두려면 같은 사업주이고 15킬로미터 이내이며 근로자 합계 300명 이내여야 합니다.","등록 가능한 자는 근로자 안전보건교육기관은 법인 또는 산업 안전·보건 관련 학과가 있는 학교, 직무교육기관은 한국산업안전보건공단 또는 학교·비영리법인":"근로자 안전보건교육기관은 법인이나 관련 학과가 있는 학교, 직무교육기관은 한국산업안전보건공단이나 학교·비영리법인이 등록할 수 있습니다.","등록 갱신: 5년마다, 고용노동부령 지도실적이 있어야 하며, 실적이 기준에 못 미치면 보수교육을 받아 갱신":"지도사 등록은 5년마다 갱신하며 지도실적이 있어야 하고 실적이 기준에 못 미치면 보수교육을 받아 갱신합니다.","등록 신청: 설치·해체업 등록신청서에 인력 증명서류, 사무실 증명서류·장비 명세서를 첨부해 주된 사무소 소재지 관할 지방고용노동관서의 장에게 제출, 접수 후 20일 이내 등록증 발급":"등록 신청서에 인력 증명서류, 사무실 증명서류, 장비 명세서를 첨부해 제출하면 접수 후 20일 이내에 등록증을 발급합니다.","등록 신청: 주사무소를 설치하려는 지역 관할 지방고용노동관서의 장에게 신청서 제출(이중 등록 불가), 접수일부터 30일 이내 등록증 발급":"등록 신청은 주사무소를 설치할 지역 관할 지방고용노동관서의 장에게 하고 이중 등록은 불가하며 접수일부터 30일 이내에 등록증을 발급합니다.","등록 없이 타워크레인을 설치·해체하면 과태료 1천만원 이하":"등록하지 않고 타워크레인을 설치·해체하면 1천만원 이하 과태료를 냅니다.","등록 취소 사유(영 제73조): 안전조치(법 제38조)를 준수하지 않아 벌금형 또는 금고 이상 형 선고 / 관계 공무원의 지도·감독 거부·방해·기피, 취소된 날부터 2년 이내 재등록 불가":"등록 취소 사유에는 안전조치 미준수로 벌금형이나 금고 이상 형 선고, 공무원의 지도·감독 방해가 있고 취소 후 2년 이내 재등록은 불가합니다.","등록한 사항을 위반해 업무를 수행한 경우 등은 임의적(취소 또는 6개월 이내 정지)":"등록한 사항을 위반해 업무를 수행한 경우 등은 취소나 6개월 이내 정지 중 고를 수 있는 임의적 사유입니다.","등록할 수 없는 사람: 피성년후견인 또는 피한정후견인 / 파산선고를 받고 복권되지 않은 사람 / 금고 이상의 실형을 선고받고 집행이 끝나거나 면제된 날부터 2년이 지나지 않은 사람 / 금고 이상 형의 집행유예 기간 중인 사람 / 이 법을 위반하여 벌금형을 선고받고 1년이 지나지 않은 사람 / 등록 취소 후 2년이 지나지 않은 사람":"피성년후견인·피한정후견인, 파산선고를 받고 복권되지 않은 사람, 금고 이상 실형 집행 후 2년이 지나지 않은 사람 등은 등록할 수 없습니다.","망간 작업은 도급금지 작업 목록에 없다":"망간 작업은 도급금지 작업 목록에 들어 있지 않습니다.","면제 예: 건설안전기술사·기계안전기술사·산업위생관리기술사·인간공학기술사·전기안전기술사·화공안전기술사, 직업환경의학과 전문의 — 전공필수·공통필수Ⅰ·공통필수Ⅱ 면제 / 공인노무사 — 공통필수Ⅰ 면제 / 박사학위 소지자 등 — 전공필수 면제":"건설안전기술사·산업위생관리기술사 등과 직업환경의학과 전문의는 전공필수·공통필수Ⅰ·Ⅱ가 면제되고 공인노무사는 공통필수Ⅰ이 면제됩니다.","명예산업안전감독관은 근로자위원이다(사용자위원 아님)":"명예산업안전감독관은 사용자위원이 아니라 근로자위원입니다.","모든 측정은 개인 시료채취방법으로 하되, 개인 시료채취방법이 곤란한 경우에는 지역 시료채취방법으로 실시, 그 사유를 결과표에 분명하게 밝힐 것":"모든 측정은 개인 시료채취방법으로 하고 곤란하면 지역 시료채취방법으로 하되 그 사유를 결과표에 밝혀야 합니다.","물반응성 물질: 물과 상호작용을 하여 자연발화되거나 인화성 가스를 발생시키는 고체·액체 또는 혼합물":"물에 닿으면 자연발화하거나 인화성 가스를 내는 물질이 물반응성 물질입니다.","물질안전보건자료대상물질을 양도하거나 제공하는 자는 상대방에게 물질안전보건자료를 제공해야 한다, 변경된 자료도 제공(제조·수입자 및 중간 양도자)":"물질안전보건자료대상물질을 양도·제공하는 자는 상대방에게 자료를 제공해야 하고 변경된 자료도 제공해야 합니다.","물질안전보건자료대상물질을 제조하거나 수입하려는 자는 물질안전보건자료를 작성해 고용노동부장관에게 제출, 포함 사항: 제품명 / 분류기준에 해당하는 화학물질의 명칭 및 함유량 / 안전 및 보건상 취급 주의 사항 / 건강 및 환경에 대한 유해성, 물리적 위험성 / 물리·화학적 특성 등 고용노동부령 사항":"대상물질 제조·수입자는 제품명, 구성물질 명칭·함유량, 취급 주의사항을 담은 자료를 제출합니다.","반드시 등록을 취소해야 하는 경우(제1호~제3호): 거짓이나 부정한 방법으로 등록 또는 갱신등록을 한 경우 / 업무정지 기간 중에 업무를 수행한 경우 / 업무 관련 서류를 거짓으로 작성한 경우":"거짓·부정 등록이나 갱신, 업무정지 기간 중 업무 수행, 업무 서류 허위 작성은 반드시 등록을 취소해야 하는 경우입니다.","발암성 물질 등 중대한 건강장해 우려가 있는 대통령령 유해인자는 작업장 내 노출 농도를 허용기준 이하로 유지해야 한다, 예외: 시설·설비의 설치나 개선이 현존 기술로 불가능 / 천재지변 등으로 중대한 결함 발생 / 임시 작업과 단시간 작업 / 그 밖의 대통령령 경우":"발암성 물질 등은 노출 농도를 허용기준 이하로 유지해야 하고 현존 기술로 불가능한 때 등은 예외입니다.","발주자는 대장 기재 내용의 적정성 등을 안전보건 분야의 전문가에게 확인받아야 하며, 설계자·최초 수급인이 안전을 우선 고려할 수 있도록 적정한 비용과 기간을 계상·설정":"발주자는 대장 내용의 적정성을 안전보건 전문가에게 확인받고 설계자와 최초 수급인이 안전을 우선 고려하도록 적정한 비용과 기간을 정해야 합니다.","방사선: 직접·간접으로 공기 또는 세포를 전리하는 능력을 가진 알파선·베타선·감마선·엑스선·중성자선 등의 전자파나 입자선":"방사선은 공기나 세포를 전리하는 능력을 가진 알파선, 베타선, 감마선, 엑스선, 중성자선 등의 전자파나 입자선입니다.","방위사업법 제28조제1항 품질보증은 안전인증 면제 사유(안전검사 면제 사유에는 없음)":"방위사업법 품질보증은 안전인증은 면제하지만 안전검사 면제 사유에는 들어 있지 않습니다.","방호장치: 아세틸렌 용접장치용 또는 가스집합 용접장치용 안전기 / 교류 아크용접기용 자동전격방지기 / 롤러기 급정지장치 / 연삭기 덮개 / 목재 가공용 둥근톱 반발 예방장치와 날 접촉 예방장치 / 동력식 수동대패용 칼날 접촉 방지장치 / 추락·낙하·붕괴 방지용 가설기자재(안전인증 대상 제외, 고시)":"자율안전확인 대상 방호장치에는 아세틸렌 용접장치용 안전기, 교류 아크용접기용 자동전격방지기, 롤러기 급정지장치, 연삭기 덮개 등이 있습니다.","방호조치 해체: 사업주의 허가를 받아 해체 / 해체 사유 소멸 시 지체 없이 원상 회복 / 기능 상실을 발견하면 지체 없이 사업주에게 신고, 신고를 받은 사업주는 즉시 수리·보수·작업중지 등 조치":"방호조치는 사업주 허가를 받아 해체하고 사유가 없어지면 지체 없이 되돌리며 기능 상실을 발견하면 사업주에게 신고해야 합니다.","배치전건강진단: 특수건강진단대상업무에 종사할 근로자의 배치 예정 업무에 대한 적합성 평가를 위해 배치 전에 실시, 특수건강진단기관에 담당 업무·배치 작업장의 유해인자 등 정보를 미리 알려 준다":"배치전건강진단은 특수업무에 종사할 근로자의 적합성을 평가하려고 배치 전에 합니다.","법인 양벌: 사망 1명 이상 중대산업재해는 50억원 이하 벌금, 나·다목은 10억원 이하 벌금":"법인은 사망 1명 이상 중대산업재해면 50억원 이하, 나·다목이면 10억원 이하 벌금을 받습니다.","법 제15조제1항제1호~제5호 및 제7호에 관한 사항: 산업재해 예방계획 수립 / 안전보건관리규정 작성·변경 / 안전보건교육 / 작업환경측정 등 작업환경 점검·개선 / 건강진단 등 건강관리 / 산업재해 통계의 기록 및 유지":"위원회는 재해 예방계획, 안전보건관리규정, 교육, 작업환경 점검, 건강진단, 재해 통계에 관한 사항을 심의·의결합니다.","법 제15조제1항제6호(산업재해의 원인 조사 및 재발 방지대책 수립) 중 중대재해에 관한 사항":"산업재해 원인 조사와 재발 방지대책 수립 중 중대재해에 관한 사항도 위원회가 심의·의결합니다.","법 제21조제4항 준용 — 거짓·부정한 방법으로 등록한 경우, 업무정지 기간 중 업무 수행은 필수 취소":"거짓·부정한 방법으로 등록했거나 업무정지 기간에 업무를 수행하면 법 제21조제4항 준용으로 반드시 등록을 취소합니다.","법 제80조제2항 대상 방호조치: 작동 부분의 돌기부분은 묻힘형으로 하거나 덮개 부착 / 동력전달부분 및 속도조절부분에는 덮개 부착 또는 방호망 설치 / 회전기계의 물림점에는 덮개 또는 울 설치":"돌기부분은 묻힘형으로 하거나 덮개를 달고 동력전달부분은 덮개나 방호망을 달고 물림점에는 덮개나 울을 설치합니다.","변경등록 대상 중요 사항: 업체의 명칭(상호) / 소재지 / 대표자의 성명 / 보유 인력":"변경등록 대상은 업체의 명칭, 소재지, 대표자의 성명, 보유 인력입니다.","병역법에 따른 신체검사, 교육공무원법에 따른 신체검사는 일반건강진단을 실시한 것으로 보는 건강진단이 아니다":"병역법과 교육공무원법의 신체검사는 일반건강진단으로 인정되지 않습니다.","보건관리자가 고시하는 안전·보건 교육을 이수하면 면제되는 것은 보수교육이다(신규교육 아님)":"보건관리자가 고시된 안전·보건 교육을 이수해서 면제받는 것은 신규교육이 아니라 보수교육입니다.","보건관리자·보건관리전문기관 종사자: 신규 34시간 이상, 보수 24시간 이상":"보건관리자 쪽도 신규 교육 34시간 이상, 보수 교육 24시간 이상입니다.","보건관리자 신규: 법령 및 작업환경측정 / 개론 / 교육방법 / 산업보건관리계획 수립·평가 및 산업역학 / 작업환경 및 직업병 예방 / 작업환경 개선 / 산업역학 및 통계 / 산업환기 / 안전보건관리 체제·규정 및 보건관리자 역할 / 보건관리계획 및 운용 / 근로자 건강관리 및 응급처치 / 위험성평가 / 감염병 예방 / 자살 예방 / 그 밖에":"보건관리자 신규교육은 법령, 작업환경측정, 산업역학, 산업환기, 보건관리계획, 근로자 건강관리 등을 다룹니다.","보건관리자 업무 위탁 가능은 건설업 제외 사업으로서 상시근로자 300명 미만(업종별·유해인자별 전문기관은 고용노동부령 사업), 또는 외딴곳으로서 고용노동부장관이 정하는 지역의 사업장":"건설업을 제외하고 상시근로자 300명 미만이거나 외딴 지역 사업장은 보건관리자 업무를 위탁할 수 있습니다.","보건관리자 증원·교체 명령 사유는 안전관리자와 같다(직무수행 불가 3개월 이상 등)":"증원·교체를 명할 수 있는 사유가 안전관리자 때와 같아서 3개월 이상 직무 불능 등이 해당합니다.","보건관리전문기관은 지역별과 업종별·유해인자별로 구분":"보건관리전문기관은 지역별 기관과 업종별·유해인자별 기관으로 나뉘어 있습니다.","보건에 관한 기술적인 사항에 관하여 사업주 또는 안전보건관리책임자를 보좌하고 관리감독자에게 지도·조언하는 업무를 수행하는 사람":"보건관리자는 보건의 기술적 사항에 관해 사업주나 책임자를 보좌하고 관리감독자에게 지도·조언하는 사람입니다.","보건조치 대상: 원재료·가스·증기·분진·흄·미스트·산소결핍·병원체 / 방사선·유해광선·고열·한랭·초음파·소음·진동·이상기압 / 사업장 배출 기체·액체·찌꺼기 / 계측감시·컴퓨터 단말기 조작·정밀공작 / 단순반복작업·인체에 과도한 부담을 주는 작업 / 환기·채광·조명·보온·방습·청결 부적정 / 폭염·한파 장시간 작업":"보건조치 대상은 원재료·가스·분진 등, 방사선·고열·소음·진동·이상기압, 배출 기체·액체, 컴퓨터 단말기 작업 등 건강장해입니다.","보건진단은 종합진단 중 제2호·제3호·제4호 바목(허가대상물질, 관리대상 유해물질, 온도·습도·환기·소음·진동·분진·유해광선)·제5호 중 보건 관련 사항·제6호·제7호":"보건진단은 종합진단 중 재해 원인, 작업조건·방법, 허가대상물질·관리대상 유해물질과 온도·소음·분진 등, 보건 관련 사항을 다룹니다.","보고 기한·방법: 발생한 날부터 1개월 이내에 산업재해조사표를 작성해 관할 지방고용노동관서의 장에게 제출(전자문서 포함)":"산업재해조사표는 발생한 날부터 1개월 이내에 작성해 관할 지방고용노동관서의 장에게 전자문서로도 제출할 수 있습니다.","보고 대상: 사망자가 발생하거나 3일 이상의 휴업이 필요한 부상 또는 질병에 걸린 사람이 발생한 산업재해":"산업재해 보고 대상은 사망자가 났거나 3일 이상 휴업이 필요한 부상·질병자가 발생한 재해입니다.","보고 방법: 사업장 소재지를 관할하는 지방고용노동관서의 장에게 전화·팩스 또는 그 밖의 적절한 방법으로, 내용: 발생 개요 및 피해 상황 / 조치 및 전망 / 그 밖의 중요한 사항":"보고는 관할 지방고용노동관서의 장에게 전화나 팩스 등으로 하며 발생 개요와 피해 상황, 조치 및 전망 등을 알립니다.","보고·출석 명령은 문서로 하며 7일 이상의 기간을 준다(긴급한 경우 제외)":"보고·출석 명령은 문서로 하고 긴급한 경우를 제외하면 7일 이상의 기간을 줍니다.","보수교육: 신규교육 이수 후 매 2년이 되는 날을 기준으로 전후 6개월 사이에 고용노동부장관이 실시하는 보수교육":"보수교육은 신규교육을 이수한 뒤 매 2년이 되는 날을 기준으로 전후 6개월 사이에 장관이 실시합니다.","보수교육 면제는 영 별표 4 제8호 각 목 해당자 등이 해당 법령 교육기관에서 직무교육 내용이 포함된 교육을 이수하고 확인서를 제출한 경우 / 직무교육 대상자가 고용노동부장관이 고시하는 안전·보건에 관한 교육을 이수한 경우":"보수교육은 영 별표 4 제8호 해당자 등이 직무교육 내용이 포함된 교육을 이수하고 확인서를 내거나 고시된 안전·보건 교육을 이수하면 면제됩니다.","보완 상태 불량 시 보고서 변경 명령, 따르지 않으면 재제출 명령(명령 위반 3년 이하 징역 또는 3천만원 이하 벌금)":"보완이 불량하면 변경을 명하고 따르지 않으면 재제출을 명하며 위반하면 3년 이하 징역입니다.","보증보험금으로 손해배상을 한 경우 그 날부터 10일 이내 다시 가입, 가입한 날부터 20일 이내 지방고용노동관서에 신고":"배상에 쓴 날부터 10일 이내 다시 가입하고 가입 후 20일 이내 신고합니다.","보호구: 안전모(안전인증 대상인 추락·감전 방지용 제외) / 보안경(차광·비산물 방지용 제외) / 보안면(용접용 제외)":"자율안전확인 대상 보호구는 안전모, 보안경, 보안면이며 안전인증 대상인 추락·감전 방지용 안전모 등은 제외합니다.","부동산 임대업은 300명 열거 업종에 들지 않으므로 100명 이상이면 작성 대상":"임대업 중 부동산 임대업은 300명 기준 업종이 아니라서 100명 이상이면 규정을 작성합니다.","부상자 또는 직업성 질병자가 동시에 10명 이상 발생한 재해":"한꺼번에 10명 이상이 다치거나 직업성 질병에 걸린 경우도 중대재해로 봅니다.","부정행위자: 시험 무효, 처분일부터 5년간 시험응시자격 정지":"부정행위는 시험 무효와 함께 5년간 응시자격 정지 처분을 받습니다.","분류기준에 해당하지 않는 구성 화학물질의 명칭·함유량도 별도로 제출, 변경 시 변경 사항을 반영한 자료 제출":"분류기준 밖 구성물질도 명칭과 함유량을 따로 제출하고 변경 시 새 자료를 냅니다.","비고 제4~6호는 2025.5.30 삭제됨 (2023 기출 당시 일부 업종 정기교육 제외 규정이 있었음)":"비고 제4~6호는 삭제되었고 2023 기출 당시에는 일부 업종의 정기교육 제외 규정이 있었다는 메모입니다.","비밀 유지 의무: 유해위험방지계획서·공정안전보고서 검토자, 안전보건진단자, 원인조사자, 안전인증자, 자율안전확인 신고 수리자, 안전검사자, 자율검사프로그램 인정자, 유해성조사 검토자, MSDS 접수자, 건강진단자, 역학조사자, 등록 지도사 등은 업무상 알게 된 비밀을 누설·도용 금지 (1년 이하 징역 또는 1천만원 이하 벌금)":"계획서 검토자, 진단자, 원인조사자, 인증자, 검사자, 건강진단자 등은 비밀을 누설해서는 안 됩니다.","비상조치계획: 비상조치를 위한 장비·인력 보유현황 / 사고발생 시 각 부서·관련 기관과의 비상연락체계 / 비상조치를 위한 조직의 임무 및 수행 절차 / 비상조치계획에 따른 교육계획 / 주민홍보계획 / 그 밖에 비상조치 관련 사항":"비상조치계획에는 장비·인력 보유현황, 비상연락체계, 조직의 임무와 절차, 교육계획, 주민홍보계획 등이 들어갑니다.","사고사망만인율은 질병으로 인한 사망재해자를 제외하고 산출한 사망만인율":"질병으로 숨진 사람을 뺀 사고 사망자만으로 계산한 만인율을 사고사망만인율이라 합니다.","사망 1명 이상은 1년 이상 징역 또는 10억원 이하 벌금(병과 가능), 나·다목 중대산업재해는 7년 이하 징역 또는 1억원 이하 벌금":"사망 1명 이상이면 1년 이상 징역이나 10억원 이하 벌금이고 나·다목 재해는 7년 이하 징역입니다.","사망자가 1명 이상 발생한 재해":"중대재해 중 하나는 사망자가 1명 이상 발생한 재해입니다.","사망재해자 1명 발생, 중대재해 발생(중대재해는 공표 기준이 아님), 보고 1회 미이행은 공표 대상이 아니다":"사망자가 한 명뿐이거나 중대재해가 났거나 보고를 한 번 빠뜨린 정도는 공표 대상에 들지 않습니다.","사무직 종사 근로자: 매반기 6시간 이상":"사무직 종사 근로자의 정기교육은 매반기 6시간 이상입니다.","사업의 분류는 통계법에 따라 고시한 한국표준산업분류":"어떤 업종인지는 통계법에 따라 고시된 한국표준산업분류로 가립니다.","사업장의 생산과 관련되는 업무와 그 소속 직원을 직접 지휘·감독하는 직위에 있는 사람":"관리감독자는 생산 업무와 그 소속 직원을 직접 지휘하는 자리에 있는 사람입니다.","사업주, 안전보건관리책임자, 관리감독자는 안전관리자·보건관리자·안전보건관리담당자·전문기관이 지도·조언하면 이에 상응하는 적절한 조치를 해야 한다":"사업주, 책임자, 관리감독자는 관리자나 전문기관이 지도·조언하면 그에 상응하는 적절한 조치를 해야 합니다.","사업주는 감염병, 정신질환 또는 근로로 인하여 병세가 크게 악화될 우려가 있는 질병으로서 고용노동부령으로 정하는 질병에 걸린 사람에게는 의료법상 의사의 진단에 따라 근로를 금지하거나 제한해야 한다, 위반 시 1천만원 이하 벌금":"감염병, 정신질환, 근로로 병세가 크게 악화될 우려가 있는 질병에 걸린 사람은 의사의 진단에 따라 근로를 금지하거나 제한해야 합니다.","사업주는 근로자위원과 사용자위원이 같은 수로 구성되는 산업안전보건위원회를 구성·운영해야 한다":"사업주는 근로자위원과 사용자위원이 같은 수로 이루어진 산업안전보건위원회를 두고 운영합니다.","사업주는 근로자의 건강관리나 그 밖에 보건관리자의 업무를 지도하기 위해 산업보건의를 두어야 한다, 의사를 보건관리자로 둔 경우는 제외":"의사가 보건관리자인 경우를 빼고 사업주는 근로자 건강관리를 지도할 산업보건의를 둡니다.","사업주는 근로자의 안전·보건에 유해하거나 위험한 작업을 도급하여 자신의 사업장에서 수급인의 근로자가 작업하도록 해서는 안 된다: ① 도금작업 ② 수은, 납 또는 카드뮴을 제련·주입·가공 및 가열하는 작업 ③ 허가대상물질(제118조제1항)을 제조하거나 사용하는 작업":"사업주는 도금작업, 수은·납·카드뮴 제련·가공 작업, 허가대상물질 제조·사용 작업 등 유해하거나 위험한 작업을 도급해서는 안 됩니다.","사업주는 급박한 위험이 있다고 믿을 만한 합리적인 이유가 있어 작업을 중지하고 대피한 근로자에게 해고나 그 밖의 불리한 처우를 해서는 안 된다":"위험하다고 믿을 이유가 있어 작업을 멈추고 피한 근로자를 해고하는 등 불리하게 대할 수 없습니다.","사업주는 대통령령으로 정하는 유해하거나 위험한 설비가 있는 경우 중대산업사고를 예방하기 위해 공정안전보고서를 작성해 고용노동부장관에게 제출하고 심사를 받아야 한다, 적합 통보 전에는 해당 설비를 가동해서는 안 된다":"유해·위험설비 사업주는 공정안전보고서를 내고 심사받아야 하며 적합 통보 전에는 가동하지 못합니다.","사업주는 명령을 받으면 안전보건진단기관에 진단을 의뢰하고, 진단에 적극 협조해야 한다":"명령을 받은 사업주는 안전보건진단기관에 진단을 의뢰하고 진단에 적극 협조해야 합니다.","사업주는 방호조치가 정상적인 기능을 발휘할 수 있도록 방호조치와 관련되는 장치를 상시적으로 점검하고 정비해야 한다":"사업주는 방호조치가 정상 기능을 하도록 관련 장치를 상시적으로 점검하고 정비해야 합니다.","사업주는 사업장을 실질적으로 총괄하여 관리하는 사람에게 아래 업무를 총괄하여 관리하도록 해야 한다":"사업장을 실제로 총괄 관리하는 사람이 아래 업무를 한꺼번에 맡도록 사업주가 정해야 합니다.","사업주는 산업재해가 발생하였을 때 그 발생 사실을 은폐해서는 안 된다, 은폐하거나 은폐를 교사·공모한 자는 1년 이하 징역 또는 1천만원 이하 벌금":"산업재해가 발생했을 때 사실을 은폐하거나 은폐를 교사·공모한 자는 1년 이하 징역 또는 1천만원 이하 벌금입니다.","사업주는 산업재해가 발생할 급박한 위험이 있으면 즉시 작업을 중지시키고 근로자를 대피시키는 등 필요한 조치":"급박한 위험이 있으면 사업주가 작업을 바로 멈추고 근로자를 대피시키는 조치를 해야 합니다.","사업주는 산업재해 예방을 위한 조치를 할 수 있는 능력을 갖춘 사업주에게 도급해야 한다":"도급은 재해 예방 조치를 할 능력이 있는 사업주에게만 줄 수 있습니다.","사업주는 상시 사용하는 근로자의 건강관리를 위하여 일반건강진단을 실시해야 한다, 특수건강진단기관 또는 건강검진기본법상 건강검진기관에서 실시":"일반건강진단은 상시 근로자를 위해 특수건강진단기관 등에서 실시해야 합니다.","사업주는 소속 근로자에게 고용노동부령으로 정하는 바에 따라 정기적으로 안전보건교육을 하여야 한다":"사업주는 소속 근로자에게 정기적으로 안전보건교육을 실시해야 하며 방법은 고용노동부령이 정합니다.","사업주는 위험성평가에 근로자를 참여시키고, 근로자대표가 요구하면 근로자대표를 참여시켜야 한다, 관련 사항을 근로자에게 알리고 결과를 기록·보존":"사업주는 평가에 근로자를 참여시키고 근로자대표가 요구하면 대표도 참여시켜 결과를 기록합니다.","사업주는 유해·위험 요인을 찾아내 위험성의 크기가 허용 가능한 수준인지 결정하고, 줄이기 위한 개선대책을 수립·이행(위험성평가)해야 한다":"위험성평가는 사업주가 유해·위험 요인을 찾아 위험성이 허용 가능한지 결정하고 개선대책을 수립·이행하는 것입니다.","사업주는 인체에 해로운 작업을 하는 작업장으로서 고용노동부령으로 정하는 작업장에 대해 고용노동부령으로 정하는 자격을 가진 자로 하여금 작업환경측정을 하도록 해야 한다":"사업주는 인체에 해로운 작업을 하는 작업장에 대해 고용노동부령 자격을 가진 자로 하여금 작업환경측정을 하게 해야 합니다.","사업주는 자신의 사업장에서 급성 독성, 피부 부식성 등이 있는 물질의 취급 등 대통령령으로 정하는 작업을 도급하려면 고용노동부장관의 승인을 받아야 하며, 안전 및 보건에 관한 평가를 받아야 한다":"급성 독성, 피부 부식성 등이 있는 물질을 취급하는 작업을 도급하려면 장관의 승인과 안전 및 보건에 관한 평가를 받아야 합니다.","사업주는 중대재해가 발생하면 즉시 작업을 중지시키고 근로자를 대피시키는 등 필요한 조치를 해야 한다, 위반 시 5년 이하 징역 또는 5천만원 이하 벌금":"중대재해가 나면 사업주는 즉시 작업을 중지시키고 근로자를 대피시켜야 하며 위반하면 5년 이하 징역 또는 5천만원 이하 벌금입니다.","사업주는 중대재해 발생 사실을 알게 되면 지체 없이 고용노동부장관에게 보고, 천재지변 등 부득이한 사유는 소멸 후 지체 없이 보고":"사업주는 중대재해 발생을 알면 지체 없이 장관에게 보고하며 천재지변 등은 사유가 소멸한 후 지체 없이 보고합니다.","사업주는 직무 수행과 관련한 사유로 명예산업안전감독관에게 불리한 처우를 해서는 안 된다":"사업주는 명예산업안전감독관의 직무 수행과 관련한 사유로 불리한 처우를 해서는 안 됩니다.","사업주는 책임자가 업무를 원활히 수행할 수 있도록 권한·시설·장비·예산, 그 밖에 필요한 지원을 해야 한다":"사업주는 책임자가 업무를 원활히 하도록 권한, 시설, 장비, 예산 등 필요한 지원을 해야 합니다.","사업주는 총괄책임자를 선임하면 선임 사실과 직무 수행내용을 증명할 서류를 갖추어 둔다, 미지정 과태료 500만원 이하":"총괄책임자 선임 서류를 갖추어 두어야 하고 지정하지 않으면 500만원 이하 과태료입니다.","사업주는 측정 결과를 해당 작업장 근로자에게 알려야 하고, 결과에 따라 시설·설비의 설치·개선 또는 건강진단 실시 등의 조치를 해야 한다":"측정 결과는 근로자에게 알리고 필요하면 시설 개선이나 건강진단을 해야 합니다.","사업주는 측정을 작업환경측정기관에 위탁할 수 있고, 필요하면 시료의 분석만을 위탁할 수 있다":"측정은 측정기관에 위탁할 수 있고 시료 분석만 따로 맡길 수도 있습니다.","사업주 또는 근로자대표가 요청하려면 산업안전보건위원회 의결 또는 상대방의 동의를 받는다(지방고용노동관서의 장이 필요성을 인정하면 예외), 산업안전보건위원회 위원장과 역학조사평가위원회 위원장은 요청권자가 아니다":"사업주나 근로자대표의 요청은 위원회 의결 또는 상대방 동의가 필요하며 관서장이 인정하면 예외입니다.","사업주 및 근로자는 적극 협조해야 하며, 정당한 사유 없이 거부·방해·기피해서는 안 된다(사업주 1,500만원, 근로자 5만원~ 과태료), 참석이 허용된 사람의 참석을 거부·방해해서는 안 된다(1,500만원), 참석자는 알게 된 비밀을 누설·도용 금지(1년 이하 징역 또는 1천만원 이하 벌금)":"사업주와 근로자는 역학조사에 협조해야 하고 거부·방해·기피하거나 참석이 허용된 사람의 참석을 막으면 과태료를 냅니다.","사업주와 근로자가 방호조치를 해체하려는 경우 등 고용노동부령으로 정하는 경우에는 필요한 안전·보건조치를 해야 한다":"방호조치를 해체하려는 경우 등에는 고용노동부령이 정한 안전·보건조치를 따라야 합니다.","사업주와 근로자는 규정을 지켜야 한다, 이 법에서 정하지 않은 사항은 근로기준법 중 취업규칙에 관한 규정을 준용":"사업주와 근로자 모두 규정을 따라야 하고 법에 없는 내용은 근로기준법의 취업규칙 조항을 준용합니다.","사업주와 근로자는 심사를 받은 개선계획서를 준수해야 한다":"심사를 마친 개선계획서는 사업주와 근로자가 모두 지켜야 합니다.","사업주와 근로자는 심사받은 보고서 내용을 지켜야 한다, 이행 여부에 대해 고용노동부장관의 확인을 받아야 한다, 변경 사유가 생기면 지체 없이 내용을 보완":"심사받은 보고서는 사업주와 근로자 모두 지키며 이행 확인을 받고 변경 사유는 곧바로 보완합니다.","사업주와 근로자는 심의·의결한 사항을 성실하게 이행, 위원에게 직무 수행과 관련한 사유로 불리한 처우 금지":"사업주와 근로자는 의결한 사항을 성실히 이행해야 하고 위원에게 직무 수행 관련 불리한 처우를 해서는 안 됩니다.","사업주의 법 위반으로 인한 것이 아니라고 인정되는 재해에 의한 사고사망자는 사고사망자 수 산정에서 제외: 방화·근로자 간 또는 타인 간 폭행 / 태풍 등 천재지변에 의한 불가항력적 재해 / 야유회 중 사고 등 건설작업과 직접 관련이 없는 경우":"방화·폭행, 천재지변의 불가항력, 야유회 사고처럼 사업주의 법 위반과 무관한 재해의 사고사망자는 산정에서 제외합니다.","사용자위원은 전체 사업의 대표자 / 안전관리자 1명 / 보건관리자 1명(보건관리자 선임 대상 건설업) / 공사금액 20억원 이상 공사 관계수급인의 각 대표자":"노사협의체 사용자위원은 전체 사업의 대표자, 안전관리자 1명, 보건관리자 1명, 관계수급인의 각 대표자입니다.","사용중지·작업중지 명령을 받은 사업주는 시정조치를 마치면 해제를 요청할 수 있고, 고용노동부장관은 완료되었다고 판단되면 해제해야 한다":"사용중지·작업중지 명령을 받은 사업주가 시정조치를 마치고 해제를 요청하면 장관은 완료되었다고 판단할 때 해제해야 합니다.","사유: 거짓·부정한 방법으로 인증 받은 경우(필수 취소) / 안전에 관한 성능이 인증기준에 맞지 않게 된 경우 / 정당한 사유 없이 확인을 거부·방해·기피한 경우, 취소 또는 6개월 이내 표시 사용 금지 또는 시정 명령":"거짓·부정 인증은 필수 취소이고 기준에 안 맞게 되었거나 확인을 방해한 경우는 취소 또는 6개월 이내 표시 사용 금지·시정 명령입니다.","산업보건에 관한 조사·연구는 산업보건지도사의 직무이며 산업안전지도사의 직무가 아니다, 유해·위험 방지대책 평가·지도, 공정상의 안전 평가·지도는 안전지도사 직무, 작업환경 평가·개선 지도, 건강진단 사후관리 지도는 보건지도사 직무":"산업보건에 관한 조사·연구는 산업보건지도사의 직무이고 산업안전지도사의 직무가 아니며 공정상 안전 평가·지도는 안전지도사의 직무입니다.","산업보건의는 외부에서 위촉할 수 있다, 선임·위촉·해임·해촉한 날부터 14일 이내 고용노동부장관에게 증명서류 제출":"산업보건의는 외부에서 위촉할 수 있고 선임·위촉·해임·해촉한 날부터 14일 이내에 증명서류를 장관에게 내야 합니다.","산업보건의 선임에 관한 서류 보존기간 3년":"산업보건의 선임에 관한 서류는 3년 동안 보존해야 합니다.","산업보건의 선임 의무 위반 과태료 500만원 이하":"산업보건의를 선임해야 하는데 선임하지 않으면 과태료 500만원 이하가 부과됩니다.","산업 안전 및 보건에 관한 기준을 확립하고 책임의 소재를 명확하게 하여 산업재해를 예방하고 쾌적한 작업환경을 조성함으로써 노무를 제공하는 사람의 안전 및 보건을 유지·증진":"산업안전보건법은 안전·보건 기준을 확립하고 책임 소재를 밝혀 재해를 예방하며 쾌적한 작업환경을 만들려는 법입니다.","산업 안전 및 보건 정책의 수립 및 집행 / 산업재해 예방 지원 및 지도 / 근로기준법 제76조의2에 따른 직장 내 괴롭힘 예방을 위한 조치기준 마련, 지도 및 지원 / 사업주의 자율적인 산업 안전 및 보건 경영체제 확립을 위한 지원 / 산업 안전 및 보건에 관한 의식을 북돋우기 위한 홍보·교육 등 안전문화 확산 추진 / 산업 안전 및 보건에 관한 기술의 연구·개발 및 시설의 설치·운영 / 산업재해에 관한 조사 및 통계의 유지·관리 / 산업 안전 및 보건 관련 단체 등에 대한 지원 및 지도·감독 / 그 밖에 노무를 제공하는 사람의 안전 및 건강의 보호·증진":"정부는 안전·보건 정책 수립, 예방 지도, 직장 내 괴롭힘 예방 조치기준 마련, 안전문화 확산, 기술 개발, 통계 관리 등을 합니다.","산업안전 및 산업재해 예방(화재·폭발 사고 발생 시 대피 포함) / 산업보건 및 건강장해 예방(폭염·한파작업 건강장해 발생 시 응급조치 포함) / 위험성 평가에 관한 사항 / 건강증진 및 질병 예방에 관한 사항 / 유해·위험 작업환경 관리에 관한 사항 / 산업안전보건법령 및 산업재해보상보험 제도에 관한 사항 / 직무스트레스 예방 및 관리에 관한 사항 / 직장 내 괴롭힘, 고객의 폭언 등으로 인한 건강장해 예방 및 관리에 관한 사항":"근로자 정기교육 내용에는 산업안전, 산업보건, 위험성 평가, 건강증진, 유해·위험 작업환경 관리, 산업안전보건법령이 들어갑니다.","산업안전 및 산업재해 예방(화재·폭발 시 대피 포함) / 산업보건 및 건강장해 예방 / 위험성 평가 / 산업안전보건법령 및 산업재해보상보험 제도 / 직무스트레스 예방 및 관리 / 직장 내 괴롭힘·고객의 폭언 등 건강장해 예방 및 관리":"근로자 정기교육 내용에는 재해 예방, 보건, 위험성 평가, 산재보험 제도, 직무스트레스, 직장 내 괴롭힘 예방이 포함됩니다.","산업안전보건관리비: 발주자가 도급계약을 체결하거나 시공을 주도하여 총괄·관리하는 자가 사업 계획을 수립할 때 도급금액 또는 사업비에 계상, 건설공사도급인은 사용명세서를 작성·보존, 산업재해 예방 외 목적으로 사용 금지":"산업안전보건관리비는 도급금액 또는 사업비에 계상하고 도급인이 사용명세서를 작성·보존하며 재해 예방 외 목적으로는 쓸 수 없습니다.","산업안전보건법의 중대재해(위 3가지)와 중대재해 처벌 등에 관한 법률의 중대산업재해는 기준이 다르다":"산업안전보건법과 중대재해처벌법은 중대재해와 중대산업재해의 기준을 서로 다르게 정합니다.","산업안전보건위원회·노사협의체 회의록: 2년 보존":"산업안전보건위원회와 노사협의체의 회의록은 2년 동안 보존합니다.","산업안전보건위원회 또는 근로자대표가 요구하면 사업주가 직접 또는 건강진단기관이 결과를 설명, 개별 근로자의 건강진단 결과는 본인 동의 없이 공개 불가":"위원회나 근로자대표가 요구하면 사업주나 건강진단기관이 결과를 설명하며 개별 근로자의 결과는 본인 동의 없이 공개하지 않습니다.","산업안전보건위원회 또는 근로자대표가 요구하면 측정 결과에 대한 설명회 등을 개최해야 한다, 위탁한 경우 작업환경측정기관에 설명하도록 할 수 있다":"위원회나 근로자대표가 요구하면 측정 결과 설명회를 열어야 하고 위탁했다면 측정기관이 설명하도록 할 수 있습니다.","산업재해 또는 사고의 발생 원인(발생한 경우만) / 작업조건 및 작업방법 평가 / 유해·위험요인 측정·분석 / 보호구·안전보건장비·작업환경 개선시설의 적정성 / 유해물질의 사용·보관·저장, 물질안전보건자료, 근로자 교육, 경고표시 부착의 적정성 / 그 밖에 보건관리 개선에 필요한 사항":"진단 항목에는 재해 원인, 작업조건 평가, 유해요인 측정·분석, 보호구·시설 적정성, 교육과 경고표시 등이 있습니다.","산업재해발생률 등을 고려한 기준(규칙 별표 11)에 적합한 건설업체는 스스로 심사하고 심사결과서를 제출(자체심사 및 확인업체)":"재해율이 낮은 건설업체는 스스로 심사하고 결과서를 내는 자체심사 및 확인업체입니다.","산업재해 발생 보고 및 응급조치 업무는 관리감독자의 업무":"산업재해 발생 보고와 응급조치 업무는 안전관리자가 아니라 관리감독자의 업무입니다.","산업재해 발생 원인 등 기록 보존기간 3년":"산업재해 발생 원인 등의 기록은 3년간 보존합니다.","산업재해 보고 미이행: 과태료 1차 700만원·2차 1,000만원·3차 1,500만원, 거짓 보고는 1,500만원 (법 상한 1,500만원)":"산업재해 보고를 하지 않으면 과태료 1차 700만원, 2차 1,000만원, 3차 1,500만원이고 거짓 보고는 1,500만원입니다.","산업재해에 관한 통계의 기록 및 유지는 관리감독자 업무 목록에 없다(안전보건관리책임자 업무)":"산업재해 통계의 기록 및 유지는 관리감독자가 아니라 안전보건관리책임자의 업무입니다.","산업재해 예방계획의 적정성 평가는 종합진단(경영·관리적 사항)에 속한다, 안전진단이 아니다":"예방계획의 적정성은 안전진단이 아니라 경영·관리적 사항을 보는 종합진단에서 평가합니다.","산업재해 예방활동 보조·지원: 거짓·부정한 방법으로 받은 경우 등 취소·환수, 취소된 날부터 5년 이내의 기간을 정하여 지원하지 않을 수 있다":"보조·지원을 부정하게 받으면 취소·환수하고 5년 이내 기간 동안 지원하지 않을 수 있습니다.","산업재해율이 같은 업종 평균 산업재해율의 2배 이상인 사업장 / 사업주가 필요한 안전조치 또는 보건조치를 이행하지 않아 중대재해가 발생한 사업장 / 직업성 질병자가 연간 2명 이상(상시근로자 1천명 이상 사업장은 3명 이상) 발생한 사업장 / 제3호의2에 해당하는 사업장(법 제56조제1항제2호 산업재해가 최근 1년 이내 2회 이상 발생) / 그 밖에 작업환경 불량, 화재·폭발 또는 누출 사고 등으로 사업장 주변까지 피해가 확산된 사업장으로서 고용노동부령으로 정하는 사업장":"재해율이 평균의 2배 이상이거나 직업성 질병자가 연 2명 이상(1천명 이상은 3명)이면 대상입니다.","산업재해의 발생 원인 등을 기록하여 보존, 기록 사항: 사업장 개요 및 근로자 인적사항 / 재해 발생 일시 및 장소 / 발생 원인 및 과정 / 재발방지 계획":"사업주는 재해 원인 등을 기록·보존해야 하고 사업장 개요와 근로자 인적사항, 일시·장소, 원인과 과정, 재발방지 계획을 적습니다.","산업재해조사표에는 근로자대표의 확인을 받아야 하고 이견이 있으면 그 내용을 첨부, 근로자대표가 없으면 재해자 본인의 확인을 받아 제출 가능":"조사표는 근로자대표 확인을 받아야 하고 이견은 덧붙이며 대표가 없으면 재해자 본인 확인을 받습니다.","산업재해 중 사망 등 재해 정도가 심하거나 다수의 재해자가 발생한 경우로서 고용노동부령으로 정하는 재해":"중대재해는 사망 등 재해 정도가 심하거나 다수의 재해자가 발생한 산업재해로 고용노동부령이 정합니다.","산화성 가스: 일반적으로 산소를 공급함으로써 공기보다 다른 물질의 연소를 더 잘 일으키거나 촉진하는 가스":"산소를 공급해 다른 물질이 더 잘 타게 하는 가스가 산화성 가스입니다.","산화성 액체·산화성 고체: 그 자체로는 연소하지 않더라도 일반적으로 산소를 발생시켜 다른 물질을 연소시키거나 연소를 촉진하는 액체·고체":"산화성 액체·고체는 그 자체는 연소하지 않아도 산소를 발생시켜 다른 물질의 연소를 일으키거나 촉진하는 물질입니다.","상법 제170조에 따른 주식회사 중 대통령령으로 정하는 회사의 대표이사는 매년 회사의 안전 및 보건에 관한 계획을 수립해 이사회에 보고하고 승인을 받아야 한다":"대통령령으로 정한 주식회사의 대표이사는 매년 안전·보건 계획을 세워 이사회에 보고하고 승인을 받아야 합니다.","상시근로자 300명 이상: 농업 / 어업 / 소프트웨어 개발·공급업 / 컴퓨터 프로그래밍·시스템 통합·관리업 / 영상·오디오물 제공 서비스업 / 정보서비스업 / 금융·보험업 / 임대업(부동산 제외) / 전문·과학·기술 서비스업(연구개발업 제외) / 사업지원 서비스업 / 사회복지 서비스업":"상시근로자 300명 이상인 업종으로 농업, 어업, 소프트웨어, 금융·보험업, 사회복지 서비스업 등이 열거됩니다.","상시근로자 300명 이상: 농업 / 어업 / 소프트웨어 개발·공급업 / 컴퓨터 프로그래밍·시스템 통합·관리업 / 영상·오디오물 제공 서비스업 / 정보서비스업 / 금융·보험업 / 임대업(부동산 제외) / 전문·과학·기술 서비스업(연구개발 제외) / 사업지원 서비스업 / 사회복지 서비스업":"위원회 설치 대상 중 300명 이상 업종으로 농업, 어업, 소프트웨어, 금융·보험업 등이 있습니다.","상시근로자 50명 이상 100명 미만 사업장은 ⑤(부서의 장)를 제외하고 사용자위원을 구성할 수 있다":"상시근로자 50명 이상 100명 미만이면 부서의 장 몫을 빼고 사용자위원을 정할 수 있습니다.","상시근로자 50명 이상: 토사석 광업 / 목재·나무제품 제조업(가구 제외) / 화학물질·화학제품 제조업(의약품 제외; 세제·화장품·광택제·화학섬유 제외) / 비금속 광물제품 / 1차 금속 / 금속가공제품(기계·가구 제외) / 자동차·트레일러 / 기타 기계·장비(사무용 제외) / 기타 운송장비(전투용 차량 제외)":"위원회 설치 대상 중 상시근로자 50명 이상인 업종으로 토사석 광업, 목재, 화학물질, 금속, 자동차, 기계 제조업 등이 열거됩니다.","상시근로자 50명 이상: 토사석 광업 / 식료품·음료 제조업 / 목재·나무제품(가구 제외) / 펄프·종이 / 코크스·연탄·석유정제품 / 화학물질·화학제품(의약품 제외) / 의료용 물질·의약품 / 고무·플라스틱 / 비금속 광물제품 / 1차 금속 / 금속가공제품(기계·가구 제외) / 전자부품·컴퓨터·영상·음향·통신장비 / 의료·정밀·광학기기·시계 / 전기장비 / 기타 기계·장비 / 자동차·트레일러 / 기타 운송장비 / 가구 / 기타 제품 제조업 / 서적·잡지·기타 인쇄물 출판업 / 해체·선별·원료 재생업 / 자동차 종합·전문 수리업":"상시근로자 50명 이상인 업종으로 토사석 광업, 식료품·음료, 목재, 화학, 금속, 전자부품 제조업 등이 열거됩니다.","생물학적 인자: 혈액매개 감염인자(HIV, B형·C형간염바이러스, 매독바이러스 등) / 공기매개 감염인자(결핵·수두·홍역 등) / 곤충 및 동물매개 감염인자(쯔쯔가무시증, 렙토스피라증, 유행성출혈열, 탄저병, 브루셀라병 등)":"생물학적 인자는 혈액매개, 공기매개, 곤충 및 동물매개 감염인자로 나뉘며 HIV, 결핵, 탄저병 등이 예입니다.","서류를 보존하지 않으면 과태료 300만원 이하 (각 서류당 1차 30만원·2차 150만원·3차 300만원)":"서류를 보존하지 않으면 1차 30만원, 2차 150만원, 3차 300만원의 과태료입니다.","서면심사: 설계도면 등 제품기술 관련 문서가 안전인증기준에 적합한지, 기간 15일(외국 제조는 30일)":"서면심사는 설계도면 등 문서가 인증기준에 맞는지 심사하며 기간은 15일이고 외국 제조는 30일입니다.","서면을 발급받지 못하면 대여받은 자는 정보 제공을 요구할 수 있다, 반환 시 수리·보수 내역과 부품교체 사항 정보를 제공":"서면을 못 받은 경우 정보 제공을 요구할 수 있고 반환할 때는 수리·보수·부품교체 정보를 제공합니다.","석면농도 기준 초과 시 건축물·설비의 철거·해체 금지(위반 5천만원 이하 과태료), 기관석면조사 없이 철거·해체하면 5천만원 이하 과태료":"석면농도가 기준을 초과하면 철거·해체를 할 수 없고 기관석면조사 없이 철거·해체하면 5천만원 이하 과태료입니다.","석면조사기관은 고용노동부장관의 지정을 받는다, 석면조사 결과 서류: 일반석면조사는 철거·해체작업 종료까지, 기관석면조사는 3년 보존":"석면조사기관은 장관이 지정하며 결과 서류는 일반은 작업 종료까지, 기관조사는 3년 보존합니다.","석면조사기관 종사자: 신규 34시간 이상, 보수 24시간 이상":"석면조사기관 종사자는 신규 교육 34시간, 보수 교육 24시간 이상을 받습니다.","석면해체·제거업자를 통해야 하는 경우: 벽체·바닥재·천장재·지붕재에 석면 1퍼센트 초과 + 자재 면적 합 50㎡ 이상 / 석면 1퍼센트 초과 분무재·내화피복재 사용 / 그 밖의 자재 면적 합 15㎡ 이상 또는 부피 1㎥ 이상 / 파이프 보온재 석면 1퍼센트 초과 + 길이 80m 이상":"석면 1퍼센트 초과 자재 50㎡ 이상 등에는 석면해체·제거업자를 거쳐야 합니다.","석면해체·제거 작업기준 준수: 위반 시 3년 이하 징역 또는 3천만원 이하 벌금(제123조제1항), 작업 완료 후 공기 중 석면농도가 기준 이하가 되도록 하고 증명자료를 제출":"석면해체·제거 작업기준을 어기면 3년 이하 징역 또는 3천만원 이하 벌금이고 작업 완료 후 공기 중 석면농도가 기준 이하임을 증명해야 합니다.","선임 대상은 보건관리자를 두어야 하는 사업으로서 상시근로자 50명 이상 사업장, 의사를 보건관리자로 선임했거나 보건관리전문기관에 위탁한 경우는 제외":"선임 대상은 보건관리자를 두어야 하는 상시근로자 50명 이상 사업장이고, 의사 보건관리자를 두었거나 전문기관에 위탁하면 제외합니다.","선임 대상은 제조업, 임업, 하수·폐수·분뇨 처리업, 폐기물 수집·운반·처리 및 원료 재생업, 환경 정화 및 복원업의 상시근로자 20명 이상 50명 미만 사업장에 1명 이상":"선임 대상은 제조업, 임업, 하수·폐수·분뇨 처리업 등의 상시근로자 20명 이상 50명 미만 사업장에 1명 이상입니다.","선임되어 있지 않은 산업보건의는 위원이 아니다":"선임이 안 된 상태의 산업보건의는 위원회에 위원으로 들어가지 않습니다.","선임 사실과 업무 수행내용을 증명할 수 있는 서류를 갖추어 둔다, 선임에 관한 서류 보존기간은 3년":"선임 사실과 업무 수행내용을 증명할 서류를 갖추어 두며 선임 서류의 보존기간은 3년입니다.","선임·위탁한 날부터 14일 이내, 해임·위탁 해지한 날부터 14일 이내에 고용노동부장관에게 증명서류 제출":"안전관리자를 선임·위탁하거나 해임·해지한 날부터 14일 이내에 증명서류를 고용노동부장관에게 내야 합니다.","설치·이전하는 경우 안전인증을 받아야 하는 기계: 크레인, 리프트, 곤돌라":"설치하거나 이전할 때 안전인증을 받아야 하는 기계는 크레인, 리프트, 곤돌라입니다.","성능이 자율안전기준에 맞지 않게 된 경우: 6개월 이내의 기간을 정해 표시 사용 금지 또는 시정 명령, 사용을 금지한 날부터 30일 이내에 명칭·형식번호, 자율안전확인번호, 제조자(수입자), 사업장 소재지, 사용금지 기간 및 사유를 관보 등에 공고":"성능이 자율안전기준에 맞지 않으면 6개월 이내 기간을 정해 표시 사용 금지나 시정 명령을 하고 30일 이내에 관보 등에 공고합니다.","세부 내용 1 총칙: 작성 목적·적용 범위 / 사업주·근로자의 재해 예방 책임·의무 / 하도급 사업장 안전·보건관리":"규정의 첫째 항목인 총칙에는 작성 목적과 적용 범위, 사업주와 근로자의 책임, 하도급 사업장 관리가 들어갑니다.","소득세법에 따른 납세실적 정보는 요청 대상으로 규정되어 있지 않다":"납세실적 정보는 소득세법에 따른 것이라도 정보 제공 요청 대상으로 정해져 있지 않습니다.","소음: 소음성난청을 유발할 수 있는 85데시벨(A) 이상의 시끄러운 소리":"85데시벨(A) 이상이어서 소음성난청을 일으킬 수 있는 소리가 소음입니다.","수립·시행 명령은 별지 제26호서식, 명령을 받은 날부터 60일 이내에 관할 지방고용노동관서의 장에게 개선계획서 제출":"명령을 받은 날부터 60일 안에 별지 제26호서식 개선계획서를 관서의 장에게 내야 합니다.","수시건강진단: 특수건강진단대상업무로 인한 것으로 의심되는 건강장해 증상이 있거나 의학적 소견이 있는 근로자로서 산업보건의·보건관리자·보건관리전문기관의 건의, 또는 근로자·근로자대표·명예산업안전감독관의 요청이 있는 사람, 지체 없이 실시":"수시건강진단은 특수건강진단대상업무로 인한 것으로 의심되는 건강장해 증상이 있는 근로자에 대해 산업보건의 등의 건의나 근로자 요청으로 실시합니다.","순회점검 주기: 건설업, 제조업, 토사석 광업, 서적·잡지 및 기타 인쇄물 출판업, 음악 및 기타 오디오물 출판업, 금속 및 비금속 원료 재생업은 2일에 1회 이상, 그 밖의 사업은 1주일에 1회 이상":"도급인의 순회점검은 건설업과 제조업 등은 2일에 1회 이상, 그 밖의 사업은 1주일에 1회 이상 합니다.","승인 대상 작업 1: 중량비율 1퍼센트 이상의 황산, 불화수소, 질산 또는 염화수소를 취급하는 설비를 개조·분해·해체·철거하는 작업 또는 해당 설비 내부에서 이루어지는 작업, 도급인이 해당 화학물질을 모두 제거한 후 증명자료를 첨부하여 고용노동부장관에게 신고한 경우는 제외":"황산, 불화수소, 질산, 염화수소를 1퍼센트 이상 취급하는 설비의 개조·해체나 내부 작업이 승인 대상입니다.","승인 대상 작업 2: 그 밖에 산업재해보상보험및예방심의위원회의 심의를 거쳐 고용노동부장관이 정하는 작업":"그 밖에 심의위원회의 심의를 거쳐 고용노동부장관이 정하는 작업도 승인 대상입니다.","승인받은 사항 중 도급공정, 도급공정 사용 최대 유해화학물질량, 도급기간(3년 미만으로 승인받은 자가 승인일부터 3년 내에서 연장하는 경우)을 변경하려면 변경승인을 받아야 한다":"승인받은 도급공정, 최대 유해화학물질량, 도급기간을 3년 안에서 연장하는 등 변경하려면 변경승인을 받아야 합니다.","승인 신청 시 받는 평가의 종류는 종합평가·안전평가·보건평가이고, 수급인의 안전보건관리 능력의 적정성은 세 평가에 공통 항목":"승인 신청 때 받는 평가 세 가지에는 수급인의 안전보건관리 능력 적정성이 공통으로 들어갑니다.","승인·연장승인·변경승인을 받은 자가 기준에 미달하게 되면 승인을 취소해야 한다":"승인받은 뒤 기준에 못 미치게 되면 장관은 승인을 취소해야 합니다.","승인 유효기간·연장·변경·취소에 관해 제58조제4항~제8항을 준용(유효기간 3년, 연장 3년)":"승인 유효기간, 연장, 변경, 취소는 제58조제4항~제8항을 준용하며 유효기간과 연장은 각각 3년입니다.","승인을 받아 도급받은 수급인은 그 작업을 하도급할 수 없다":"하도급은 승인받은 수급인에게 허용되지 않아 그 작업을 다시 맡길 수 없습니다.","승인을 받으려면 고용노동부장관이 실시하는 안전 및 보건에 관한 평가를 받아야 한다":"승인 신청 전에 고용노동부장관이 진행하는 안전·보건 평가를 먼저 받아야 합니다.","승인의 유효기간은 3년의 범위에서 정한다":"승인은 한 번에 3년 범위 안에서만 유효기간을 정합니다.","승인 취소: 거짓·부정한 방법으로 받은 경우(필수), 승인받은 물질이 비공개 불가 물질이 된 경우":"거짓·부정한 방법으로 승인을 받았거나 승인받은 물질이 비공개 불가 물질이 되면 승인을 취소합니다.","시설 기준: 사무실, 장비 기준: 렌치류, 드릴링머신, 버니어캘리퍼스, 트랜싯, 체인블록 및 레버블록, 전기테스터기, 송수신기":"시설은 사무실을 갖추고 장비는 렌치류, 드릴링머신, 버니어캘리퍼스, 트랜싯, 체인블록, 전기테스터기, 송수신기를 갖춥니다.","시정조치 명령을 받은 사업주는 완료할 때까지 명령 사항을 근로자가 쉽게 볼 수 있는 곳에 게시, 이행하지 않으면 작업의 전부 또는 일부의 중지 명령":"시정조치 명령을 받으면 이행을 마칠 때까지 명령 내용을 눈에 띄는 곳에 게시해야 합니다.","신고 면제: 연구·개발 목적 제조·수입 또는 수출 목적 제조 / 안전인증(제84조제3항)을 받은 경우 / 다른 법령상 안전성 검사·인증을 받은 경우로서 — 농업기계화촉진법 검정, 산업표준화법 제15조 인증, 전기용품 및 생활용품 안전관리법 안전인증·안전검사, IECEx 인증":"연구·개발 목적, 수출 목적 제조나 안전인증을 받은 경우, 다른 법령상 안전성 검사·인증을 받은 경우는 신고가 면제됩니다.","신고 면제자나 신고하지 않은 자가 자율안전확인표시를 하면 안 된다, 표시 임의 변경·제거 금지(1년 이하 징역 또는 1천만원 이하 벌금)":"신고 면제자나 미신고자는 표시를 못 하며 임의로 바꾸거나 제거하면 1년 이하 징역 또는 1천만원 이하 벌금입니다.","신고 시기·방법: 출고 또는 수입하기 전에 자율안전확인 신고서에 제품 설명서와 자율안전기준 충족 증명서류를 첨부해 공단에 제출, 공단은 신고를 받은 날부터 15일 이내 신고증명서 발급":"출고나 수입 전에 신고서에 제품 설명서와 자율안전기준 충족 증명서류를 첨부해 공단에 내면 15일 이내에 신고증명서를 발급합니다.","신고한 자는 자율안전기준에 맞는 것임을 증명하는 서류를 보존(2년), 자율안전확인표시를 해야 한다":"신고한 자는 증명서류를 2년 보존하고 자율안전확인표시를 붙여야 합니다.","신규교육: 해당 직위에 선임(위촉)되거나 채용된 후 3개월 이내 (보건관리자가 의사이면 1년 이내)":"선임되거나 채용되고 3개월 안에 신규교육을 받으며 보건관리자가 의사이면 1년까지 가능합니다.","신규교육 면제 대상은 안전보건관리담당자 / 영 별표 4 제6호에 해당하는 안전관리자(이공계 전문대학 이상 + 관리감독자 3년 등) / 영 별표 4 제7호에 해당하는 안전관리자":"신규교육 면제 대상은 안전보건관리담당자와 영 별표 4에 해당하는 일부 안전관리자입니다.","신규화학물질을 제조하거나 수입하려는 자는 유해성·위험성을 조사하고 조사보고서를 고용노동부장관에게 제출해야 한다, 일반 소비자 생활용 수입, 소량 수입 등은 제외":"신규화학물질 제조·수입자는 유해성 조사 후 보고서를 장관에게 내며 소비자 생활용 등은 제외됩니다.","신규화학물질제조자등이 양도·제공하면 조치 사항을 기록한 서류를 함께 제공":"신규화학물질을 넘기거나 줄 때는 조치 사항을 적은 서류도 함께 줍니다.","신청 서류: 도급대상 작업의 공정 관련 서류 일체 / 도급작업 안전보건관리계획서 / 안전 및 보건에 관한 평가 결과, 접수일부터 14일 이내 승인서 발급":"신청할 때는 도급 공정 서류, 도급작업 안전보건관리계획서, 안전 및 보건 평가 결과를 내고 접수일부터 14일 이내에 승인서를 발급받습니다.","실시 순서: ① 유해·위험 요인 파악 ② 위험성 크기가 허용 가능한 수준인지 결정 ③ 허용 불가능이면 개선대책 수립·이행":"위험성평가는 요인 파악, 허용 가능 여부 결정, 허용 불가능이면 개선대책 수립·이행의 순서로 합니다.","실시한 것으로 인정되는 건강진단: 국민건강보험법에 따른 건강검진 / 선원법에 따른 건강진단 / 진폐의 예방과 진폐근로자의 보호 등에 관한 법률에 따른 정기 건강진단 / 학교보건법에 따른 건강검사 / 항공안전법에 따른 신체검사 / 일반건강진단 검사항목을 모두 포함하여 실시한 건강진단":"국민건강보험법 건강검진, 선원법·학교보건법·항공안전법에 따른 건강진단 등은 일반건강진단을 실시한 것으로 인정합니다.","심사받은 사업주는 계획서 이행에 대해 고용노동부장관의 확인을 받아야 한다(자체심사업체는 스스로 확인, 건설공사 중 근로자가 사망하면 장관 확인), 확인 결과 미조치 시 시설 개선·사용중지·작업중지 명령":"심사받은 사업주는 계획서 이행에 대해 장관의 확인을 받아야 하고 미조치 시 시설 개선·사용중지·작업중지 명령을 받습니다.","아래에 해당하는 동력 기계·기구도 방호조치 없이는 양도 등을 할 수 없다: 작동 부분에 돌기 부분이 있는 것 / 동력전달 부분 또는 속도조절 부분이 있는 것 / 회전기계에 물체 등이 말려 들어갈 부분이 있는 것":"작동 부분에 돌기가 있거나 동력전달·속도조절 부분이 있거나 물체가 말려 들어갈 부분이 있는 동력 기계·기구도 방호조치 없이 양도할 수 없습니다.","안전검사기관은 고용노동부장관이 안전검사 업무를 위탁받아 수행하는 기관으로 지정, 취소·정지는 제21조제4항·제5항 준용(취소 또는 6개월 이내 정지)":"안전검사기관은 장관이 지정하며 취소·정지는 제21조제4항·제5항을 준용해 취소나 6개월 이내 정지를 합니다.","안전검사기관·자율안전검사기관 종사자: 신규 34시간 이상, 보수 24시간 이상":"검사기관 종사자도 신규 34시간 이상, 보수 24시간 이상으로 안전관리자와 같습니다.","안전검사대상: 프레스 / 전단기 / 크레인(정격 하중 2톤 미만 제외) / 리프트 / 압력용기 / 곤돌라 / 국소 배기장치(이동식 제외) / 원심기(산업용만) / 롤러기(밀폐형 구조 제외) / 사출성형기(형 체결력 294킬로뉴턴 미만 제외) / 고소작업대(화물자동차·특수자동차에 탑재한 것) / 컨베이어 / 산업용 로봇 / 혼합기 / 파쇄기 또는 분쇄기":"프레스, 전단기, 크레인, 리프트, 압력용기, 곤돌라, 국소 배기장치, 원심기, 롤러기, 사출성형기 등이 대상입니다.","안전검사대상기계등을 사용하는 사업주는 안전검사를 받아야 한다, 사업주와 소유자가 다르면 소유자가 안전검사를 받는다":"안전검사대상기계등을 사용하는 사업주가 안전검사를 받아야 하며 소유자가 다르면 소유자가 받습니다.","안전검사 대상 사업주가 근로자대표와 협의(근로자를 사용하지 않으면 제외)해 검사기준·주기를 충족하는 자율검사프로그램을 정하고 고용노동부장관의 인정을 받아 자격 있는 사람에게 자율안전검사를 받으면 안전검사를 받은 것으로 본다":"근로자대표와 협의해 검사기준·주기를 충족하는 자율검사프로그램을 정해 장관의 인정을 받아 검사를 받으면 안전검사를 받은 것으로 봅니다.","안전검사를 받지 않았거나 불합격한 기계등은 사용 금지":"검사를 받지 않았거나 불합격한 기계등은 쓸 수 없습니다.","안전검사 신청: 검사 주기 만료일 30일 전까지 안전검사기관에 제출, 기관은 주기 만료일 전후 각 30일 이내에 검사하고, 그 기간 내 합격하면 만료일에 받은 것으로 본다":"검사 신청은 주기 만료일 30일 전까지 하고 기관은 만료일 전후 각 30일 이내에 검사하며 그 기간에 합격하면 만료일에 받은 것으로 봅니다.","안전검사 신청서 및 검사 관련 서류는 안전검사기관이 3년 보존":"안전검사 서류는 안전검사기관이 3년 동안 갖고 있어야 합니다.","안전검사 업무를 위탁받은 자가 거짓·부정한 방법으로 수행한 경우: 3년 이하 징역 또는 3천만원 이하 벌금":"안전검사 업무를 위탁받고도 거짓으로 하면 3년 이하 징역 또는 3천만원 이하 벌금입니다.","안전관리자는 업무를 수행할 때 보건관리자와 협력한다, 사업주는 외부전문가의 평가·지도를 받을 수 있고, 배치할 때 연장·야간·휴일근로 등 작업 형태를 고려한다":"안전관리자는 업무 수행 때 보건관리자와 협력하고, 사업주는 외부전문가의 평가·지도를 받을 수 있으며 연장·야간·휴일근로 등을 고려해 배치합니다.","안전관리자 신규: 법령 / 산업안전보건개론 / 인간공학 및 산업심리 / 안전보건교육방법 / 재해 시 응급처치 / 안전점검·평가 및 재해 분석기법 / 안전기준 및 개인보호구 등 분야별 재해예방 실무 / 산업안전보건관리비 계상·사용기준 / 작업환경 개선 등 산업위생 / 무재해운동 추진기법 / 위험성평가 / 그 밖에":"안전관리자 신규교육은 법령, 개론, 인간공학, 교육방법, 응급처치, 재해 분석기법, 보호구 등 실무를 다룹니다.","안전관리자·안전관리전문기관 종사자: 신규 34시간 이상, 보수 24시간 이상":"안전관리자와 전문기관 종사자의 직무교육은 신규 34시간, 보수 24시간 이상입니다.","안전관리자 업무 위탁 가능 사업장은 건설업을 제외한 사업으로서 상시근로자 300명 미만, 위탁하면 그 안전관리전문기관을 안전관리자로 본다":"건설업을 제외한 상시근로자 300명 미만 사업장은 안전관리자 업무를 위탁할 수 있고 위탁하면 전문기관을 안전관리자로 봅니다.","안전관리전문기관 또는 보건관리전문기관에 업무를 위탁할 수 있다":"관리자를 직접 두지 않고 안전관리전문기관이나 보건관리전문기관에 일을 맡길 수 있습니다.","안전 및 보건에 관하여 사업주를 보좌하고 관리감독자에게 지도·조언하는 업무를 수행하는 사람, 안전관리자 또는 보건관리자가 있거나 두어야 하는 경우에는 두지 않는다":"안전보건관리담당자는 안전·보건에 관해 사업주를 보좌하고 관리감독자에게 조언하며, 안전·보건관리자가 있거나 두어야 하면 두지 않습니다.","안전보건관리담당자: 신규교육 없음(면제), 보수 8시간 이상":"안전보건관리담당자는 신규교육이 면제되고 보수교육만 8시간 이상 받습니다.","안전보건관리담당자 보수: 위험성평가 / 안전·보건교육방법 / 사업장 순회점검 및 지도 / 기계·기구의 적격품 선정 / 산업재해 통계의 유지·관리 및 조사 / 그 밖에":"안전보건관리담당자 보수교육은 위험성평가, 교육방법, 순회점검, 적격품 선정, 재해 통계 관리와 조사를 다룹니다.","안전·보건관리 업무 위탁에 관한 사항은 계획 포함 사항에 없다":"안전·보건관리 업무를 위탁하는 문제는 이사회에 올리는 계획의 포함 사항이 아닙니다.","안전보건관리책임자: 신규 6시간 이상, 보수 6시간 이상":"책임자의 직무교육은 처음 6시간 이상, 이후 보수 6시간 이상입니다.","안전보건관리책임자·관리감독자·안전관리자·보건관리자·안전보건관리담당자·산업보건의 선임 또는 업무 위반 / 산업안전보건위원회 구성·운영 / 안전보건관리규정 작성·절차 / 정기·채용 시 안전보건교육 / 건설업 기초안전보건교육 / 직무교육(책임자~담당자) / 안전보건표지 / 공정안전보고서 작성 시 위원회 심의 / 개선계획 심의·준수 / 안전보건총괄책임자 지정 / 시정조치 불응 / 안전보건조정자 / 건설 노사협의체 이행 / 자율안전확인표시 / 안전검사합격증명서 부착 / 석면 해체 관련 / 측정 설명회 / 건강진단 설명 / 건강관리카드 양도·대여 / 지도사 무등록 직무 / MSDS 제출·제공·승인 관련 / 대체자료 / 측정방법·근로자대표 참석·결과 통지 / 보고·출석 명령":"책임자·관리감독자·관리자 선임 또는 업무 위반, 위원회 구성·운영, 관리규정 작성·절차, 정기·채용 시 교육 등 위반도 과태료 대상입니다.","안전보건관리책임자는 안전관리자와 보건관리자를 지휘·감독한다":"책임자는 안전관리자와 보건관리자의 일을 지휘하고 감독하는 위치에 있습니다.","안전보건관리책임자 등에게 직무교육을 이수하지 않게 한 경우: 책임자·안전관리자·보건관리자 500만원, 안전보건관리담당자 1차 100만원·2차 200만원·3차 500만원, 전문기관 종사자 300만원":"직무교육을 시키지 않으면 책임자·관리자는 500만원, 담당자는 1차 100만원에서 시작하는 과태료입니다.","안전보건관리책임자 신규: 책임자의 책임과 직무 / 산업안전보건법령 및 안전·보건조치, 보수: 산업안전·보건정책 / 자율안전·보건관리":"안전보건관리책임자 신규교육은 책임과 직무, 법령과 조치를 다루고 보수교육은 안전·보건정책과 자율관리를 다룹니다.","안전보건관리책임자·안전관리자·보건관리자·안전보건관리담당자·산업보건의 선임에 관한 서류: 3년 보존":"책임자부터 산업보건의까지 선임에 관한 서류는 3년 동안 갖추어 둡니다.","안전보건관리책임자의 총괄 관리 업무와 안전보건총괄책임자의 직무에 위험성평가 실시가 포함된다, 도급 협의체 협의사항에도 포함":"위험성평가 실시는 안전보건관리책임자의 총괄 업무, 안전보건총괄책임자의 직무, 도급 협의체 협의사항에 포함됩니다.","안전보건교육 면제는 전년도 산업재해가 발생하지 않은 사업장은 다음 연도 근로자 정기교육 시간의 100분의 50 범위에서 면제 가능":"전년도에 산업재해가 없었던 사업장은 다음 연도 근로자 정기교육 시간의 100분의 50 범위에서 면제할 수 있습니다.","안전보건진단기관은 결과보고서를 사업주 및 고용노동부장관에게 제출":"진단 결과보고서는 진단기관이 사업주와 고용노동부장관 두 곳에 냅니다.","안전보건진단기관은 대통령령 요건을 갖추어 고용노동부장관의 지정을 받는다, 지정 취소·정지는 법 제21조제4항·제5항 준용":"진단기관 지정을 받으려면 요건을 갖춰야 하며 취소·정지는 제21조제4항·제5항에 따릅니다.","안전보건진단은 산업재해를 예방하기 위하여 잠재적 위험성을 발견하고 그 개선대책을 수립할 목적으로 조사·평가하는 것":"안전보건진단은 산업재해 예방을 위해 잠재적 위험성을 발견하고 개선대책을 세우려고 조사·평가하는 것입니다.","안전보건총괄책임자를 지정하면 건설기술 진흥법상 안전총괄책임자를 둔 것으로 본다":"지정만 하면 안전총괄책임자를 따로 두지 않아도 건설기술 진흥법상 둔 것으로 인정됩니다.","안전에 관한 기술적인 사항에 관하여 사업주 또는 안전보건관리책임자를 보좌하고 관리감독자에게 지도·조언하는 업무를 수행하는 사람":"안전관리자는 안전의 기술적 사항에 관해 사업주나 책임자를 보좌하고 관리감독자에게 지도·조언하는 사람입니다.","안전운전계획: 안전운전지침서 / 설비점검·검사 및 보수계획, 유지계획 및 지침서 / 안전작업허가 / 도급업체 안전관리계획 / 근로자 등 교육계획 / 가동 전 점검지침 / 변경요소 관리계획 / 자체감사 및 사고조사계획 / 그 밖에 안전운전에 필요한 사항":"안전운전계획에는 안전운전지침서, 설비점검·검사 계획, 안전작업허가, 도급업체 안전관리계획, 교육계획, 가동 전 점검지침 등이 들어갑니다.","안전인증기관은 안전인증 업무 및 확인 업무를 위탁받아 수행하는 기관으로 고용노동부장관이 지정, 취소·정지는 제21조제4항·제5항 준용":"안전인증 업무와 확인 업무는 장관이 지정한 안전인증기관이 위탁받아 합니다.","안전인증대상기계등을 제조하거나 수입하는 자(고용노동부령으로 정한 기계등을 설치·이전하거나 주요 구조 부분을 변경하는 자 포함)는 안전인증기준에 맞는지 고용노동부장관이 실시하는 안전인증을 받아야 한다":"안전인증대상기계등을 제조하거나 수입하는 자는 안전인증기준에 맞는지 고용노동부장관이 실시하는 안전인증을 받아야 합니다.","안전인증대상기계등이 아닌 유해·위험기계등으로서 대통령령으로 정하는 자율안전확인대상기계등을 제조·수입하는 자는 자율안전기준에 맞는지 확인(자율안전확인)하여 고용노동부장관에게 신고해야 한다":"자율안전확인대상기계등을 제조·수입하는 자는 자율안전기준에 맞는지 확인해 고용노동부장관에게 신고해야 합니다.","안전인증대상기계등이 아닌 유해·위험기계등을 제조·수입하는 자도 성능 평가를 받으려고 안전인증을 신청할 수 있다":"안전인증대상이 아닌 기계도 성능을 평가받고 싶으면 안전인증을 신청할 수 있습니다.","안전인증 받은 자는 제품명·모델명·제조수량·판매수량·판매처 현황 등을 기록하여 보존(3년)":"안전인증을 받은 자는 제품명, 모델명, 제조수량, 판매수량, 판매처 현황 등을 기록해 3년 동안 보존합니다.","안전인증 신청서·심사 관련 서류는 안전인증기관이 3년 보존":"심사 관련 서류는 인증기관이 3년간 간직합니다.","안전인증 신청은 안전인증기관에 제출, 외국 제조자는 국내 대리인을 선정해 신청하게 할 수 있다":"외국 제조자는 국내 대리인을 정해 대신 신청하게 할 수 있고 신청서는 안전인증기관에 냅니다.","안전인증·안전검사 업무를 위탁받은 기관: 3년 / 안전인증을 받은 자의 기록 서류: 3년 / 자율안전확인대상기계등 제조·수입자의 증명서류: 2년 / 자율검사프로그램 검사 결과 서류: 2년":"안전인증·안전검사 위탁기관과 안전인증 받은 자의 기록은 3년, 자율안전확인 증명서류와 자율검사프로그램 검사 결과는 2년 보존합니다.","안전인증을 받은 자가 안전인증기준을 지키고 있는지 고용노동부장관은 3년 이하의 범위에서 주기마다 확인":"장관은 안전인증을 받은 자가 인증기준을 지키는지 3년 이하의 범위에서 주기마다 확인합니다.","안전인증을 받은 자는 인증받은 기계등이나 용기·포장에 안전인증 표시, 인증받지 않은 것에 인증표시 또는 유사 표시·광고 금지":"인증받은 자는 기계등이나 용기·포장에 안전인증 표시를 하고 인증받지 않은 것에 인증표시나 유사 표시·광고를 해서는 안 됩니다.","안전인증이 취소된 자는 취소된 날부터 1년 이내에는 취소된 기계등에 대해 안전인증을 신청할 수 없다":"취소 후 1년 안에는 같은 기계등으로 안전인증을 다시 신청할 수 없습니다.","안전장치 및 보호구 구입 시 적격품 여부 확인(제15조제1항제8호)은 위원회 심의·의결 사항에 들어 있지 않다":"안전장치와 보호구 구입 시 적격품 확인은 위원회 심의·의결 사항에 들어 있지 않습니다.","안전조치 대상 1: 기계·기구, 그 밖의 설비에 의한 위험 / 2: 폭발성·발화성·인화성 물질 등에 의한 위험 / 3: 전기, 열, 그 밖의 에너지에 의한 위험":"안전조치 대상 위험은 기계·기구·설비, 폭발성·발화성·인화성 물질, 전기·열 등 에너지에 의한 위험입니다.","안전조치(제38조)·보건조치(제39조)·도급인 조치(제63조) 위반으로 근로자를 사망에 이르게 한 자: 7년 이하 징역 또는 1억원 이하 벌금, 5년 내 재범은 형의 2분의 1까지 가중":"안전·보건·도급인 조치를 어겨 근로자가 숨지면 7년 이하 징역이나 1억원 이하 벌금입니다.","안전조치·보건조치 위반(사망 아님)은 5년 이하 징역 또는 5천만원 이하 벌금":"안전조치·보건조치를 위반했지만 사망에 이르지 않으면 5년 이하 징역 또는 5천만원 이하 벌금입니다.","안전진단은 종합진단 중 제2호(재해 원인)·제3호(작업조건·방법)·제4호 가~마목(기계·기구 위험, 폭발성 물질, 전기·열, 추락·붕괴·낙하·비래, 기타 설비 위험)·제5호 중 안전 관련 사항":"안전진단은 종합진단 중 재해 원인, 작업조건·방법, 기계·기구·폭발성 물질·전기·열·추락 등의 위험, 안전 관련 사항을 다룹니다.","압력용기, 사출성형기, 산업용 로봇, 예초기는 별표 21 대상이 아니다":"별표 21 대여 대상에서 압력용기, 사출성형기, 산업용 로봇, 예초기는 빠집니다.","약사는 보건관리자 자격 목록에 없다":"약사는 보건관리자 자격 목록에 들어 있지 않습니다.","양벌규정: 법인의 대표자·대리인·사용인·종업원이 제167조제1항(법인 10억원 이하) 또는 제168조~제172조 위반을 하면 행위자 외에 법인·개인에게도 벌금형, 상당한 주의와 감독을 게을리하지 않았으면 면책":"법인의 대표자·대리인·사용인·종업원이 위반하면 행위자 외에 법인이나 개인에게도 벌금형을 과하고 상당한 주의와 감독을 했으면 면책됩니다.","업무 1 관리감독자가 지휘·감독하는 작업(해당작업)과 관련된 기계·기구 또는 설비의 안전·보건 점검 및 이상 유무의 확인 / 업무 2 소속 근로자의 작업복·보호구 및 방호장치의 점검과 그 착용·사용에 관한 교육·지도 / 업무 3 해당작업에서 발생한 산업재해에 관한 보고 및 이에 대한 응급조치 / 업무 4 해당작업의 작업장 정리·정돈 및 통로 확보에 대한 확인·감독 / 업무 5 안전관리자(또는 안전관리전문기관 담당자)·보건관리자(또는 보건관리전문기관 담당자)·안전보건관리담당자·산업보건의의 지도·조언에 대한 협조 / 업무 6 위험성평가에 관한 업무: 유해·위험요인의 파악에 대한 참여, 개선조치의 시행에 대한 참여 / 업무 7 그 밖에 해당작업의 안전 및 보건에 관한 사항으로서 고용노동부령으로 정하는 사항":"관리감독자 업무에는 해당작업의 기계·설비 점검, 작업복·보호구 점검 및 교육, 재해 보고와 응급조치 등이 있습니다.","업무 1 산업안전보건위원회 또는 노사협의체에서 심의·의결한 업무, 안전보건관리규정 및 취업규칙에서 정한 업무 / 업무 2 안전인증대상기계등과 자율안전확인대상기계등 중 보건과 관련된 보호구 구입 시 적격품 선정에 관한 보좌 및 지도·조언 / 업무 3 위험성평가에 관한 보좌 및 지도·조언 / 업무 4 물질안전보건자료의 게시 또는 비치에 관한 보좌 및 지도·조언 / 업무 5 산업보건의의 직무(보건관리자가 의사인 경우만) / 업무 6 해당 사업장 보건교육계획의 수립 및 보건교육 실시에 관한 보좌 및 지도·조언 / 업무 7 의료행위(보건관리자가 의사 또는 간호사인 경우만): 자주 발생하는 가벼운 부상 치료 / 응급처치가 필요한 사람 처치 / 부상·질병 악화 방지 처치 / 건강진단 결과 발견된 질병자의 요양 지도 및 관리 / 이에 따르는 의약품 투여 / 업무 8 전체 환기장치 및 국소 배기장치 등 설비의 점검과 작업방법의 공학적 개선에 관한 보좌 및 지도·조언 / 업무 9 사업장 순회점검, 지도 및 조치 건의 / 업무 10 산업재해 원인 조사·분석 및 재발 방지 기술적 보좌 / 업무 11 산업재해 통계의 유지·관리·분석 보좌 / 업무 12 법령으로 정한 보건 사항 이행에 관한 보좌 / 업무 13 업무 수행 내용의 기록·유지 / 업무 14 그 밖에 고용노동부장관이 정하는 보건 관련 작업관리·작업환경관리 사항":"보건관리자 업무에는 위원회 심의·의결 업무, 보건 관련 보호구 적격품 선정 보좌, 위험성평가 보좌, 물질안전보건자료 등이 있습니다.","업무 1 산업안전보건위원회 또는 노사협의체에서 심의·의결한 업무, 안전보건관리규정 및 취업규칙에서 정한 업무 / 업무 2 위험성평가에 관한 보좌 및 지도·조언 / 업무 3 안전인증대상기계등과 자율안전확인대상기계등 구입 시 적격품의 선정에 관한 보좌 및 지도·조언 / 업무 4 해당 사업장 안전교육계획의 수립 및 안전교육 실시에 관한 보좌 및 지도·조언 / 업무 5 사업장 순회점검, 지도 및 조치 건의 / 업무 6 산업재해 발생의 원인 조사·분석 및 재발 방지를 위한 기술적 보좌 및 지도·조언 / 업무 7 산업재해에 관한 통계의 유지·관리·분석을 위한 보좌 및 지도·조언 / 업무 8 법 또는 법에 따른 명령으로 정한 안전에 관한 사항의 이행에 관한 보좌 및 지도·조언 / 업무 9 업무 수행 내용의 기록·유지 / 업무 10 그 밖에 안전에 관한 사항으로서 고용노동부장관이 정하는 사항":"안전관리자 업무에는 위원회에서 심의·의결한 업무, 위험성평가 보좌, 안전인증 기계 적격품 선정 보좌 등이 있습니다.","업무교육과 직업윤리교육, 합산 총 20시간 이상, 갱신기간 동안 지도실적이 2년 이상인 지도사는 10시간 이상, 공단이 끝난 날부터 10일 이내 보고, 이수자 명단 등을 5년 보존":"보수교육은 업무교육과 직업윤리교육을 합쳐 20시간 이상이고 지도실적이 2년 이상인 지도사는 10시간 이상이며 명단 등은 5년 보존합니다.","업무는 안전보건교육 실시 보좌 / 위험성평가 보좌 / 작업환경측정 및 개선 보좌 / 각종 건강진단 보좌 / 산업재해 원인 조사·통계의 기록 및 유지 보좌 / 안전장치·보호구 구입 시 적격품 선정 보좌":"안전보건관리담당자 업무는 교육 실시, 위험성평가, 작업환경측정, 건강진단, 재해 원인 조사·통계, 적격품 선정을 보좌하는 것입니다.","업무는 자체점검 참여 및 근로감독관의 사업장 감독 참여 / 산업재해 예방계획 수립 참여, 기계·기구 자체검사 참석 / 법령 위반 시 개선 요청·신고 / 급박한 위험 시 작업중지 요청 / 작업환경측정·건강진단 참석 및 설명회 참여 / 유사 질병자 다수 발생 시 임시건강진단 실시 요청 / 안전수칙 준수 지도 / 법령 및 정책 개선 건의 / 안전·보건 의식 활동 참여·지원 / 그 밖의 홍보 등":"명예산업안전감독관 업무에는 자체점검 참여, 법령 위반 시 개선 요청·신고, 급박한 위험 시 작업중지 요청, 임시건강진단 요청 등이 있습니다.","업무를 폐지하거나 등록이 취소되면 지체 없이 등록증을 지방고용노동청장에게 반납":"폐업하거나 등록이 취소되면 바로 등록증을 지방고용노동청장에게 돌려줘야 합니다.","업무 영역: 산업안전지도사는 기계안전·전기안전·화공안전·건설안전 분야, 산업보건지도사는 직업환경의학·산업위생 분야":"산업안전지도사는 기계안전, 전기안전, 화공안전, 건설안전 분야를 맡고 산업보건지도사는 직업환경의학, 산업위생 분야를 맡습니다.","업무정지가 이용자에게 심한 불편을 주거나 공익을 해칠 우려가 있으면 업무정지를 대신해 10억원 이하의 과징금을 부과할 수 있다":"업무정지가 이용자에게 큰 불편을 주면 정지 대신 10억원 이하 금액을 과징금으로 걷을 수 있습니다.","업무정지 처분을 대신하는 과징금: 10억원 이하 (업무정지가 이용자에게 심한 불편을 주거나 공익을 해칠 우려가 있는 경우)":"업무정지가 이용자에게 심한 불편을 주거나 공익을 해칠 우려가 있으면 업무정지를 대신해 10억원 이하의 과징금을 부과합니다.","업종별 보건관리전문기관에 위탁할 수 있는 사업은 광업":"업종별 전문기관에 보건관리 업무를 맡길 수 있는 사업은 광업입니다.","에어로졸: 재충전이 불가능한 금속·유리 또는 플라스틱 용기에 압축가스·액화가스 또는 용해가스를 충전하고 내용물을 가스에 현탁시킨 고체나 액상입자로, 액상 또는 가스상에서 폼·페이스트·분말상으로 배출되는 분사장치를 갖춘 것":"에어로졸은 재충전이 불가능한 용기에 압축·액화·용해 가스를 채우고 내용물을 폼·페이스트·분말상 등으로 내보내는 분사장치를 갖춘 것입니다.","역학조사 참석이 허용된 사람의 참석을 방해한 자: 과태료 1천500만원 이하(형벌 아님)":"역학조사에서 참석이 허용된 사람의 참석을 방해한 자는 형벌이 아니라 과태료 1천500만원 이하입니다.","연면적 5천제곱미터 이상 냉동·냉장 창고시설의 설비공사 및 단열공사 (3천제곱미터가 아님)":"냉동·냉장 창고시설 설비·단열공사는 5천제곱미터 이상일 때만 대상입니다.","연수교육의 기간은 업무교육 및 실무수습 기간을 합산해 3개월 이상, 공단은 끝난 날부터 10일 이내 고용노동부장관에게 결과 보고, 이수자 명단 등을 3년 보존":"연수교육은 업무교육과 실무수습을 합쳐 3개월 이상이며 공단은 끝난 날부터 10일 이내에 장관에게 결과를 보고하고 명단 등을 3년 보존합니다.","연장 신청 시 유효기간이 만료되는 날의 다음 날부터 3년의 범위에서 연장승인 가능, 연장 시에도 안전 및 보건에 관한 평가를 받아야 한다":"연장을 신청하면 유효기간이 끝난 다음 날부터 3년 범위에서 연장승인을 받을 수 있고 이때도 안전 및 보건 평가를 받아야 합니다.","영 별표 1 제1호에 따른 사업, 상시근로자 50명 미만의 도매업·숙박 및 음식점업은 위 각 교육시간의 2분의 1 이상으로 한다 (예: 30명 도매업의 채용 시 교육 4시간)":"상시근로자 50명 미만 도매업·숙박 및 음식점업 등은 각 교육시간의 2분의 1 이상으로 하며 30명 도매업의 채용 시 교육은 4시간입니다.","영 별표 35 주요 금액(만원): 책임자·안전관리자·보건관리자 미선임 500 / 산업보건의 미선임 300(1차) / 안전보건관리규정 미작성 150(1차) / 중대재해 미보고 3,000 / 산재 미보고 700·1,000·1,500 / 안전검사 미수검 200(1대당 1차) / 휴게시설 미설치 1,500 / 안전보건진단 명령 위반 1,000, 위험성평가 미실시 과태료(500·700·1,000)는 2027.1.1 이후 시행분":"영 별표 35에서 책임자·안전관리자·보건관리자 미선임은 500만원, 중대재해 미보고는 3,000만원 등 위반별 금액을 정해 두고 있습니다.","영업비밀 관련 대체자료: 고용노동부장관의 승인을 받아 화학물질의 명칭·함유량을 대체자료로 적을 수 있다, 중대한 건강장해 우려 물질로 고시된 것은 제외, 승인 유효기간 5년, 5년 단위 연장":"영업비밀이면 장관의 승인을 받아 화학물질의 명칭·함유량을 대체자료로 적을 수 있고 승인 유효기간은 5년이며 5년 단위로 연장합니다.","영업비밀 비공개 승인 신청 시 보호사유를 거짓으로 작성한 자: 과태료 500만원 이하":"영업비밀 승인을 신청하며 보호사유를 거짓으로 쓰면 500만원 이하 과태료입니다.","영 제40조제5항 사유는 교육 관련 서류의 거짓 작성 / 정당한 사유 없이 교육 실시 거부 / 교육 없이 수수료 수령 / 교육 내용·방법 위반":"취소 사유로는 서류를 거짓으로 쓰거나 교육을 거부하거나 교육 없이 수수료를 받는 경우가 있습니다.","영 제86조 나머지: 일반소비자의 생활용으로 제공되는 화학물질 또는 혼합물 / 고시하는 연구·개발용 화학물질(자료 제출만 제외) / 독성·폭발성 등 위해 정도가 적다고 인정해 고시하는 화학물질":"영 제86조의 나머지 제외 대상은 일반소비자 생활용 물질, 고시하는 연구·개발용 물질, 위해 정도가 적다고 고시한 물질입니다.","예비심사: 기계 및 방호장치·보호구가 유해·위험기계등인지 확인(안전인증대상 아닌 기계가 신청한 경우), 기간 7일":"예비심사는 안전인증대상이 아닌 기계가 신청했을 때 유해·위험기계등인지 확인하며 기간은 7일입니다.","예외(시험·연구·검사 목적): 고용노동부령 요건을 갖추어 고용노동부장관의 승인을 받은 경우 / 화학물질관리법상 금지물질 판매 허가를 받은 자가 승인받은 자 등에게 양도·제공 / 금지물질 수입 허가를 받은 자가 수입":"시험·연구·검사 목적으로 고용노동부령 요건을 갖춰 장관 승인을 받은 경우 등은 제조등금지물질의 예외입니다.","예외 1: 일시·간헐적으로 하는 작업을 도급하는 경우":"일시적이거나 간헐적으로 하는 작업을 도급하는 경우는 도급금지의 예외입니다.","예외 2: 수급인이 보유한 기술이 전문적이고 사업 운영에 필수 불가결한 경우로서 고용노동부장관의 승인을 받은 경우":"수급인의 기술이 전문적이고 사업 운영에 필수 불가결해 장관의 승인을 받은 경우도 도급금지의 예외입니다.","예초기: 날접촉 예방장치 / 원심기: 회전체 접촉 예방장치 / 공기압축기: 압력방출장치 / 금속절단기: 날접촉 예방장치 / 지게차: 헤드 가드, 백레스트, 전조등, 후미등, 안전벨트 / 포장기계(진공포장기, 래핑기로 한정): 구동부 방호 연동장치":"예초기는 날접촉 예방장치, 원심기는 회전체 접촉 예방장치, 공기압축기는 압력방출장치, 지게차는 헤드 가드 등이 방호장치입니다.","요건은 안전관리자 자격 또는 보건관리자 자격을 갖추었거나 고용노동부장관이 고시하는 안전보건교육을 이수한 해당 사업장 소속 근로자, 업무에 지장이 없으면 다른 업무 겸직 가능":"요건은 안전·보건관리자 자격이 있거나 고시된 안전보건교육을 이수한 소속 근로자이며 업무에 지장이 없으면 다른 업무를 겸직할 수 있습니다.","용접용 보안면, 추락 및 감전 위험방지용 안전모, 차광 및 비산물 위험방지용 보안경은 안전인증대상":"용접용 보안면과 추락·감전용 안전모, 차광·비산물용 보안경은 자율안전확인이 아니라 안전인증 대상입니다.","원심기·롤러기·사출성형기·고소작업대·컨베이어·산업용 로봇·혼합기·파쇄기: 관계 법령 / 개론 / 구조(종류) 및 특성 / 검사기준 / 방호장치 / 검사장비 / 검사실습 및 체크리스트":"원심기, 롤러기, 사출성형기, 고소작업대, 컨베이어, 산업용 로봇 등의 검사원 교육은 구조, 검사기준, 방호장치, 실습으로 구성됩니다.","원심기에 압력방출장치를 설치하는 것이 아니라 회전체 접촉 예방장치":"원심기에는 압력방출장치가 아니라 회전체 접촉 예방장치를 설치합니다.","원인조사 시 현장을 방문하여 조사하고, 사업주의 법 위반이 원인인지 등을 조사":"원인조사는 현장을 직접 방문해 사업주의 법 위반이 원인인지 등을 조사하는 방식입니다.","위 업종 외 제조업: 50명 이상 1천명 미만 1명 이상, 1천명 이상 3천명 미만 2명 이상, 3천명 이상 2명 이상(의사·간호사 1명 이상 포함)":"위 업종 외 제조업은 50명 이상 1천명 미만 1명 이상, 1천명 이상은 2명 이상이며 3천명 이상은 의사나 간호사를 포함합니다.","위에 해당하지 않는 나머지 사업: 상시근로자 100명 이상":"앞의 업종과 건설업이 아닌 나머지 사업은 상시근로자가 100명 이상일 때 선임합니다.","위원장은 위원 중에서 호선, 근로자위원과 사용자위원 중 각 1명을 공동위원장으로 선출할 수 있다":"위원장은 위원들이 서로 뽑으며 양측에서 한 명씩 뽑아 공동위원장을 둘 수도 있습니다.","위원장은 회의 결과와 중재 결정 내용을 사내방송, 사내보, 게시, 정례조회 등으로 근로자에게 신속히 알린다":"회의 결과와 중재 결정은 위원장이 사내방송, 사내보, 게시, 정례조회로 근로자에게 곧바로 알립니다.","위원회는 법령·단체협약·취업규칙·안전보건관리규정에 반하는 내용으로 심의·의결해서는 안 된다":"법령이나 단체협약, 취업규칙, 관리규정에 어긋나는 내용은 위원회가 의결할 수 없습니다.","위원회를 구성하지 않으면 과태료 500만원 이하":"산업안전보건위원회를 구성하지 않으면 과태료 500만원 이하가 부과됩니다.","위촉 대상은 근로자대표가 추천하는 소속 사업장 근로자 / 노동조합 연합단체·지역 대표기구 임직원 / 전국 규모 사업주단체 임직원 / 산업재해 예방 관련 업무 단체 임직원":"명예산업안전감독관 위촉 대상은 근로자대표가 추천하는 근로자와 노동조합 연합단체, 사업주단체, 예방 관련 단체의 임직원입니다.","위험성평가는 정의 조항(제2조)이 아니라 제36조에서 정의: 유해·위험 요인을 찾아내 위험성의 크기가 허용 가능한 수준인지 결정하고 개선대책을 수립·이행하는 것":"위험성평가는 정의 조항이 아니라 제36조에서 정의하며 위험성이 허용 가능한지 결정하고 개선대책을 이행하는 것입니다.","유기과산화물: 2가의 -O-O- 구조를 가지고 1개 또는 2개의 수소 원자가 유기라디칼에 의하여 치환된 과산화수소의 유도체를 포함한 액체 또는 고체 유기물질":"유기과산화물은 2가의 -O-O- 구조를 가지고 수소 원자가 유기라디칼로 치환된 과산화수소 유도체 형태의 유기물질입니다.","유사명칭 사용 금지: 등록한 지도사가 아닌 사람은 산업안전지도사·산업보건지도사 또는 유사 명칭을 사용할 수 없다":"등록하지 않은 사람이 지도사 명칭이나 유사 명칭을 쓰는 것은 금지됩니다.","유해·위험의 정도, 사업의 종류, 상시근로자 수(건설공사는 공사금액) 등을 고려해 대통령령으로 정하는 사업 또는 사업장에는 법의 전부 또는 일부를 적용하지 않을 수 있음":"유해·위험 정도, 사업 종류, 상시근로자 수 등을 고려해 대통령령으로 정하는 사업에는 법 전부나 일부를 적용하지 않을 수 있습니다.","유해인자별 보건관리전문기관에 위탁할 수 있는 사업은 납 취급, 수은 취급, 크롬 취급, 석면 취급, 허가대상물질 취급, 근골격계 질환 원인 작업(단순반복·영상표시단말기·중량물 취급 등)을 하는 사업":"유해인자별 보건관리전문기관에는 납, 수은, 크롬, 석면, 허가대상물질 취급이나 근골격계 질환 원인 작업을 하는 사업을 위탁할 수 있습니다.","유해인자의 유해성·위험성을 평가해 결과를 관보 등에 공표할 수 있고, 수준별로 구분해 관리해야 한다, 평가 결과 등을 고려해 노출기준을 정해 고시":"평가 결과는 공표하고 수준별로 관리하며 노출기준을 정해 고시하는 근거가 됩니다.","유해하거나 위험한 기계·기구·설비를 도입한 경우 안전 및 보건 관련 조치에 관한 사항":"유해하거나 위험한 기계·설비를 도입했을 때의 안전·보건 조치도 심의·의결 사항입니다.","유해하거나 위험한 작업에 채용하거나 그 작업으로 작업내용을 변경할 때 위 교육 외에 추가로 실시":"유해하거나 위험한 작업에 채용하거나 작업내용을 변경할 때는 위 교육에 더해 특별교육을 추가로 해야 합니다.","유해하거나 위험한 작업·장소에서 사용하거나 건강장해 방지에 사용하는 기계·기구 및 설비의 설치·이전·주요 구조부분 변경: 금속이나 그 밖의 광물의 용해로 / 화학설비 / 건조설비 / 가스집합 용접장치 / 근로자 건강에 상당한 장해를 일으킬 우려가 있는 물질의 밀폐·환기·배기를 위한 설비":"용해로, 화학설비, 건조설비, 가스집합 용접장치 등 위험 설비를 설치·이전·변경하는 경우입니다.","의결하지 못했거나 의결 사항의 해석·이행방법에 의견이 일치하지 않으면 중재기구를 두어 해결하거나 제3자의 중재를 받는다, 중재 결정은 위원회 의결로 본다":"의결하지 못했거나 해석·이행방법이 갈리면 중재기구나 제3자의 중재로 해결하고 중재 결정은 위원회 의결로 봅니다.","의사·치과의사·한의사는 3일 이상의 입원치료가 필요한 부상 또는 질병이 환자의 업무와 관련성이 있다고 판단하면 치료과정에서 알게 된 정보를 고용노동부장관에게 신고할 수 있다":"3일 이상 입원할 부상·질병이 업무와 관련 있다고 보면 의사 등이 장관에게 신고할 수 있습니다.","의원·한의원은 지정 대상이 아니다, 병원이 종합병원이 아니라도 병원이면 지정받을 수 있다, 산업보건지도사는 대상 목록에 없다 (2024 기출 정답표는 법인을 오답으로 표시했으나 영 제95조는 법인을 포함)":"의원·한의원과 산업보건지도사는 지정 대상이 아니고 병원은 종합병원이 아니라도 지정받을 수 있으며 법인은 영 제95조에 포함됩니다.","이 법과 명령으로 정하는 산업재해 예방 기준을 이행 / 근로자의 신체적 피로와 정신적 스트레스 등을 줄일 수 있는 쾌적한 작업환경의 조성 및 근로조건 개선 / 해당 사업장의 안전 및 보건에 관한 정보를 근로자에게 제공":"사업주는 예방 기준 이행, 쾌적한 작업환경과 근로조건 개선, 안전·보건 정보의 근로자 제공을 해야 합니다.","이사회 보고·승인을 하지 않으면 과태료 1천만원 이하":"이사회에 보고하고 승인받는 의무를 어기면 과태료 1천만원 이하가 부과됩니다.","이상기압: 게이지 압력이 제곱센티미터당 1킬로그램 초과 또는 미만인 기압":"게이지 압력이 제곱센티미터당 1킬로그램보다 높거나 낮은 기압이 이상기압입니다.","이상기온: 고열·한랭·다습으로 인하여 열사병·동상·피부질환 등을 일으킬 수 있는 기온":"이상기온은 고열, 한랭, 다습으로 열사병이나 동상, 피부질환 등을 일으킬 수 있는 기온입니다.","이행사항 1 도급인과 수급인을 구성원으로 하는 안전 및 보건에 관한 협의체의 구성 및 운영 / 2 작업장 순회점검 / 3 관계수급인이 근로자에게 하는 안전보건교육(제29조제1항~제3항)을 위한 장소 및 자료의 제공 등 지원 / 4 관계수급인이 근로자에게 하는 특별교육(제29조제3항)의 실시 확인 / 5 작업 장소에서 발파작업을 하는 경우, 또는 화재·폭발, 토사·구축물 등의 붕괴 또는 지진 등이 발생한 경우에 대비한 경보체계 운영과 대피방법 등 훈련 / 6 위생시설(휴게시설, 세면·목욕시설, 세탁시설, 탈의시설, 수면시설) 등 설치 등을 위해 필요한 장소의 제공 또는 도급인이 설치한 위생시설 이용의 협조 / 7 같은 장소에서 이루어지는 도급인과 관계수급인 등의 작업에 있어서 작업시기·내용, 안전조치 및 보건조치 등의 확인 / 8 7호 확인 결과 작업 혼재로 화재·폭발 등 위험이 우려되면 작업시기·내용 등의 조정":"도급인의 이행사항에는 협의체 구성·운영, 작업장 순회점검, 관계수급인 안전보건교육을 위한 장소·자료 지원 등이 있습니다.","이행사항 위반 벌칙: 제1호~제5호·제7호·제8호 또는 제2항 위반 500만원 이하 벌금, 제6호 위반 과태료 1천500만원 이하":"제6호 위반은 과태료 1천500만원 이하이고 나머지 호는 500만원 이하 벌금입니다.","이행상태평가: 확인 후 1년이 지난 날부터 2년 이내에 첫 평가, 이후 4년마다, 사업주 요청이나 변경요소 관리계획 미준수 등 고시 사유가 있으면 1년 또는 2년마다 평가 가능, 세부 방법은 고용노동부장관이 정한다":"이행상태평가는 확인 1년 후 2년 이내 첫 평가, 이후 4년마다 하고 사유가 있으면 1·2년마다 합니다.","인력 기준: 타워크레인 설치·해체기능사 자격 취득자 / 판금제관기능사 또는 비계기능사 자격 취득자(2025년 12월 31일까지 취득자) / 지정 교육기관 교육 이수·수료시험 합격 후 5년이 지나지 않은 사람 / 보수교육 이수 후 5년이 지나지 않은 사람 — 이들 4명 이상 보유":"인력 기준은 타워크레인 설치·해체기능사, 판금제관기능사·비계기능사 취득자, 교육 이수 후 5년이 지나지 않은 사람 등입니다.","인정 요건: 검사원 고용 / 장비 보유·관리 / 안전검사 주기의 2분의 1 주기마다 검사(건설현장 외 크레인은 6개월) / 검사기준이 안전검사기준 충족, 자율안전검사기관에 위탁하면 앞 두 가지는 충족한 것으로 본다":"인정 요건은 검사원 고용, 장비 보유·관리, 안전검사 주기의 2분의 1 주기 검사, 안전검사기준 충족입니다.","인정 취소: 거짓·부정한 방법으로 인정받은 경우(필수) / 인정받고도 검사를 하지 않은 경우 / 인정받은 내용대로 검사하지 않은 경우 / 검사원 또는 자율안전검사기관이 검사를 하지 않은 경우, 취소된 기계등은 사용 금지":"거짓·부정 인정은 필수 취소이고 인정받고 검사를 하지 않았거나 내용대로 하지 않았을 때도 취소되며 취소된 기계등은 사용할 수 없습니다.","인증받은 기계등을 제조·수입·양도·대여하는 자는 표시를 임의로 변경하거나 제거할 수 없다(1년 이하 징역 또는 1천만원 이하 벌금)":"인증받은 기계등의 표시를 임의로 변경하거나 제거하면 1년 이하 징역 또는 1천만원 이하 벌금입니다.","인체에 상해를 입힐 우려가 있는 재질이나 표면이 거친 재질은 표시에 사용할 수 없다":"표시 재질은 사람에게 상처를 줄 수 있거나 표면이 거칠면 안 됩니다.","인화성 가스: 20℃, 표준압력(101.3kPa)에서 공기와 혼합하여 인화되는 범위에 있는 가스와 54℃ 이하 공기 중에서 자연발화하는 가스":"인화성 가스는 20℃, 101.3kPa에서 공기와 섞여 인화되는 가스와 54℃ 이하에서 자연발화하는 가스입니다.","인화성 고체: 쉽게 연소되거나 마찰에 의하여 화재를 일으키거나 촉진할 수 있는 물질":"쉽게 타거나 마찰로 불이 붙는 고체가 인화성 고체입니다.","인화성 액체: 표준압력(101.3kPa)에서 인화점이 93℃ 이하인 액체":"표준압력 101.3kPa에서 인화점이 93℃ 이하이면 인화성 액체입니다.","일반석면조사 결과: 해체·제거작업 종료까지 / 기관석면조사 결과: 3년 / 작업환경측정기관 서류: 3년 / 지도사 업무 서류: 5년 / 석면해체·제거 서류: 30년":"일반석면조사 결과는 작업 종료까지, 기관조사와 측정기관 서류는 3년, 지도사 서류는 5년, 석면 서류는 30년입니다.","일부 면제: 외국 안전인증기관 인증 / IECEx 인증 / 국가표준기본법 시험·검사기관 시험 / 산업표준화법 제15조 인증 / 전기용품 및 생활용품 안전관리법 안전인증 — 해당 인증·시험 또는 일부 항목에 한정":"외국 안전인증기관 인증, IECEx 인증, 국가표준기본법 시험·검사 등은 해당 인증이나 일부 항목에 한정해 일부 면제됩니다.","일용근로자가 채용 시·특별교육을 받은 날 이후 1주일 동안 같은 사업장에서 같은 업무의 일용근로자로 다시 종사하면 이미 받은 교육 면제":"일용근로자가 1주일 안에 같은 사업장 같은 업무로 돌아오면 앞서 받은 교육은 다시 받지 않습니다.","임시건강진단: 고용노동부장관이 같은 유해인자에 노출되는 근로자들에게 유사한 질병의 증상이 발생한 경우 등에 사업주에게 특정 근로자에 대한 건강진단의 실시나 작업전환 등 조치를 명할 수 있다":"임시건강진단은 같은 유해인자 노출 근로자에게 유사 증상이 생기면 장관이 명하는 건강진단입니다.","임시건강진단 명령 사유: 같은 부서 근로자 또는 같은 유해인자 노출 근로자에게 유사한 질병의 자각·타각 증상 발생 / 직업병 유소견자가 발생하거나 여러 명 발생 우려 / 그 밖에 지방고용노동관서의 장이 필요하다고 판단":"같은 부서나 같은 유해인자 노출자의 유사 증상, 유소견자 발생 등이 명령 사유입니다.","임시작업: 일시적으로 하는 작업 중 월 24시간 미만인 작업(월 10시간 이상 24시간 미만이 매월 행하여지는 작업 제외), 단시간작업: 관리대상 유해물질을 취급하는 시간이 1일 1시간 미만인 작업(1일 1시간 미만이 매일 수행되는 경우 제외)":"임시작업은 월 24시간 미만인 일시 작업이고 단시간작업은 관리대상 유해물질 취급이 1일 1시간 미만인 작업입니다.","자격 1 산업보건지도사 자격을 가진 사람 / 자격 2 의료법에 따른 의사 / 자격 3 간호법에 따른 간호사 / 자격 4 산업위생관리산업기사 또는 대기환경산업기사 이상의 국가기술자격 취득자 / 자격 5 인간공학기사 이상의 국가기술자격 취득자 / 자격 6 전문대학 이상에서 산업보건 또는 산업위생 분야 학위 취득자(동등 이상 학력 포함)":"보건관리자 자격은 산업보건지도사, 의사, 간호사, 산업위생관리산업기사 이상, 인간공학기사 이상, 산업보건 관련 학위 취득자 등입니다.","자격 1 산업안전지도사 자격을 가진 사람 / 자격 2 산업안전산업기사 이상의 국가기술자격 취득자 / 자격 3 건설안전산업기사 이상의 국가기술자격 취득자 / 자격 4 4년제 대학 이상에서 산업안전 관련 학위 취득자 또는 동등 이상 학력 / 자격 5 전문대학 또는 동등 이상 학교에서 산업안전 관련 학위 취득자 / 자격 6 이공계 전문대학 이상 학위 취득 후 해당 사업의 관리감독자 업무(건설업은 시공실무경력) 3년(4년제 이공계 대학 학위 취득자는 1년) 이상 담당, 1998년 12월 31일까지의 지정 교육 이수 및 시험 합격자, 건설업 제외, 같은 업종(대분류 기준)의 상시근로자 300명 미만 사업장에서만 가능 / 자격 7 공업계 고등학교 이상 졸업 후 관리감독자 업무 5년 이상, 지정 교육(1998년 12월 31일까지) 이수 및 시험 합격자, 별표 3 제27호·제36호 사업장(상시근로자 50명 이상 1천명 미만)에서만 가능 / 자격 7의2 공업계 고등학교 졸업 또는 공학·자연과학 학위 취득 후 건설업 외 실무경력 5년 이상으로 지정 교육(2028년 12월 31일까지) 이수·시험 합격자, 건설업 외 상시근로자 300명 미만 사업장에서만 가능 / 자격 8 고압가스·LPG·도시가스 안전관리책임자, 교통안전관리자, 화약류제조보안책임자·관리보안책임자, 전기안전관리자(해당 법령 적용 사업에서만) / 자격 9 전담 안전관리자를 두어야 하는 사업장(건설업 제외)에서 안전 관련 업무를 10년 이상 담당한 사람 / 자격 10~12는 건설업: 종합공사 건설현장에서 안전보건관리책임자로 10년 이상 재직 / 중급 이상 토목·건축 건설기술인 + 산업안전교육 이수·시험 합격 / 토목·건축 기사(3년)·산업기사(5년) + 실무경력 + 산업안전교육":"안전관리자 자격은 산업안전지도사, 산업안전산업기사 이상, 건설안전산업기사 이상, 산업안전 관련 학위 취득자 등으로 정해집니다.","자격: 산업안전지도사 / 발주청이 선임한 공사감독자 / 주된 공사의 책임감리자 / 종합공사 건설현장 안전보건관리책임자로 3년 이상 재직한 사람 / 건설안전기술사 / 건설안전기사·산업안전기사 + 건설안전 5년 / 건설안전산업기사·산업안전산업기사 + 건설안전 7년":"안전보건조정자 자격은 산업안전지도사, 공사감독자, 책임감리자, 건설안전기술사, 산업안전기사와 건설안전 경력자 등입니다.","자격대여·대여알선 금지: 자기의 성명이나 사무소의 명칭을 사용해 다른 사람이 직무를 수행하게 하거나 자격증·등록증을 대여한 사람, 대여받거나 알선한 사람은 1년 이하 징역 또는 1천만원 이하 벌금":"성명·사무소 명칭을 빌려주거나 자격증을 대여·알선하면 1년 이하 징역 또는 1천만원 이하 벌금입니다.","자격·면허·경험·기능 취업 제한: 유해하거나 위험한 작업으로서 상당한 지식이나 숙련도가 요구되는 고용노동부령 작업은 그 작업에 필요한 자격·면허·경험 또는 기능을 가진 근로자가 아닌 사람에게 하게 해서는 안 된다(위반 3년 이하 징역 또는 3천만원 이하 벌금), 고용노동부장관은 교육기관을 지정할 수 있다":"유해하거나 위험한 작업으로 상당한 지식이나 숙련이 필요한 작업은 필요한 자격·면허·경험·기능을 가진 근로자가 아니면 하게 해서는 안 됩니다.","자격은 의료법에 따른 의사로서 직업환경의학과 전문의, 예방의학 전문의 또는 산업보건에 관한 학식과 경험이 있는 사람":"산업보건의는 직업환경의학과나 예방의학 전문의이거나 산업보건에 학식과 경험이 있는 의사여야 합니다.","자기반응성 물질: 열적으로 불안정하여 산소가 공급되지 않아도 강렬하게 발열·분해하기 쉬운 액체·고체 또는 혼합물":"열적으로 불안정해 산소 없이도 격렬하게 발열·분해하는 물질이 자기반응성 물질입니다.","자기발열성 물질: 주위의 에너지 공급 없이 공기와 반응하여 스스로 발열하는 물질(자기발화성 물질 제외)":"자기발열성 물질은 외부 에너지 공급 없이 공기와 반응해 스스로 열을 내는 물질이며 자기발화성 물질은 제외합니다.","자연발화성 액체·자연발화성 고체: 적은 양으로도 공기와 접촉하여 5분 안에 발화할 수 있는 액체·고체":"자연발화성 물질은 적은 양이라도 공기와 닿으면 5분 안에 발화할 수 있는 액체·고체입니다.","자율검사프로그램에 따른 안전검사 업무를 거짓이나 부정한 방법으로 수행한 자: 3년 이하 징역 또는 3천만원 이하 벌금":"자율검사프로그램 검사를 거짓·부정하게 하면 3년 이하 징역 또는 3천만원 이하 벌금입니다.","자율검사프로그램의 유효기간은 2년, 자율안전검사 결과는 기록·보존(2년)":"자율검사프로그램의 유효기간은 2년이고 자율안전검사 결과는 2년 동안 기록·보존합니다.","자율안전검사기관은 대통령령 요건을 갖추어 지정, 취소·정지는 제21조제4항·제5항 준용":"자율안전검사기관도 대통령령 요건을 갖춘 곳을 장관이 지정하고 취소·정지는 제21조를 준용합니다.","자율안전확인 신고를 하지 않고 제조·수입·양도·대여·사용하거나 진열하는 행위 금지(1년 이하 징역 또는 1천만원 이하 벌금)":"신고 없이 만들거나 팔거나 쓰거나 진열하면 1년 이하 징역 또는 1천만원 이하 벌금을 받습니다.","자체 교육을 할 수 있는 사람은 안전보건관리책임자, 관리감독자, 안전관리자, 보건관리자, 안전보건관리담당자, 산업보건의 / 공단의 강사요원 교육과정 이수자 / 산업안전지도사·산업보건지도사 / 학식과 경험이 있는 사람으로서 고용노동부장관이 정하는 기준에 해당하는 사람":"사업주가 직접 교육할 수 있는 사람은 책임자, 관리자, 지도사, 공단 강사요원 이수자 등입니다.","작성 대상(규칙 별표 2)은 농업·어업·소프트웨어 개발 및 공급업·컴퓨터 프로그래밍 등·영상오디오물 제공·정보서비스업·금융 및 보험업·임대업(부동산 제외)·전문과학기술 서비스업(연구개발 제외)·사업지원 서비스업·사회복지 서비스업은 상시근로자 300명 이상, 그 밖의 사업은 100명 이상":"규정 작성 대상은 농업, 어업, 소프트웨어, 금융·보험업 등은 상시근로자 300명 이상이고 그 밖의 사업은 100명 이상입니다.","작성·변경 기한은 작성해야 할 사유가 발생한 날부터 30일 이내, 변경할 사유가 발생한 경우에도 30일 이내":"규정은 작성이나 변경 사유가 생긴 날부터 30일 이내에 작성하거나 변경해야 합니다.","작성·변경 절차는 산업안전보건위원회의 심의·의결(변경 포함), 위원회가 설치되어 있지 않은 사업장은 근로자대표의 동의":"작성·변경 절차는 산업안전보건위원회 심의·의결이며 위원회가 없으면 근로자대표의 동의를 받습니다.","작성·제출 제외 대상(영 제86조): 건강기능식품 / 농약 / 마약 및 향정신성의약품 / 비료 / 사료 / 생활주변방사선 안전관리법상 원료물질 / 안전확인대상생활화학제품·살생물제품 중 일반소비자 생활용 / 식품 및 식품첨가물 / 의약품 및 의약외품 / 방사성물질 / 위생용품 / 의료기기 / 첨단바이오의약품 / 화약류 / 폐기물 / 화장품":"작성·제출 제외 대상에는 건강기능식품, 농약, 마약, 비료, 사료, 식품, 의약품 및 일반소비자 생활용 제품 등이 있습니다.","작성할 때 산업안전보건위원회의 심의를 거친다, 위원회가 설치되어 있지 않은 사업장은 근로자대표의 의견을 듣는다":"보고서를 작성할 때 산업안전보건위원회의 심의를 거치고 위원회가 없으면 근로자대표의 의견을 듣습니다.","작성할 때 소방·가스·전기·교통 분야 등 다른 법령의 안전관리 규정과 통합하여 작성할 수 있다":"규정은 소방, 가스, 전기, 교통 분야 등 다른 법령의 안전관리 규정과 통합해 작성할 수 있습니다.","작업·공사 중지 또는 변경 명령 위반 5년 이하 징역 또는 5천만원 이하 벌금(제42조제4항 후단)":"작업·공사 중지 또는 변경 명령을 위반하면 5년 이하 징역 또는 5천만원 이하 벌금입니다.","작업내용 변경 시 교육은 일용근로자 및 1주일 이하 기간제: 1시간 이상 / 그 밖의 근로자: 2시간 이상":"작업내용이 바뀔 때 교육은 일용·단기 1시간 이상, 나머지 근로자는 2시간 이상입니다.","작업을 도급하는 자는 시작 전에 수급인에게 안전 및 보건에 관한 정보를 문서로 제공해야 한다: 폭발성·발화성·인화성·독성 등 화학물질을 제조·사용·운반·저장하는 반응기·증류탑·배관·저장탱크 설비의 개조·분해·해체·철거 작업 / 그 설비 내부 작업 / 질식 또는 붕괴의 위험이 있는 작업":"작업을 도급하는 자는 시작 전에 폭발성·독성 화학물질 설비의 개조·해체·철거 작업 등에 관한 안전·보건 정보를 문서로 제공해야 합니다.","작업의 종료 시간 및 작업장의 폐쇄 시간은 협의사항이 아니다":"작업 종료 시간과 작업장 폐쇄 시간은 협의체에서 정하는 협의사항이 아닙니다.","작업이 정상적으로 이루어져 작업시간과 유해인자에 대한 근로자의 노출 정도를 정확히 평가할 수 있을 때 실시할 것 (일출 후 일몰 전 같은 시간 조건은 규정에 없다)":"정상 작업이어서 시간과 노출을 정확히 평가할 수 있을 때 하며 일출·일몰 조건은 없습니다.","작업중지 해제: 사업주가 해제를 요청하면 전문가 등으로 구성된 심의위원회의 심의를 거쳐 해제":"작업중지를 풀어 달라고 사업주가 요청하면 전문가가 참여한 심의위원회가 따져 보고 해제합니다.","작업환경측정 결과, 건강진단 결과에 대해 위원회 또는 근로자대표가 요구하면 설명회 개최 또는 건강진단기관 설명, 개별 근로자의 건강진단 결과는 본인 동의 없이 공개 불가":"작업환경측정과 건강진단 결과는 위원회나 근로자대표가 요구하면 설명하고, 개별 근로자의 건강진단 결과는 본인 동의 없이 공개하지 않습니다.","작업환경측정 결과를 근로자에게 알리지 않은 것(제125조제6항 앞부분)은 과태료 500만원 이하이고, 후속 조치를 하지 않은 것은 벌금":"측정 결과를 알리지 않은 것은 과태료이고 후속 조치를 하지 않은 것은 벌금입니다.","작업환경측정 결과 서류는 규칙에서 5년(고시 물질 30년)으로 연장, 건강진단 결과표도 5년(고시 물질 30년)":"작업환경측정 결과 서류와 건강진단 결과표는 규칙에서 5년으로 늘어나고 고시 물질은 30년 보존합니다.","작업환경측정기관에 위탁하는 경우 공정별 작업내용, 화학물질의 사용실태 및 물질안전보건자료 등 필요한 정보를 제공할 것":"측정기관에 맡길 때는 공정별 작업내용과 화학물질 사용실태, MSDS 등을 알려 줘야 합니다.","작업환경측정기관이 되려는 자는 대통령령 인력·시설·장비 요건을 갖추어 고용노동부장관의 지정을 받아야 한다, 취소·정지는 제21조제4항·제5항 준용":"측정기관이 되려면 요건을 갖춰 장관의 지정을 받고 취소·정지는 제21조를 준용합니다.","작업환경측정은 작업환경 실태를 파악하기 위하여 해당 근로자 또는 작업장에 대하여 사업주가 유해인자에 대한 측정계획을 수립한 후 시료를 채취하고 분석·평가하는 것":"작업환경측정은 사업주가 측정계획을 세운 뒤 시료를 채취하고 분석·평가해 작업환경 실태를 파악하는 것입니다.","잠함 또는 잠수 작업 등 높은 기압에서 하는 작업에 종사하는 근로자: 1일 6시간, 1주 34시간을 초과하여 근로하게 해서는 안 된다, 위반 시 3년 이하 징역 또는 3천만원 이하 벌금":"높은 기압 작업은 1일 6시간, 1주 34시간을 넘기면 3년 이하 징역 또는 3천만원 이하 벌금입니다.","장소별 안전조치: 추락 위험 장소 / 토사·구축물 붕괴 우려 장소 / 물체가 떨어지거나 날아올 위험 장소 / 천재지변으로 인한 위험 우려 장소":"장소별 안전조치는 추락 위험, 토사·구축물 붕괴 우려, 물체의 낙하·비래 위험, 천재지변 위험 장소에 대해 합니다.","적용 제외 사업·사업장과 제외되는 규정은 시행령 별표 1":"법이 적용되지 않는 사업·사업장과 제외 규정은 시행령 별표 1에 정해져 있습니다.","전기용품 및 생활용품 안전관리법 제8조 안전검사는 안전검사 면제 목록에 없다(자율안전확인 신고 면제 사유)":"전기용품 안전관리법상 안전검사는 안전검사 면제가 아니라 자율안전확인 신고 면제 사유입니다.","전담 보건관리자는 업종 구분 없이 상시근로자 300명 이상 사업장":"업종과 상관없이 상시근로자가 300명 이상이면 보건관리자가 다른 일 없이 이 업무만 합니다.","전담 안전관리자는 상시근로자 300명 이상 사업장(건설업은 공사금액 120억원 이상, 토목공사업 150억원 이상)은 안전관리자가 그 업무만 전담해야 한다":"상시근로자 300명 이상 사업장은 안전관리자가 그 업무만 전담해야 하고 건설업은 공사금액 120억원 이상 기준입니다.","전부 면제(규칙 제109조제1항): 연구·개발 목적 제조·수입 또는 수출 목적 제조 / 건설기계관리법 검사 또는 형식승인·형식신고 / 고압가스 안전관리법 검사 / 광산안전법 검사 중 설치·변경공사 완료 시 검사 / 방위사업법 품질보증 / 선박안전법 검사 / 에너지이용 합리화법 검사 / 원자력안전법 검사 / 위험물안전관리법 검사 / 전기사업법·전기안전관리법 검사 / 항만법 검사 / 소방시설법 형식승인":"연구·개발 목적 제조, 수출 목적 제조, 건설기계관리법 검사, 고압가스 안전관리법 검사 등은 안전인증을 전부 면제받습니다.","전산입력자료가 있으면 서류 대신 전산입력자료를 보존할 수 있다":"전산입력자료로 갖고 있다면 종이 서류 대신 그 자료를 보존해도 됩니다.","절곡기, 천공기는 별표 20 대상이 아니다":"절곡기와 천공기는 별표 20이 정한 방호조치 대상 기계에 들어 있지 않습니다.","정기교육: 연간 16시간 이상":"정기교육 시간은 연간 16시간 이상입니다.","정기교육 미실시: 근로자 1명당 1차 10만원·2차 20만원·3차 50만원 / 관리감독자 1명당 50만원·250만원·500만원":"정기교육을 하지 않으면 근로자 1명당 10만·20만·50만원, 관리감독자 1명당 50만·250만·500만원의 과태료입니다.","정기교육은 근로자 정기교육 항목(건강증진·질병 예방 제외) + 작업공정의 유해·위험과 재해 예방대책 / 사업장 내 안전보건관리체제 및 안전·보건조치 현황 / 표준안전 작업방법 결정 및 지도·감독 요령 / 현장근로자와의 의사소통능력 및 강의능력 등 교육 능력 배양 / 비상시·재해 발생 시 긴급조치 / 그 밖의 관리감독자의 직무":"관리감독자 정기교육은 근로자 정기교육 항목에 작업공정의 유해·위험, 안전보건관리체제, 표준작업방법 지도 요령, 교육 능력 배양이 더해집니다.","정기 안전·보건점검 횟수: 건설업, 선박 및 보트 건조업은 2개월에 1회 이상, 그 밖의 사업은 분기에 1회 이상":"정기 점검 횟수는 건설업과 선박 건조업이 2개월에 한 번, 다른 업종은 분기에 한 번입니다.","정기회의는 2개월마다, 임시회의는 위원장이 필요하다고 인정할 때":"노사협의체는 2개월마다 정기회의를 열고 임시회의는 위원장이 필요하다고 볼 때 엽니다.","정기회의는 분기마다 위원장이 소집, 임시회의는 위원장이 필요하다고 인정할 때 소집":"정기회의는 위원장이 분기마다 소집하고 임시회의는 필요하다고 판단할 때 소집합니다.","정기회의 미개최 1회당 1차 50만원, 2차 250만원, 3차 500만원":"정기회의를 열지 않으면 1회당 1차 50만원, 2차 250만원, 3차 500만원의 과태료가 부과됩니다.","정보 제공 위반: 1년 이하 징역 또는 1천만원 이하 벌금":"정보를 제공하지 않은 도급인은 1년 이하 징역이나 1천만원 이하 벌금에 처해집니다.","정부는 한국산업안전보건공단, 그 밖의 관련 단체 및 연구기관에 행정적·재정적 지원을 할 수 있다":"한국산업안전보건공단과 관련 연구기관에 정부가 예산과 행정을 뒷받침해 줄 수 있습니다.","제1차 검사 결과 질병의 확진이 곤란하면 제2차 건강진단을 받아야 한다":"제1차에서 질병 확진이 어려우면 이어서 제2차 건강진단을 받습니다.","제1차 검사항목: 과거병력·작업경력 및 자각·타각증상(시진·촉진·청진·문진) / 혈압·혈당·요당·요단백 및 빈혈검사 / 체중·시력 및 청력 / 흉부방사선 촬영 / AST(SGOT)·ALT(SGPT)·γ-GTP 및 총콜레스테롤, 혈당·γ-GTP·총콜레스테롤 검사는 고용노동부장관이 정하는 근로자에 대해 실시":"제1차 항목은 병력·경력, 혈압·혈당, 빈혈, 체중·시력·청력, 흉부촬영, 간기능, 콜레스테롤입니다.","제1호~제3호 사업장이 관계수급인의 사업장이고 도급인이 도급인의 조치의무(법 제63조)를 위반해 관계수급인 근로자가 재해를 입은 경우에는 도급인 사업장의 산업재해발생건수등을 함께 공표":"도급인이 법 제63조의 조치의무를 위반해 관계수급인 근로자가 재해를 입었다면 도급인 사업장의 재해건수 등도 함께 공표합니다.","제21조제4항·제5항은 안전보건교육기관, 안전보건진단기관, 건설재해예방전문지도기관, 안전인증기관, 안전검사기관, 자율안전검사기관, 석면조사기관, 작업환경측정기관, 특수건강진단기관, 타워크레인 설치·해체업자, 석면해체·제거업자, 제140조제2항 교육기관에 준용, 역학조사 업무 위탁기관은 준용 대상이 아니다":"제21조제4항·제5항은 안전보건교육기관, 안전인증기관, 작업환경측정기관, 특수건강진단기관 등 여러 기관에 준용됩니다.","제38조·제39조·제63조 위반으로 근로자를 사망에 이르게 한 사람에게는 200시간 범위의 수강명령 또는 이수명령 병과 가능":"안전조치·보건조치·도급인 조치 위반으로 근로자를 사망에 이르게 한 사람에게는 200시간 범위의 수강명령이나 이수명령을 병과할 수 있습니다.","제45조제1항 후단, 제46조제5항, 제53조제1항, 제87조제2항, 제118조제4항, 제119조제4항, 제131조제1항(임시건강진단 명령) 명령 위반 / 안전 및 보건 평가, 안전인증, 안전검사 업무 또는 자율검사프로그램에 따른 안전검사 업무를 거짓·부정한 방법으로 수행한 자":"제45조제1항 후단, 제46조제5항, 제53조제1항 등과 임시건강진단 명령 위반을 열거한 조항들입니다.","제58조제1항 위반 도급은 제167조~제172조 벌칙 조문에 열거되어 있지 않고 제161조의 과징금으로 제재한다":"제58조제1항 위반 도급은 징역·벌금 조문이 아니라 제161조의 과징금으로 제재합니다.","제80조제1항·제2항·제4항 위반: 1년 이하 징역 또는 1천만원 이하 벌금 (3년 이하 징역 3천만원 아님)":"제80조 위반 벌칙은 1년 이하 징역 또는 1천만원 이하 벌금이지 3년 이하가 아닙니다.","제85조제4항·제92조제2항 명령 위반 / 제101조 조사·수거·성능시험 방해·거부 / 제153조제1항·제2항 자격대여·대여받음·알선":"명령 위반, 조사·수거 방해, 자격대여·알선도 1년 이하 징역 또는 1천만원 이하 벌금 구간입니다.","제공 문서 기재 사항: 위험물질 및 관리대상 유해물질의 명칭과 유해성·위험성 / 안전·보건상 유해하거나 위험한 작업의 주의사항 / 유출 등 사고 발생 시 조치 내용":"제공 문서에는 위험물질의 명칭과 유해성, 작업 주의사항, 유출 등 사고 발생 시 조치 내용을 기재합니다.","제외 설비: 원자력 설비 / 군사시설 / 사업장 내 직접 사용 난방용 연료의 저장·사용설비 / 도매·소매시설 / 차량 등의 운송설비 / LPG 충전·저장시설 / 도시가스 공급시설 / 피해 정도가 크지 않다고 고시하는 설비":"원자력 설비, 군사시설, 난방용 연료 설비, 도매·소매시설, 운송설비, LPG 충전·저장시설, 도시가스 공급시설 등은 제외 설비입니다.","제조업·기계설비: 해당 작업 시작 15일 전까지 유해위험방지계획서에 건축물 각 층의 평면도, 기계·설비의 개요, 배치도면, 작업방법 개요 등을 첨부해 공단에 2부 제출(기계·설비는 설치장소 개요, 설비 도면)":"제조업·기계설비는 작업 시작 15일 전까지 평면도, 기계·설비 개요, 배치도면, 작업방법 개요 등을 첨부해 공단에 2부 제출합니다.","제조업 등(대통령령 사업, 전기 계약용량 300킬로와트 이상)에서 제품 생산 공정과 직접 관련된 건설물·기계·기구 및 설비 등 전부를 설치·이전하거나 주요 구조부분을 변경하려는 경우":"전기 계약용량 300킬로와트 이상 제조업의 생산 공정 설비를 설치·이전·변경하면 대상입니다.","제출 시기: 설비의 설치·이전 또는 주요 구조부분 변경공사의 착공일(규정량에 해당하게 된 경우 그 해당일) 30일 전까지 2부를 공단에 제출":"설비의 설치·이전 또는 주요 구조부분 변경공사의 착공일 30일 전까지 2부를 공단에 제출합니다.","제품심사: 유해·위험기계등이 서면심사 내용과 일치하는지와 안전에 관한 성능이 안전인증기준에 적합한지 — 개별 제품심사(15일) 또는 형식별 제품심사(30일, 일부 방호장치·보호구 60일) 중 하나만":"제품심사는 서면심사 내용과 일치하고 성능이 기준에 맞는지 보며 개별 제품심사(15일)와 형식별 제품심사(30일) 중 하나만 합니다.","제품심사에서 처리기간 내 심사를 끝낼 수 없는 부득이한 사유가 있으면 15일의 범위에서 심사기간 연장":"제품심사를 기간 내에 끝낼 수 없는 부득이한 사유가 있으면 15일의 범위에서 심사기간을 늘립니다.","제한하려는 경우와 제한된 근로자의 건강이 회복되어 다시 근로하게 하려는 경우 미리 보건관리자(의사인 보건관리자), 산업보건의 또는 건강진단 실시 의사의 의견을 듣는다":"근로를 제한하거나 건강이 회복되어 다시 근로하게 하려면 미리 의사인 보건관리자, 산업보건의 또는 건강진단 실시 의사의 의견을 듣습니다.","조치 2: 대여받은 자에게 서면 발급 — 가. 기계등의 성능 및 방호조치의 내용 / 나. 특성 및 사용 시 주의사항 / 다. 수리·보수 및 점검 내역과 주요 부품의 제조일 / 라. 정밀진단 및 수리 후 안전점검 내역, 주요 안전부품의 교환이력 및 제조일":"대여자는 대여받는 자에게 기계등의 성능과 방호조치 내용, 사용 시 주의사항, 점검 내역과 제조일 등을 적은 서면을 발급합니다.","조치 3: 설치·해체 작업이 필요한 기계등의 설치·해체를 다른 설치·해체업자에게 위탁하면 — 법령상 자격·장비 확인 / 서면 발급 및 주지 / 안전보건규칙 준수 확인, 대여받은 자에게 확인 결과를 알릴 것(제4호)":"설치·해체가 필요한 기계등의 작업을 다른 업자에게 위탁하면 자격·장비를 확인하고 서면을 발급하며 확인 결과를 대여받은 자에게 알립니다.","조치 결과 보고: 근로 금지·제한, 작업전환, 근로시간 단축, 직업병 확진 의뢰 안내 소견이 있는 결과표를 받은 사업주는 받은 날부터 30일 이내 사후관리 조치결과 보고서를 제출":"근로 금지·제한, 작업전환 등 소견이 있는 결과표를 받은 사업주는 받은 날부터 30일 이내에 사후관리 조치결과 보고서를 제출합니다.","주기 1: 크레인(이동식 제외)·리프트(이삿짐운반용 제외)·곤돌라 — 설치가 끝난 날부터 3년 이내 최초 검사, 이후 2년마다, 건설현장에서 사용하는 것은 최초 설치한 날부터 6개월마다":"크레인·리프트·곤돌라는 설치가 끝난 날부터 3년 이내 최초 검사 후 2년마다 받고 건설현장에서 쓰는 것은 6개월마다 받습니다.","주기 2: 이동식 크레인·이삿짐운반용 리프트·고소작업대 — 자동차관리법 신규등록 이후 3년 이내 최초 검사, 이후 2년마다":"이동식 크레인 등은 자동차관리법 신규등록 후 3년 안에 첫 검사를 받고 이후 2년마다 받습니다.","주기 3: 프레스, 전단기, 압력용기, 국소 배기장치, 원심기, 롤러기, 사출성형기, 컨베이어, 산업용 로봇, 혼합기, 파쇄기 또는 분쇄기 — 설치가 끝난 날부터 3년 이내 최초 검사, 이후 2년마다, 공정안전보고서를 제출해 확인받은 압력용기는 4년마다":"프레스, 전단기, 압력용기, 국소 배기장치, 컨베이어, 산업용 로봇 등은 설치가 끝난 날부터 3년 이내 최초 검사 후 2년마다 받습니다.","주기: 사무직 종사 근로자(공장·공사현장과 같은 구역에 있지 않은 사무실에서 서무·인사·경리·판매·설계 등 사무업무에 종사하는 근로자, 판매업무 등에 직접 종사하는 근로자 제외)는 2년에 1회 이상, 그 밖의 근로자는 1년에 1회 이상":"일반건강진단은 사무직 종사 근로자는 2년에 1회 이상, 그 밖의 근로자는 1년에 1회 이상 실시합니다.","주기 단축: 측정 결과 노출기준 이상 공정의 근로자 / 직업병 유소견자가 발견된 공정의 근로자 / 의사가 단축 필요 소견을 낸 근로자 — 다음 회에 한정해 주기를 2분의 1로 단축":"기준 이상 공정과 유소견자 발견 공정 근로자, 의사 단축 소견자는 다음 회에 한해 2분의 1로 줄입니다.","주민홍보계획은 비상조치계획의 세부내용이고, 변경요소 관리계획·도급업체 안전관리계획·자체감사 및 사고조사계획은 안전운전계획, 각종 건물·설비의 배치도는 공정안전자료":"주민홍보계획은 비상조치계획, 변경요소 관리계획 등은 안전운전계획, 건물·설비 배치도는 공정안전자료의 세부내용입니다.","주요 구조 부분을 변경하는 경우 안전인증을 받아야 하는 기계·설비: 프레스 / 전단기 및 절곡기 / 크레인 / 리프트 / 압력용기 / 롤러기 / 사출성형기 / 고소작업대 / 곤돌라 (컨베이어·원심기는 해당 없음)":"주요 구조 부분을 변경할 때 안전인증을 받아야 하는 기계는 프레스부터 곤돌라까지이며 컨베이어와 원심기는 해당 없습니다.","중대산업사고: 근로자가 사망하거나 부상을 입을 수 있는 설비에서의 누출·화재·폭발 사고, 인근 지역 주민이 인적 피해를 입을 수 있는 설비에서의 누출·화재·폭발 사고":"중대산업사고는 근로자나 인근 지역 주민이 인적 피해를 입을 수 있는 설비에서 일어나는 누출·화재·폭발 사고입니다.","중대산업재해: 사망자 1명 이상 / 동일한 사고로 6개월 이상 치료가 필요한 부상자 2명 이상 / 동일한 유해요인으로 급성중독 등 대통령령 직업성 질병자가 1년 이내 3명 이상":"중대산업재해는 사망자 1명 이상, 동일 사고로 6개월 이상 치료 부상자 2명 이상, 동일 유해요인 직업성 질병자 1년 이내 3명 이상입니다.","중대시민재해: 사망자 1명 이상 / 동일한 사고로 2개월 이상 치료 부상자 10명 이상 / 동일한 원인으로 3개월 이상 치료 질병자 10명 이상":"중대시민재해는 사망자 1명 이상, 2개월 이상 치료 부상자 10명 이상, 3개월 이상 치료 질병자 10명 이상입니다.","중대재해 발생 보고 미이행·거짓 보고: 과태료 3천만원 이하 (영 별표 35: 1차부터 3,000만원)":"중대재해 발생 보고를 하지 않거나 거짓 보고하면 과태료 3천만원 이하이고 영 별표 35에서 1차부터 3,000만원입니다.","중대재해의 범위는 고용노동부령(시행규칙 제3조)에서 정한다":"범위는 법률에 두지 않고 시행규칙 제3조에서 따로 정하고 있습니다.","중대재해 처벌 등에 관한 법률의 중대산업재해와 다른 개념":"이 법의 중대재해는 중대재해 처벌 등에 관한 법률의 중대산업재해와 서로 다른 개념입니다.","중대재해 처벌법은 상시근로자 5명 미만 사업장의 개인사업주·경영책임자등에게는 적용하지 않는다":"상시근로자가 5명 미만이면 개인사업주와 경영책임자등에게 중대재해처벌법이 적용되지 않습니다.","중대한 건강장해를 일으킬 우려가 있는 화학물질에 대해 고용노동부장관은 제조·수입자 또는 사용 사업주에게 유해성·위험성 조사와 결과 제출을 명할 수 있다, 조사 결과 건강장해가 우려되면 시설·설비 설치·개선 등 조치":"중대한 건강장해 우려 화학물질은 장관이 제조·수입자나 사용 사업주에게 유해성·위험성 조사와 결과 제출을 명할 수 있습니다.","증원·교체 명령 사유(지방고용노동관서의 장)는 연간재해율이 같은 업종 평균재해율의 2배 이상 / 중대재해가 연간 2건 이상(전년도 사망만인율이 업종 평균 이하이면 제외) / 관리자가 질병 등으로 3개월 이상 직무를 수행할 수 없게 된 경우 / 화학적 인자로 인한 직업성 질병자가 연간 3명 이상 발생":"증원·교체 명령 사유에는 재해율이 평균의 2배 이상, 중대재해 연 2건 이상, 직무 불능 3개월 이상 등이 있습니다.","지도사가 직무를 수행하려면 고용노동부령에 따라 고용노동부장관에게 등록해야 한다, 등록 후 법인을 설립할 수 있고, 법인에는 상법 중 합명회사 규정을 적용":"지도사가 직무를 수행하려면 장관에게 등록해야 하고 등록 후 법인을 설립할 수 있으며 법인에는 상법의 합명회사 규정을 적용합니다.","지도사는 업무 관련 서류를 5년 보존":"지도사는 업무 관련 서류를 5년 동안 보존해야 합니다.","지도사는 직무상 알게 된 비밀을 누설하거나 도용해서는 안 된다":"직무상 알게 된 비밀은 누설하거나 도용할 수 없습니다.","지도사는 직무 수행에 필요하면 사업주에게 관계 장부 및 서류의 열람을 신청할 수 있고, 사업주는 정당한 사유 없이 거부할 수 없다":"지도사는 사업주에게 장부와 서류 열람을 신청할 수 있고 사업주는 정당한 사유 없이 막지 못합니다.","지도사 자격이 있는 사람이 직무를 수행하려면 등록 전 1년의 범위에서 연수교육을 받아야 한다, 산업안전·산업보건 분야 5년 이상 실무경력자는 제외":"등록 전 1년 범위에서 연수교육이 필요하고 5년 이상 실무경력자는 면제됩니다.","지도실적: 갱신기간 동안 사업장 또는 고시 기관·단체에서 지도하거나 종사한 실적, 실적 기간이 3년 미만이면 기준 미달":"갱신기간 동안 지도하거나 종사한 실적이 3년 미만이면 실적 기준에 미달합니다.","지방고용노동관서의 장은 공표 대상 연도의 다음 연도 3월 15일까지 자료 제출을 요청하고, 도급인은 그 해 4월 30일까지 통합 산업재해 현황 조사표를 제출":"공표 다음 연도 3월 15일까지 자료를 요청받으면 도급인은 4월 30일까지 통합 조사표를 냅니다.","지방고용노동관서의 장의 명령을 받고 15일 이내 이행하면 보고한 것으로 보는 경우가 있다(안전관리자·보건관리자 선임 의무자, 안전보건총괄책임자 지정 도급인, 지도 대상 건설공사도급인, 은폐 사업주는 제외)":"관서장의 명령을 받고 15일 이내 이행하면 보고한 것으로 보는 경우가 있으나 관리자 선임 의무자나 은폐 사업주 등은 제외합니다.","지상높이 31미터 이상인 건축물 또는 인공구조물의 건설·개조·해체 / 연면적 3만제곱미터 이상 건축물 / 연면적 5천제곱미터 이상 시설 — 문화 및 집회시설(전시장·동물원·식물원 제외), 판매시설, 운수시설(고속철도 역사·집배송시설 제외), 종교시설, 종합병원, 관광숙박시설, 지하도상가, 냉동·냉장 창고시설":"건설공사 대상은 지상높이 31미터 이상 건축물, 연면적 3만제곱미터 이상 건축물, 연면적 5천제곱미터 이상 판매·운수·종교시설 등의 공사입니다.","지정 대상 사업은 관계수급인에게 고용된 근로자를 포함한 상시근로자가 100명 이상인 사업(선박 및 보트 건조업, 1차 금속 제조업, 토사석 광업은 50명 이상) 또는 관계수급인의 공사금액을 포함한 총공사금액이 20억원 이상인 건설업":"지정 대상은 상시근로자 100명 이상(선박 건조업, 1차 금속 제조업, 토사석 광업은 50명 이상)이거나 총공사금액 20억원 이상 건설업입니다.","지정받을 수 있는 자: 국가 또는 지방자치단체의 소속기관 / 의료법에 따른 종합병원 또는 병원 / 고등교육법 제2조제1호~제6호에 따른 대학 또는 그 부속기관 / 작업환경측정 업무를 하려는 법인 / 작업환경측정 대상 사업장의 부속기관(고용노동부령 범위로 한정)":"지정받을 수 있는 자는 국가·지방자치단체 소속기관, 종합병원 또는 병원, 대학 또는 그 부속기관, 측정 업무를 하려는 법인 등입니다.","지정을 받으려면 대통령령으로 정하는 인력·시설·장비 요건을 갖추어 고용노동부장관의 지정을 받아야 한다":"전문기관으로 지정받으려면 대통령령의 인력·시설·장비 요건을 갖춰 고용노동부장관의 지정을 받아야 합니다.","지정을 취소해야 하는 사유(필수)는 거짓이나 부정한 방법으로 지정받은 경우, 업무정지 기간 중에 업무를 수행한 경우":"거짓이나 부정한 방법으로 지정받았거나 업무정지 기간에 업무를 수행하면 지정을 반드시 취소해야 합니다.","지정이 취소된 자는 취소된 날부터 2년 이내에는 해당 기관으로 지정받을 수 없다":"지정이 취소되면 취소일부터 2년이 지나야 해당 기관으로 다시 지정받을 수 있습니다.","지정 취소 또는 6개월 이내 업무정지 사유는 거짓·부정한 방법으로 지정 / 업무정지 기간 중 업무 수행 / 지정 요건 미충족 / 지정받은 사항을 위반한 업무 수행 / 그 밖에 대통령령 사유":"지정 취소나 6개월 이내 업무정지 사유에는 거짓·부정 지정, 정지 중 업무 수행, 요건 미충족, 지정사항 위반 업무 등이 있습니다.","지정 취소·정지 사유(영 제96조): 서류 거짓 작성 / 정당한 사유 없이 측정 거부 / 위탁받은 업무에 차질 / 고용노동부령 측정방법 위반 / 측정·분석능력 확인을 1년 이상 받지 않거나 부적합 판정 / 비치서류 미보존 / 공무원 지도·감독 거부":"지정 취소·정지 사유에는 서류 거짓 작성, 정당한 사유 없는 측정 거부, 측정방법 위반, 능력 확인 미수검·부적합 판정 등이 있습니다.","직무 1 건강진단 결과의 검토 및 그 결과에 따른 작업 배치, 작업 전환 또는 근로시간 단축 등 근로자의 건강보호 조치 / 직무 2 근로자의 건강장해의 원인 조사와 재발 방지를 위한 의학적 조치 / 직무 3 그 밖에 근로자의 건강 유지 및 증진을 위하여 필요한 의학적 조치에 관하여 고용노동부장관이 정하는 사항":"산업보건의 직무는 건강진단 결과 검토와 작업 배치·전환·근로시간 단축 조치, 건강장해 원인 조사와 의학적 재발 방지 조치 등입니다.","직무 1 위험성평가의 실시에 관한 사항 / 2 작업의 중지(법 제51조·제54조) / 3 도급 시 산업재해 예방조치 / 4 산업안전보건관리비의 관계수급인 간 사용에 관한 협의·조정 및 집행 감독 / 5 안전인증대상기계등과 자율안전확인대상기계등의 사용 여부 확인":"안전보건총괄책임자 직무에는 위험성평가 실시, 작업중지, 도급 시 재해 예방조치, 안전보건관리비 사용 협의·조정 등이 있습니다.","직무교육 대상은 안전보건관리책임자 / 안전관리자 / 보건관리자 / 안전보건관리담당자 / 안전관리전문기관·보건관리전문기관·건설재해예방전문지도기관·안전검사기관·자율안전검사기관·석면조사기관에서 안전·보건 업무에 종사하는 사람":"직무교육 대상은 책임자, 안전·보건관리자, 담당자와 전문기관·검사기관·석면조사기관에서 안전·보건 업무에 종사하는 사람입니다.","직무교육 미이수(전문기관 종사자) / 근로자대표 통지 미이행 / 근로자의 조치사항 불이행(제40조) / 신규화학물질 조치 서류 미제공(제108조제5항) / 건강진단 결과 목적 외 사용(제132조제3항) / 건강진단 미수검(제133조) / 지도사 유사명칭(제149조) / 자격자 의견 미청취 / 확인 미수령 / 지도계약 미체결 / 일반석면조사 미실시 / 석면 신고 / 석면농도 증명자료 미제출 / 보고·제출·통보 미이행 / 질문 답변 거부 / 공단 검사·지도 거부 / 서류 미보존":"직무교육 미이수, 근로자대표 통지 미이행, 근로자의 조치사항 불이행, 건강진단 결과 목적 외 사용, 건강진단 미수검 등도 과태료 대상입니다.","직무교육 신청은 직무교육기관의 장은 교육 실시 15일 전까지 일시·장소 통지, 매년 12월 31일까지 다음 연도 교육 실시계획서를 고용노동부장관에게 제출해 승인받는다":"교육기관은 15일 전 일시·장소를 알리고 해마다 12월 31일까지 다음 해 실시계획서 승인을 받습니다.","직무교육을 이수한 사람이 다른 사업장으로 전직해 신규 선임되면 전직 전 교육이수증명서 제출로 이수한 것으로 본다":"다른 사업장으로 옮겨 신규 선임돼도 이전에 받은 교육이수증명서를 내면 이수로 인정합니다.","진단 명령 위반 과태료 1천만원 이하(영 별표 35: 1,000만원), 진단 거부·방해·기피 1천500만원 이하, 근로자대표 미참여 1차 150만원":"진단 명령 위반은 1천만원, 거부·방해는 1천500만원 이하이고 근로자대표 미참여는 1차 150만원입니다.","진동: 착암기, 손망치 등의 공구를 사용함으로써 발생되는 백랍병·레이노 현상·말초순환장애 등의 국소 진동 및 차량 등을 이용함으로써 발생되는 관절통·디스크·소화장애 등의 전신 진동":"진동은 착암기, 손망치 등으로 생기는 국소 진동과 차량 등을 이용할 때 생기는 전신 진동으로 나뉩니다.","질식·붕괴 위험 작업: 산소결핍·유해가스로 인한 질식 위험 장소에서의 작업 / 토사·구축물·인공구조물 등 붕괴 우려 장소에서의 작업":"질식·붕괴 위험 작업은 산소결핍이나 유해가스로 인한 질식 위험 장소 작업과 붕괴 우려 장소 작업입니다.","참석 대상(규칙): 요양급여·유족급여를 신청한 자 또는 그 대리인(근로복지공단 요청 조사에 한함), 공단은 역학조사평가위원회를 설치·운영":"역학조사 참석 대상은 요양급여·유족급여를 신청한 자 또는 그 대리인이며 공단은 역학조사평가위원회를 설치·운영합니다.","채용·변경된 작업에 경험이 있는 근로자는 채용 시 교육·특별교육 시간을 100분의 50 이상으로 실시 가능(같은 업종 6개월 이상 근무 경험자를 이직 후 1년 이내 채용 등)":"경험 있는 근로자는 채용 시·특별교육을 100분의 50 이상 시간으로 줄여 실시할 수 있습니다.","채용 시 교육: 8시간 이상 / 작업내용 변경 시 교육: 2시간 이상":"채용 시 교육은 8시간 이상이고 작업내용이 바뀔 때 교육은 2시간 이상입니다.","채용 시 교육은 일용근로자 및 근로계약기간 1주일 이하 기간제: 1시간 이상 / 근로계약기간 1주일 초과 1개월 이하 기간제: 4시간 이상 / 그 밖의 근로자: 8시간 이상":"채용 시 교육은 일용근로자 1시간, 1주일 초과 1개월 이하 기간제 4시간, 그 밖의 근로자 8시간 이상입니다.","채용 시·작업내용 변경 시 교육 미실시: 근로자 1명당 10만원·20만원·50만원":"채용 시·작업내용 변경 시 교육을 하지 않으면 근로자 1명당 10만원, 20만원, 50만원 과태료입니다.","채용 시·작업내용 변경 시는 근로자 항목 + 사업장 내 안전보건관리체제 및 조치 현황 / 표준안전 작업방법 결정 및 지도·감독 요령 / 비상시·재해 발생 시 긴급조치 / 그 밖의 관리감독자의 직무":"관리감독자의 채용 시·변경 시 교육은 근로자 항목에 관리체제 현황, 표준작업방법 지도 요령, 비상시 긴급조치, 직무가 더해집니다.","책임자 선임 의무 위반 과태료 500만원 이하":"책임자 선임 의무를 어기면 과태료 500만원 이하가 부과됩니다.","총공사금액 50억원 이상 건설공사의 건설공사발주자는 계획단계에 기본안전보건대장, 설계단계에 설계안전보건대장, 시공단계에 공사안전보건대장이 작성·이행되도록 해야 한다":"총공사금액 50억원 이상 건설공사의 발주자는 계획·설계·시공 단계마다 기본·설계·공사 안전보건대장이 작성·이행되도록 해야 합니다.","최대 지간길이 50미터 이상인 다리의 건설등 공사 / 터널의 건설등 공사 / 다목적댐, 발전용댐, 저수용량 2천만톤 이상의 용수 전용 댐 및 지방상수도 전용 댐의 건설등 공사 / 깊이 10미터 이상인 굴착공사":"최대 지간길이 50미터 이상 다리, 터널, 다목적댐·발전용댐 등, 깊이 10미터 이상 굴착공사의 건설등 공사가 대상입니다.","최초평가: 최초로 작업을 시작하기 전까지, 정기평가: 최초평가를 실시한 연도의 다음 연도부터 매년 1회 이상, 수시평가: 추가 유해·위험 요인 발생 우려나 중대산업사고·산업재해 발생 시 관련 작업 시작 전까지":"최초평가는 작업 전, 정기평가는 매년 1회 이상, 수시평가는 위험 우려나 재해 발생 시 합니다.","추락 및 감전 위험방지용 안전모 / 안전화 / 안전장갑 / 방진마스크 / 방독마스크 / 송기마스크 / 전동식 호흡보호구 / 보호복 / 안전대 / 차광 및 비산물 위험방지용 보안경 / 용접용 보안면 / 방음용 귀마개 또는 귀덮개":"보호구로는 안전모·안전화·안전장갑, 방진·방독·송기마스크, 보호복, 안전대, 보안경, 보안면, 귀마개가 나열됩니다.","취급 사업주의 의무: 작업장 내 근로자가 쉽게 볼 수 있는 장소에 게시하거나 갖추어 두고, 작업공정별 관리 요령 게시, 근로자 교육, 용기·포장에 경고표시(양도·제공자, 사업장 용기 사용 사업주)":"취급 사업주는 자료를 근로자가 쉽게 볼 수 있는 장소에 게시하거나 갖추고 관리 요령을 게시하며 교육하고 용기·포장에 경고표시를 합니다.","취소된 날부터 2년 이내 재등록 불가":"등록이 취소된 날부터 2년 이내에는 다시 등록할 수 없습니다.","취소 또는 정지(임의): 직무 수행과정에서 고의 또는 과실로 중대재해가 발생한 경우 / 등록 결격사유(제145조제3항제1호~제5호)에 해당하게 된 경우 / 보증보험에 가입하지 않거나 필요한 조치를 하지 않은 경우 / 품위유지·성실의무 위반 또는 서명 누락 / 금지행위(제151조)·자격대여(제153조제1항)·비밀유지(제162조) 위반":"고의·과실로 중대재해를 낸 경우, 결격사유에 해당하게 된 경우, 보증보험 미가입 등은 취소나 정지를 고릅니다.","취소 시 취소일부터 30일 이내에 명칭·형식번호, 인증번호, 제조자(수입자), 사업장 소재지, 취소일 및 사유를 관보·일간신문·인터넷 등에 공고":"취소하면 30일 이내에 명칭, 인증번호, 제조자, 소재지, 취소일 및 사유를 관보·일간신문·인터넷 등에 공고합니다.","측정 결과 기록 서류 보존기간: 법 3년, 규칙 5년(고시 물질은 30년), 측정기관은 3년":"측정 결과 서류는 법 3년, 규칙 5년(고시 물질은 30년) 보존하며 측정기관은 3년 보존합니다.","측정 결과 보고: 시료채취를 마친 날부터 30일 이내 관할 지방고용노동관서의 장에게 제출(30일 범위에서 연장 가능), 노출기준 초과 공정은 시료채취를 마친 날부터 60일 이내 개선 증명서류 또는 개선 계획 제출":"측정 결과는 시료채취를 마친 날부터 30일 이내에 지방고용노동관서에 보고하고 기준 초과 공정은 60일 이내 개선 증명서류나 계획을 냅니다.","측정기관 유형: 사업장 위탁측정기관(위탁받은 사업장) / 사업장 자체측정기관(그 사업장·계열회사 사업장 또는 수급인 사업장)":"측정기관은 위탁받은 사업장의 사업장 위탁측정기관과 그 사업장·계열회사·수급인 사업장의 사업장 자체측정기관으로 나뉩니다.","측정을 하지 않은 경우 과태료 1천만원 이하(영 별표 35: 근로자 1명당 20만원·50만원·100만원), 측정방법 미준수 500만원 이하, 근로자대표 미참석 500만원 이하, 결과 미통지 500만원 이하":"측정을 하지 않으면 과태료 1천만원 이하이고 측정방법 미준수, 근로자대표 미참석, 결과 미통지는 각각 500만원 이하입니다.","측정자 자격: 그 사업장에 소속된 사람 중 산업위생관리산업기사 이상의 자격을 가진 사람":"측정은 그 사업장 소속의 산업위생관리산업기사 이상 자격자가 할 수 있습니다.","측정 주기: 신규 가동·변경 등으로 측정 대상 작업장이 된 날부터 30일 이내 측정, 그 후 반기에 1회 이상, 화학적 인자의 측정치가 노출기준을 초과(고시 물질)하거나 2배 이상 초과(그 밖의 물질)하면 측정일부터 3개월에 1회 이상":"측정은 대상 작업장이 된 날부터 30일 이내에 하고 이후 반기에 1회 이상 하며 기준을 초과하면 측정일부터 3개월에 1회 이상 합니다.","크레인·리프트·곤돌라: 관계 법령 / 개론 / 구조 및 특성 / 검사기준 / 방호장치 / 검사장비 / 검사실습 및 체크리스트 / 위험검출 훈련 / 검사원 직무":"크레인·리프트·곤돌라 검사원 교육은 법령, 구조 및 특성, 검사기준, 방호장치, 체크리스트, 위험검출 훈련, 검사원 직무로 구성됩니다.","타워크레인 등(타워크레인, 건설용 리프트, 항타기 및 항발기)이 설치·작동 중이거나 설치·해체·조립 작업 중이면 건설공사도급인은 필요한 안전·보건조치를 해야 한다, 위반 시 3년 이하 징역 또는 3천만원 이하 벌금":"타워크레인 등이 설치·작동·해체 중이면 도급인이 안전·보건조치를 해야 하고 어기면 3년 이하 징역입니다.","타워크레인 설치·해체업 미등록 설치·해체: 과태료 1천만원 이하(형벌 아님), 등록한 자에게 시키지 않은 사업주는 3년 이하 징역":"미등록 설치·해체는 과태료 1천만원 이하이고 등록자에게 안 맡긴 사업주는 3년 이하 징역입니다.","타워크레인을 대여받은 자: 충돌위험이 있으면 충돌방지장치 설치 등 조치 / 설치·해체 작업과정 전반을 영상으로 기록하여 대여기간 동안 보관":"타워크레인을 빌린 자는 충돌방지장치를 달고 설치·해체 과정을 영상으로 남겨 대여기간 보관합니다.","타워크레인을 설치하거나 해체하려는 자는 인력·시설·장비 요건을 갖추어 고용노동부장관에게 등록, 사업주는 등록한 자로 하여금 설치·해체하도록 해야 한다(미준수 3년 이하 징역 또는 3천만원 이하 벌금)":"타워크레인 설치·해체업은 장관에게 등록해야 하고 등록 안 한 자에게 시키면 3년 이하 징역입니다.","토사·구축물·인공구조물 붕괴 우려 장소 / 기계·기구 전도·붕괴 우려 장소 / 안전난간 필요 장소 / 비계·거푸집 설치·해체 장소 / 건설용 리프트 운행 장소 / 지반 굴착·발파작업 장소 / 엘리베이터홀 등 추락 위험 장소 / 석면이 붙어 있는 물질 파쇄·해체 장소 / 공중 전선 근처 감전 위험 장소 / 물체 낙하·비래 위험 장소 / 프레스·전단기 작업 장소 / 차량계 하역운반기계·건설기계 작업 장소 / 전기 기계·기구 감전 위험 작업 장소 / 철도차량 충돌·협착 위험 작업 장소 / 화재·폭발 등 사고 위험이 높은 장소로서 고용노동부령으로 정하는 장소":"토사·구축물 붕괴 우려 장소, 기계 전도 우려 장소, 안전난간 필요 장소, 비계·거푸집 해체 장소 등이 나열됩니다.","토사석 광업, 식료품·음료, 섬유, 목재, 펄프·종이, 코크스·석유정제, 화학, 의약품, 고무·플라스틱, 비금속 광물, 1차 금속, 금속가공, 전자부품, 의료·정밀기기, 전기장비, 기타 기계, 자동차, 기타 운송장비, 가구, 인쇄·출판, 폐기물·원료 재생, 환경 정화, 자동차 수리, 발전업, 운수 및 창고업 등: 상시근로자 50명 이상 500명 미만 1명 이상, 500명 이상 2명 이상":"안전관리자를 두어야 하는 업종으로 토사석 광업, 식료품·음료, 섬유, 화학, 자동차, 발전업, 운수 및 창고업 등이 열거됩니다.","통합공표 사업장은 제조업, 철도운송업, 도시철도운송업, 전기업이 이루어지는 사업장으로서 도급인이 사용하는 상시근로자 수가 500명 이상이고, 도급인 사업장의 사고사망만인율보다 관계수급인 근로자를 포함해 산출한 사고사망만인율이 높은 사업장":"통합공표는 제조업, 철도·도시철도운송업, 전기업의 상시근로자 500명 이상 도급 사업장 중 수급인 포함 사망만인율이 더 높은 곳입니다.","특별교육(법 제29조제3항) 미실시: 근로자 1명당 50만원·100만원·150만원":"특별교육을 하지 않으면 근로자 1명당 50만원, 100만원, 150만원의 과태료가 차례로 부과됩니다.","특별교육: 16시간 이상(최초 작업 종사 전 4시간 이상, 12시간은 3개월 이내 분할 가능), 단기간·간헐적 작업은 2시간 이상":"특별교육은 16시간 이상으로 최초 작업 전에 4시간을 하고 나머지는 3개월 이내 나눠 할 수 있습니다.","특별교육 대상 작업별 교육은 근로자 제1호라목과 같다":"관리감독자 특별교육의 작업별 내용은 근로자 특별교육의 별표 제1호라목과 동일합니다.","특별교육은 일용·1주일 이하 기간제: 별표 5 제1호라목 작업 종사자(제39호 제외) 2시간 이상, 제39호(타워크레인 신호업무) 종사자 8시간 이상":"특별교육은 일용·단기 근로자 중 일반 작업은 2시간 이상, 타워크레인 신호업무 종사자는 8시간 이상입니다.","특별교육을 실시하면 채용 시 교육·작업내용 변경 시 교육을 한 것으로 본다":"특별교육을 하면 채용 시 교육과 작업내용 변경 시 교육을 이미 마친 것으로 칩니다.","특수건강진단, 배치전건강진단, 수시건강진단은 특수건강진단기관에서 실시":"특수·배치전·수시 건강진단은 모두 특수건강진단기관이 실시합니다.","특수건강진단: 고용노동부령 유해인자에 노출되는 업무(특수건강진단대상업무) 종사 근로자, 직업병 소견으로 작업 전환·장소 변경한 근로자로서 의사 소견이 있는 사람에 대해 실시":"특수건강진단은 유해인자에 노출되는 업무 종사 근로자와 직업병 소견으로 작업 전환한 근로자로서 의사 소견이 있는 사람에게 실시합니다.","특수건강진단·배치전건강진단·수시건강진단 검사항목은 제1차 검사항목과 제2차 검사항목으로 구분, 제1차는 모든 대상 근로자에게, 제2차는 건강수준 평가가 곤란하거나 질병이 의심되는 사람에게":"제1차 항목은 모든 대상자에게, 제2차 항목은 평가가 어렵거나 질병이 의심되는 사람에게 합니다.","특수형태근로종사자: 최초 노무제공 시 2시간 이상(단기간·간헐적 1시간 이상), 특별교육 16시간 이상(단기간·간헐적 2시간 이상)":"특수형태근로종사자는 최초 노무제공 시 2시간 이상, 특별교육 16시간 이상이며 단기·간헐적 작업은 시간이 줄어듭니다.","특수형태근로종사자의 노무를 제공받는 자는 안전·보건조치 의무, 배달종사자·가맹본부에 대한 조치 규정도 있다":"특수형태근로종사자를 일시키는 자도 안전·보건조치 의무가 있고 배달종사자 관련 규정도 있습니다.","판매업무에 직접 종사하는 근로자: 매반기 6시간 이상":"판매업무에 직접 종사하는 근로자의 정기교육도 매반기 6시간 이상입니다.","판매업무 직접 종사 근로자 외의 근로자: 매반기 12시간 이상":"판매업무 직접 종사자가 아닌 근로자의 정기교육은 매반기 12시간 이상입니다.","평가는 서면조사 및 방문조사의 방법으로 실시":"신뢰성 평가는 서면조사와 방문조사의 방법으로 실시합니다.","평가 시 측정 결과와 측정 서류를 검토하고 해당 작업공정·사업장에 대해 작업환경측정을 하며 결과를 관할 지방고용노동관서의 장에게 보고, 노출기준 초과 시 지방고용노동관서의 장이 사업주에게 시설·설비 개선 또는 건강진단 실시 등을 하도록 한다":"평가 때 측정 결과와 서류를 검토하고 작업공정에 대해 측정하며 결과를 지방고용노동관서의 장에게 보고하고 기준 초과 시 개선 등을 명합니다.","평가의 주체는 사업주가 아니다 — 사업주가 신뢰성을 평가해 지방고용노동관서에 보고하는 규정은 없다":"신뢰성을 평가하는 주체는 사업주가 아니며 사업주가 평가해 보고하는 규정도 없습니다.","폐기물, 생활주변방사선 원료물질, 첨단바이오의약품은 영 제85조 제외 대상이 아니다 (군수품 중 통상품도 제외 대상이 아님)":"폐기물과 생활주변방사선 원료물질, 첨단바이오의약품은 영 제85조 제외 대상이 아닙니다.","폭발성 물질: 자체의 화학반응에 따라 주위환경에 손상을 줄 수 있는 정도의 온도·압력 및 속도를 가진 가스를 발생시키는 고체·액체 또는 혼합물":"폭발성 물질은 자체 화학반응으로 주위환경에 손상을 줄 만한 온도·압력·속도의 가스를 발생시키는 고체·액체 또는 혼합물입니다.","표준안전 작업방법에 관한 사항은 근로자 채용 시·변경 시 교육 내용에 없다(관리감독자 교육에는 있음)":"표준안전 작업방법 교육은 관리감독자에게만 있고 일반 근로자의 채용 시·변경 시 교육에는 없습니다.","품위유지와 성실의무, 직무와 관련해 작성·확인한 서류에 기명·날인 또는 서명":"지도사는 품위를 유지하고 성실히 직무를 수행하며 직무와 관련해 작성·확인한 서류에 기명·날인 또는 서명해야 합니다.","프레스 / 전단기 및 절곡기 / 크레인 / 리프트 / 압력용기 / 롤러기 / 사출성형기 / 고소작업대 / 곤돌라":"안전인증 대상 기계로는 프레스, 전단기 및 절곡기, 크레인, 리프트, 압력용기, 롤러기, 사출성형기, 고소작업대, 곤돌라가 있습니다.","프레스 및 전단기 방호장치 / 양중기용 과부하 방지장치 / 보일러 압력방출용 안전밸브 / 압력용기 압력방출용 안전밸브 / 압력용기 압력방출용 파열판 / 절연용 방호구 및 활선작업용 기구 / 방폭구조 전기기계·기구 및 부품 / 추락·낙하·붕괴 위험 방지용 가설기자재(고시) / 산업용 로봇 방호장치(고시)":"방호장치로는 프레스·전단기용, 과부하 방지장치, 안전밸브, 파열판, 절연용 방호구, 방폭 전기기계 등이 나열됩니다.","프레스·전단기: 관계 법령 / 개론 / 구조 및 특성 / 검사기준 / 방호장치 / 검사장비 용도 및 사용방법 / 검사실습 및 체크리스트 작성 요령 / 위험검출 훈련":"프레스·전단기 검사원 교육은 법령, 구조 및 특성, 검사기준, 방호장치, 검사실습, 위험검출 훈련으로 구성됩니다.","프로그램 포함 내용: 검사대상 기계등 보유 현황 / 검사원 보유 현황·장비 및 관리방법 / 검사 주기 및 검사기준 / 향후 2년간 검사수행계획 / 과거 2년간 수행 실적(재신청), 공단에 신청, 15일 이내 인정 여부 결정":"프로그램에는 검사대상 기계 보유 현황, 검사원과 장비 현황, 검사 주기와 기준, 향후 2년간 계획, 과거 2년간 실적이 들어갑니다.","합격한 사업주에게 안전검사합격증명서 발급, 사업주는 기계등에 부착":"합격한 사업주는 안전검사합격증명서를 받아 기계등에 붙여 둡니다.","합동 안전·보건점검반 구성: 도급인(지역이 다르면 그 사업장의 안전보건관리책임자) / 관계수급인(같음) / 도급인 및 관계수급인의 근로자 각 1명(관계수급인은 해당 공정만)":"합동 안전·보건점검반은 도급인, 관계수급인, 도급인 및 관계수급인의 근로자 각 1명으로 구성합니다.","해당 사업을 하는 사업장은 보유설비 전부: 원유 정제처리업 / 기타 석유정제물 재처리업 / 석유화학계 기초화학물질 제조업 또는 합성수지 및 기타 플라스틱물질 제조업(합성수지·플라스틱은 별표 13 제1호 또는 제2호에 해당하는 경우로 한정) / 질소 화합물, 질소·인산 및 칼리질 화학비료 제조업 중 질소질 비료 제조 / 복합비료 및 기타 화학비료 제조업 중 복합비료 제조(단순혼합·배합 제외) / 화학 살균·살충제 및 농업용 약제 제조업(농약 원제 제조만) / 화약 및 불꽃제품 제조업":"원유 정제처리업, 석유화학계 기초화학물질 제조업, 합성수지 제조업 등은 보유설비 전부가 공정안전보고서 대상입니다.","허가기준 유지의무(제118조제3항) 위반 3년 이하 징역, 허가 없이 제조·사용 5년 이하 징역":"허가기준 유지의무 위반은 3년 이하 징역이고 허가 없이 제조·사용하면 5년 이하 징역입니다.","허가대상물질은 제조등금지물질에 해당하나 대체물질이 개발되지 않아 고용노동부장관의 허가를 받아 제조·사용할 수 있는 물질, 허가받은 사항을 변경할 때도 허가":"허가대상물질은 대체물질이 없어 장관 허가를 받아 제조·사용할 수 있고 변경도 허가를 받습니다.","허가대상물질의 제조·사용설비, 작업방법 등 허가기준은 고용노동부령, 기준에 부적합하면 수리·개조·이전 또는 작업방법 변경 명령, 취소 또는 6개월 이내 영업정지(거짓·부정 허가는 필수 취소)":"허가기준에 안 맞으면 수리·개조 명령, 취소 또는 6개월 이내 영업정지이며 거짓 허가는 필수 취소입니다.","허가대상물질 제조·사용 작업은 도급금지 작업에 포함":"허가대상물질 제조·사용 작업은 도급해서는 안 되는 작업에 포함됩니다.","허용기준 이하 미유지 과태료 1천만원 이하":"허용기준 이하를 유지하지 않으면 과태료 1천만원 이하입니다.","현장실습생에 대한 특례 규정이 있다 (제166조의2)":"현장실습생에 대한 특례 규정이 제166조의2에 있습니다.","협의 과정에서 고용노동부장관이 규제 변경을 요구하면 행정기관의 장은 따라야 하고, 필요하면 고용노동부장관이 국무총리에게 협의·조정 사항을 보고해 확정할 수 있다":"협의 중 장관이 규제 변경을 요구하면 행정기관의 장이 따르고, 필요하면 국무총리에게 보고해 확정할 수 있습니다.","협의사항은 산업재해 예방방법·재해 시 대피방법 / 작업의 시작시간, 작업 및 작업장 간의 연락방법 / 그 밖의 산업재해 예방 관련 사항":"협의사항은 재해 예방방법과 대피방법, 작업 시작시간과 작업장 간 연락방법, 그 밖의 예방 관련 사항입니다.","협의체는 도급인 및 그의 수급인 전원으로 구성":"협의체 구성원은 도급인과 모든 수급인입니다.","협의체 협의사항: 작업의 시작 시간 / 작업 또는 작업장 간의 연락방법 / 재해발생 위험이 있는 경우 대피방법 / 작업장에서의 위험성평가의 실시에 관한 사항 / 사업주와 수급인 또는 수급인 상호 간의 연락 방법 및 작업공정의 조정":"협의체 협의사항은 작업 시작 시간, 작업장 간 연락방법, 재해 위험 시 대피방법, 위험성평가 실시, 작업공정의 조정입니다.","협의체 회의: 매월 1회 이상 정기적으로 개최하고 결과를 기록·보존":"협의체는 한 달에 한 번 이상 정기 회의를 열고 결과를 기록해 보존해야 합니다.","확인 주기: 2년에 1회 이상, 최근 3년 동안 취소·표시 사용금지·시정명령을 받은 사실이 없고 최근 2회 확인 결과 기술능력·생산체계가 기준 이상이면 3년에 1회 이상":"확인 주기는 2년에 1회 이상이고 최근 3년간 취소 등이 없고 최근 2회 확인 결과가 기준 이상이면 3년에 1회 이상으로 늘어납니다.","회의록 기재는 개최 일시 및 장소 / 출석위원 / 심의 내용 및 의결·결정 사항 / 그 밖의 토의사항, 보존 2년":"회의록에는 개최 일시와 장소, 출석위원, 심의 내용과 의결·결정 사항을 적고 2년간 보존합니다.","휴게시설: 모든 사업주가 휴게시설을 갖추어야 한다, 크기·위치·온도·조명 등 설치·관리기준 준수 대상은 상시근로자 20명 이상 사업장(건설업은 총공사금액 20억원 이상), 또는 전화상담원·요양보호사·간병인·돌봄 종사자·텔레마케터·배달원·청소 종사자·아파트 경비원·건물 경비원 2명 이상이 있는 상시근로자 10명 이상 20명 미만 사업장(건설업 제외)":"모든 사업주는 휴게시설을 갖춰야 하고 설치·관리기준 준수 대상은 상시근로자 20명 이상 사업장이거나 건설업 총공사금액 20억원 이상입니다.","휴대형 연마기·휴대형 연삭기는 자율안전확인 대상이 아니다":"휴대형 연마기와 휴대형 연삭기는 자율안전확인을 받을 필요가 없는 기계입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
